
// Image fallback (CSP-safe): inline image error handlers are blocked by the page CSP (script-src 'self'), so
// an icon/state-card image that fails to load would just show the browser's broken-image glyph. Images are
// marked with data-fallback="…" and swapped here via one capture-phase error listener (the error event
// doesn't bubble, so capture is required; guarded so a failing fallback can't loop).
document.addEventListener("error", (e) => {
  const t = e.target;
  if (!t || t.tagName !== "IMG" || !t.dataset) return;
  if (t.dataset.fallback && t.src.indexOf(t.dataset.fallback) < 0) { t.src = t.dataset.fallback; return; }
  // #inline-handlers-reintroduced — the hide half, which research.js has had since the CSP pass and these
  // listeners never gained. "visibility" keeps the element's box, which is what the inline handlers this
  // replaces were doing in the MIO lists; anything else removes it outright.
  if (t.dataset.hideOnError) {
    if (t.dataset.hideOnError === "visibility") t.style.visibility = "hidden";
    else t.style.display = "none";
  }
}, true);

let simActive = false;
let simCompletedFocuses = new Set();
let simCurrentFocusId = null;
let simCurrentProgress = 0;
let simDays = 0;
let simSpeed = 1;
let isPlaying = false;
let simInterval = null;
let simSnapshots = [];
let simCurrentSnapshotIndex = -1;
let simAnalysisCache = new Map();
let simSpiritsCache = new Map();
let globalMutexColorMap = new Map();
/** Focus-tree effects encountered during the run that the simulator does NOT project
 *  (conditional/scoped/random effects, tech unlocks, equipment, buildings, diplomacy, etc.).
 *  Surfaced honestly in the ledger so the user knows what isn't being modelled. */
let simNotSimulated = new Set();
/** Last "Run Full Path" projection: [{ day, id, title }]. */
let simLastTimeline = [];

/* ===========================================================================
   FOCUS-TREE SIMULATOR — effect engine
   Projects ONLY what a focus tree's completion_reward effects do to a country's
   ledger. Daily political power uses the documented HOI4 formula. Everything we
   can't faithfully model (conditionals, tech, equipment, buildings, diplomacy,
   ongoing non-PP spirit modifiers) is collected in simNotSimulated and shown to
   the user rather than silently dropped or faked.
   =========================================================================== */

/** Read a numeric ledger stat from its DOM cell, stripping % and commas. */
function getSimStat(id, fallback) {
  const el = document.getElementById(id);
  if (!el) return fallback;
  const n = parseFloat(String(el.textContent).replace(/[,%\s]/g, ""));
  return Number.isFinite(n) ? n : fallback;
}
function setSimStatText(id, text) {
  const el = document.getElementById(id);
  if (el) el.textContent = text;
}
function setSimPP(v) { setSimStatText("simValPP", (v).toFixed(1)); }
function setSimStability(v) { setSimStatText("simValStability", Math.max(0, Math.min(100, v)).toFixed(0) + "%"); }
function setSimWarSupport(v) { setSimStatText("simValWarSupport", Math.max(0, Math.min(100, v)).toFixed(0) + "%"); }
function setSimCommandPower(v) { setSimStatText("simValCP", Math.max(0, v).toFixed(0)); }
function setSimManpower(v) { setSimStatText("simValManpower", Math.max(0, Math.round(v)).toLocaleString()); }
function setSimResearchSlots(v) { setSimStatText("simValResearchSlots", Math.max(0, Math.round(v)).toString()); }

/** Current stability as a 0..1 fraction (ledger stores it as a percent). */
function getSimStabilityFraction() {
  return Math.max(0, Math.min(100, getSimStat("simValStability", 50))) / 100;
}

/** Sum political-power daily-rate modifiers across the active national spirits. */
function collectActiveSpiritPpModifiers() {
  let ppFactor = 0, ppGain = 0;
  const list = document.getElementById("simSpiritsList");
  if (!list) return { ppFactor, ppGain };
  Array.from(list.querySelectorAll(".sim-spirit-item")).forEach(el => {
    const det = simSpiritsCache.get(el.dataset.ideaId);
    if (det && Array.isArray(det.modifiers)) {
      det.modifiers.forEach(m => {
        const idx = m.indexOf("=");
        if (idx === -1) return;
        const k = m.slice(0, idx).trim();
        const v = parseFloat(m.slice(idx + 1)) || 0;
        if (k === "political_power_factor") ppFactor += v;
        else if (k === "political_power_gain") ppGain += v;
      });
    }
  });
  return { ppFactor, ppGain };
}

/** Daily political-power gain, HOI4-accurate for the focus-tree scope.
 *  Base +2.0/day (Regular difficulty) + flat political_power_gain spirit modifiers,
 *  scaled by (1 + Σ political_power_factor), then by the stability multiplier:
 *  +20% at 100% stability, neutral at 50%, -50% at 0% (per the wiki). War support
 *  does NOT affect PP gain. Difficulty/party-popularity contributions are out of
 *  scope (not focus-tree effects) and are disclaimed in the ledger. */
function getDailyPpGain() {
  const BASE = 2.0;
  const stab = getSimStabilityFraction();
  const stabMult = stab >= 0.5 ? 1 + (stab - 0.5) * 0.4 : 1 + (stab - 0.5) * 1.0;
  const { ppFactor, ppGain } = collectActiveSpiritPpModifiers();
  return (BASE + ppGain) * (1 + ppFactor) * stabMult;
}

/** Add one day's political power to the ledger. */
function addSimDailyPp() {
  setSimPP(getSimStat("simValPP", 150) + getDailyPpGain());
}

/** Remove a national spirit from the ledger by idea id. */
function removeSimSpirit(ideaId) {
  const list = document.getElementById("simSpiritsList");
  if (!list) return;
  const item = list.querySelector(`[data-idea-id="${ideaId}"]`);
  if (item) item.remove();
  if (!list.querySelector(".sim-spirit-item")) {
    list.innerHTML = '<div class="sim-empty-text">No active spirits</div>';
  }
}

/** Add a country flag badge to the ledger. */
function addSimFlag(flag) {
  const list = document.getElementById("simFlagsList");
  if (!list || !flag) return;
  const empty = list.querySelector(".sim-empty-text");
  if (empty) empty.remove();
  const exists = Array.from(list.querySelectorAll(".sim-flag-badge")).some(b => b.textContent.trim() === flag);
  if (exists) return;
  const badge = document.createElement("div");
  badge.className = "sim-flag-badge";
  badge.textContent = flag;
  list.appendChild(badge);
}

/** Tokenise a Paradox-script effect body into top-level { key, op, value, block }
 *  statements. Brace-aware so nested blocks (add_timed_idea, swap_ideas,
 *  hidden_effect, if/limit, …) are captured whole. */
function tokenizeEffectScript(text) {
  const out = [];
  if (!text) return out;
  const n = text.length;
  let i = 0;
  const isBreak = (c) => c === " " || c === "\t" || c === "\r" || c === "\n" || c === "{" || c === "}" || c === "=" || c === "<" || c === ">" || c === "#";
  function skipWs() {
    while (i < n) {
      const c = text[i];
      if (c === "#") { while (i < n && text[i] !== "\n") i++; }
      else if (c === " " || c === "\t" || c === "\r" || c === "\n") i++;
      else break;
    }
  }
  function readWord() {
    skipWs();
    if (i >= n) return null;
    const c = text[i];
    if (c === "{" || c === "}" || c === "=" || c === "<" || c === ">") { i++; return c; }
    if (c === '"') { let j = i + 1; while (j < n && text[j] !== '"') j++; const t = text.slice(i + 1, j); i = j + 1; return t; }
    let j = i;
    while (j < n && !isBreak(text[j])) j++;
    const t = text.slice(i, j); i = j; return t;
  }
  function readBlockRaw() {
    // i is at "{"; return inner text and advance past the matching "}"
    let depth = 0, start = i, j = i;
    while (j < n) {
      const c = text[j];
      if (c === "{") depth++;
      else if (c === "}") { depth--; if (depth === 0) { j++; break; } }
      j++;
    }
    const inner = text.slice(start + 1, Math.max(start + 1, j - 1));
    i = j; return inner;
  }
  let guard = 100000;
  while (guard-- > 0) {
    skipWs();
    if (i >= n) break;
    let key = readWord();
    if (key === null) break;
    if (key === "}" || key === "{" || key === "=" || key === "<" || key === ">") continue;
    skipWs();
    let op = "=";
    if (text[i] === "=" || text[i] === "<" || text[i] === ">") { op = readWord(); }
    skipWs();
    if (text[i] === "{") {
      const block = readBlockRaw();
      out.push({ key, op, value: null, block });
    } else {
      const value = readWord();
      out.push({ key, op, value, block: null });
    }
  }
  return out;
}

/** Pull the idea id(s) from an add_ideas / remove_ideas argument (single token,
 *  or a { a b c } / { idea = x } block). */
function extractIdeaIds(stmt) {
  if (stmt.value) return [stmt.value];
  if (!stmt.block) return [];
  const ids = [];
  tokenizeEffectScript(stmt.block).forEach(s => {
    if (s.key === "idea" && s.value) ids.push(s.value);
    else if (!s.value && !s.block && s.key && s.op === "=") { /* skip */ }
  });
  // bare-token list form: { idea_a idea_b }
  if (ids.length === 0) {
    stmt.block.split(/\s+/).map(t => t.trim()).filter(t => t && t !== "=").forEach(t => ids.push(t));
  }
  return ids;
}

/** A pretty label for an effect command in the "not projected here" list. */
function prettyEffectKey(key) {
  return String(key || "").replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
}

/** Apply a focus's completion_reward effect script to the ledger. Recognised
 *  instant country-scope effects mutate the stats; everything else is recorded
 *  in simNotSimulated. Recurses into hidden_effect blocks. */
function applyFocusEffectScript(text, depth) {
  depth = depth || 0;
  if (depth > 6) return;
  const statements = tokenizeEffectScript(text);
  statements.forEach(stmt => {
    const key = stmt.key;
    const num = parseFloat(stmt.value);
    const hasNum = Number.isFinite(num);
    switch (key) {
      case "add_political_power":
        if (hasNum) setSimPP(getSimStat("simValPP", 150) + num); break;
      case "add_stability":
        if (hasNum) setSimStability(getSimStat("simValStability", 50) + num * 100); break;
      case "set_stability":
        if (hasNum) setSimStability(num * 100); break;
      case "add_war_support":
        if (hasNum) setSimWarSupport(getSimStat("simValWarSupport", 50) + num * 100); break;
      case "set_war_support":
        if (hasNum) setSimWarSupport(num * 100); break;
      case "add_command_power":
      case "add_command_power_to_pool":
        if (hasNum) setSimCommandPower(getSimStat("simValCP", 0) + num); break;
      case "add_manpower":
        if (hasNum) setSimManpower(getSimStat("simValManpower", 0) + num); break;
      case "add_research_slot":
        if (hasNum) setSimResearchSlots(getSimStat("simValResearchSlots", 3) + num); break;
      case "set_research_slots":
        if (hasNum) setSimResearchSlots(num); break;
      case "army_experience":
      case "add_army_experience":
        if (hasNum) setSimStatText("simValArmyXp", (getSimStat("simValArmyXp", 0) + num).toFixed(0)); break;
      case "navy_experience":
      case "add_navy_experience":
        if (hasNum) setSimStatText("simValNavyXp", (getSimStat("simValNavyXp", 0) + num).toFixed(0)); break;
      case "air_experience":
      case "add_air_experience":
        if (hasNum) setSimStatText("simValAirXp", (getSimStat("simValAirXp", 0) + num).toFixed(0)); break;
      case "add_ideas":
        extractIdeaIds(stmt).forEach(id => addSimSpirit(id)); break;
      case "add_timed_idea": {
        const ids = extractIdeaIds(stmt);
        ids.forEach(id => addSimSpirit(id));
        if (ids.length) simNotSimulated.add("Timed spirit — kept active (expiry not modelled)");
        break;
      }
      case "remove_ideas":
      case "remove_ideas_with_trait":
        extractIdeaIds(stmt).forEach(id => removeSimSpirit(id)); break;
      case "swap_ideas": {
        const toks = tokenizeEffectScript(stmt.block || "");
        toks.forEach(s => {
          if (s.key === "remove_idea" && s.value) removeSimSpirit(s.value);
          if (s.key === "add_idea" && s.value) addSimSpirit(s.value);
        });
        break;
      }
      case "set_country_flag":
        addSimFlag(stmt.value || (stmt.block ? (tokenizeEffectScript(stmt.block).find(s => s.key === "flag") || {}).value : null)); break;
      case "hidden_effect":
        if (stmt.block) applyFocusEffectScript(stmt.block, depth + 1); break;
      case "add_nuke":
        simNotSimulated.add("Nuclear bombs (no ledger stat)"); break;
      default:
        // Unknown / out-of-scope: record once so the user knows it fires in-game.
        // Only real command identifiers — skip stray numbers/punctuation that can
        // surface from inside blocks we don't recurse, and pure-tooltip commands.
        if (key && /^[a-zA-Z][a-zA-Z0-9_]*$/.test(key) &&
            !/^(log|custom_effect_tooltip|tooltip|effect_tooltip)$/.test(key)) {
          simNotSimulated.add(prettyEffectKey(key));
        }
    }
  });
}

/** Mark a focus complete and apply its effects (shared by manual step + auto-run). */
function completeSimFocus(focus) {
  if (!focus) return;
  simCompletedFocuses.add(focus.id);
  const rewards = pendingEffectEdits.get(focus.id) || focus.reward || [];
  const text = Array.isArray(rewards) ? rewards.join("\n") : String(rewards || "");
  applyFocusEffectScript(text, 0);
  simCurrentFocusId = null;
  simCurrentProgress = 0;
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function getSimDateString(days) {
  let date = new Date(1936, 0, 1);
  date.setDate(date.getDate() + days);
  return `${date.getDate()} ${MONTHS[date.getMonth()]}, ${date.getFullYear()}`;
}

// #prereq-or-group-evaluated-as-and — A BLOCK IS ONE REQUIREMENT; IDS INSIDE IT ARE ALTERNATIVES.
//
// HOI4 reads several `focus =` entries inside ONE `prerequisite = { }` block as an OR, and separate
// blocks as an AND. collectFocusPrerequisiteGroups already parses them into that shape, and the comment
// beside the prerequisite WRITER already states the rule — this evaluator was the caller that never
// adopted it, flattening every block into one list and requiring all of them.
//
// Alternatives are usually mutually exclusive (pick this path or that one), so under AND they could never
// all complete and the focus was locked forever. Measured: 884 of vanilla's 10,608 focuses and 986 of
// Millennium Dawn's 22,017 were permanently unreachable — one MD focus offers a choice of twelve.
//
// All three consumers were wrong together: Run Full Path skipped these focuses, clicking one answered
// "Prerequisites not completed…", and the canvas drew them greyscale.
// #prereq-groups-go-stale — DERIVE THE GROUPS THE WAY THE WRITER DOES, FROM THE LIVE ID LIST.
//
// `prerequisiteGroups` is set once, by the parser, and never updated again. Everything that edits
// prerequisites afterwards touches `focus.prerequisites` only: linking a parent pushes to it, unlinking
// filters it, and the delete and rename passes rewrite it. So reading the groups directly means reading
// what the file said when it was OPENED, not what it says now:
//   · link a new parent   -> not in any group -> the simulator ignored a prerequisite the file has
//   · unlink one          -> still in its group -> the simulator still demanded it
//   · rename or delete it -> the group keeps the OLD id, which nothing can ever complete, so the focus
//     was locked forever — the very failure the OR-group fix existed to remove, reintroduced for any
//     tree the user had actually edited.
//
// rebuildFocusPrerequisiteSection already solves this: it filters each group against the live ids, drops
// a group left empty, and gives anything ungrouped a block of its own (an AND). Deriving the same way
// here keeps the simulator agreeing with the file that is about to be written, by construction.
function arePrereqsCompleted(focus, completedSet) {
  const refs = Array.isArray(focus.prerequisites) ? focus.prerequisites : [];
  if (!refs.length) return true;
  const grouped = Array.isArray(focus.prerequisiteGroups) ? focus.prerequisiteGroups : null;
  const groups = [];
  const placed = new Set();
  if (grouped && grouped.length) {
    for (const g of grouped) {
      // Dedupe PER GROUP, not globally: `(A or C) and (B or C)` is a real shape — Millennium Dawn's
      // LBA_approach_france is exactly that — and dropping C from the second group changes its meaning.
      const withinGroup = new Set();
      const kept = (Array.isArray(g) ? g : []).filter((id) => {
        if (!refs.includes(id) || withinGroup.has(id)) return false;
        withinGroup.add(id);
        placed.add(id);
        return true;
      });
      if (kept.length) groups.push(kept);
    }
  }
  // Anything with no group of its own is its own requirement — an AND, which is what the writer emits
  // for it and what the editor's status line promises when you link a parent ("required first").
  for (const id of refs) if (!placed.has(id)) groups.push([id]);
  if (!groups.length) return true;
  // Several ids in ONE block are alternatives (OR); separate blocks are all required (AND).
  return groups.every((ids) => ids.some((pid) => completedSet.has(pid)));
}

function isMutexCompleted(focus, completedSet) {
  if (!focus.mutuallyExclusive || focus.mutuallyExclusive.length === 0) return false;
  return focus.mutuallyExclusive.some(oid => completedSet.has(oid));
}

function saveSimSnapshot() {
  if (simCurrentSnapshotIndex !== -1 && simCurrentSnapshotIndex < simSnapshots.length - 1) {
    simSnapshots = simSnapshots.slice(0, simCurrentSnapshotIndex + 1);
  }
  const snapshot = {
    days: simDays,
    completedFocuses: new Set(simCompletedFocuses),
    currentFocusId: simCurrentFocusId,
    currentProgress: simCurrentProgress,
    politicalPower: parseFloat(document.getElementById("simValPP")?.textContent || "150") || 150,
    stability: parseFloat(document.getElementById("simValStability")?.textContent || "50") || 50,
    warSupport: parseFloat(document.getElementById("simValWarSupport")?.textContent || "50") || 50,
    commandPower: parseFloat(document.getElementById("simValCP")?.textContent || "0") || 0,
    manpower: getSimStat("simValManpower", 0),
    researchSlots: getSimStat("simValResearchSlots", 3),
    armyXp: parseFloat(document.getElementById("simValArmyXp")?.textContent || "0") || 0,
    navyXp: parseFloat(document.getElementById("simValNavyXp")?.textContent || "0") || 0,
    airXp: parseFloat(document.getElementById("simValAirXp")?.textContent || "0") || 0,
    activeSpirits: Array.from(document.getElementById("simSpiritsList")?.querySelectorAll(".sim-spirit-item") || []).map(el => el.dataset.ideaId).filter(Boolean),
    activeFlags: Array.from(document.getElementById("simFlagsList")?.querySelectorAll(".sim-flag-badge") || []).map(el => el.textContent.trim()).filter(Boolean),
    notSimulated: Array.from(simNotSimulated)
  };
  simSnapshots.push(snapshot);
  simCurrentSnapshotIndex = simSnapshots.length - 1;
  const scrubber = document.getElementById("simScrubber");
  const label = document.getElementById("simScrubberLabel");
  if (scrubber) {
    scrubber.max = simSnapshots.length - 1;
    scrubber.value = simSnapshots.length - 1;
  }
  if (label) {
    label.textContent = `${simSnapshots.length} / ${simSnapshots.length}`;
  }
}

async function getOrFetchSimSpiritDetails(ideaId, callback) {
  if (simSpiritsCache.has(ideaId)) {
    callback(simSpiritsCache.get(ideaId));
    return;
  }
  try {
    // …and say WHICH mod. With no modPath the endpoint falls back to the persisted active mod, which is not
    // necessarily the one open in this editor — measured, that made even the mod's OWN spirits come back
    // "not found". The endpoint then searches mod -> dependencies -> game, so an inherited spirit (which on
    // an add-on is nearly every spirit a focus grants) resolves too. #simulator-cannot-see-inherited-spirits
    const simRoot = encodeURIComponent(String(getActiveModPath() || ""));
    const res = await fetch(`/api/ideas/entry-preview?ideaId=${encodeURIComponent(ideaId)}&modPath=${simRoot}`);
    const payload = await res.json();
    if (payload.ok) {
      const blockRes = await fetch(`/api/ideas/entry-block?ideaId=${encodeURIComponent(ideaId)}&modPath=${simRoot}`);
      const blockPayload = await blockRes.json();
      const modifiers = [];
      if (blockPayload.ok && blockPayload.blockText) {
        const modMatch = blockPayload.blockText.match(/modifier\s*=\s*\{([^}]*)\}/s);
        if (modMatch) {
          const lines = modMatch[1].split(/\r?\n/);
          lines.forEach(line => {
            const cleaned = line.trim();
            if (cleaned && !cleaned.startsWith("#") && cleaned.includes("=")) {
              modifiers.push(cleaned);
            }
          });
        }
      }
      const details = {
        pictureToken: payload.pictureToken || "generic",
        modifiers
      };
      simSpiritsCache.set(ideaId, details);
      callback(details);
    } else {
      const details = { pictureToken: "generic", modifiers: [] };
      simSpiritsCache.set(ideaId, details);
      callback(details);
    }
  } catch (err) {
    console.error("Failed to fetch spirit details:", err);
    const details = { pictureToken: "generic", modifiers: [] };
    simSpiritsCache.set(ideaId, details);
    callback(details);
  }
}

function renderSimSpiritItem(id) {
  const item = document.createElement("div");
  item.className = "sim-spirit-item";
  item.dataset.ideaId = id;
  item.style.display = "flex";
  item.style.alignItems = "flex-start";
  item.style.padding = "6px 8px";
  item.style.background = "rgba(255, 255, 255, 0.03)";
  item.style.border = "1px solid rgba(255, 255, 255, 0.05)";
  item.style.borderRadius = "4px";
  item.style.marginBottom = "4px";

  const img = document.createElement("img");
  img.className = "sim-spirit-icon";
  img.style.width = "28px";
  img.style.height = "28px";
  img.style.objectFit = "contain";
  img.style.marginRight = "8px";
  img.style.marginTop = "2px";
  img.style.flexShrink = "0";
  img.src = "https://raw.githubusercontent.com/pdx-tools/hoi4-assets/main/ui/idea_default.png";
  item.appendChild(img);

  const rightCol = document.createElement("div");
  rightCol.style.display = "flex";
  rightCol.style.flexDirection = "column";
  rightCol.style.flex = "1";
  item.appendChild(rightCol);

  const title = document.createElement("div");
  title.className = "sim-spirit-title";
  title.style.fontWeight = "600";
  title.style.fontSize = "12px";
  title.style.color = "#fff";
  title.textContent = id;
  rightCol.appendChild(title);

  const modContainer = document.createElement("div");
  modContainer.className = "sim-spirit-modifiers";
  modContainer.style.fontSize = "10px";
  modContainer.style.color = "#8b949e";
  modContainer.style.marginTop = "2px";
  rightCol.appendChild(modContainer);

  getOrFetchSimSpiritDetails(id, (details) => {
    const pic = details.pictureToken || "generic";
    img.src = `/api/icon?key=GFX_idea_${encodeURIComponent(pic)}`;
    if (details.modifiers && details.modifiers.length > 0) {
      modContainer.innerHTML = details.modifiers.map(m => `<div style="margin-top: 1px;">• ${translateHoi4ToEnglish(m)}</div>`).join("");
    } else {
      modContainer.innerHTML = `<div style="font-style: italic; opacity: 0.6;">No modifiers</div>`;
    }
  });

  return item;
}

function loadSimSnapshot(index) {
  const snapshot = simSnapshots[index];
  if (!snapshot) return;
  simCurrentSnapshotIndex = index;
  simDays = snapshot.days;
  simCompletedFocuses = new Set(snapshot.completedFocuses);
  simCurrentFocusId = snapshot.currentFocusId;
  simCurrentProgress = snapshot.currentProgress;
  
  const ppEl = document.getElementById("simValPP");
  if (ppEl) ppEl.textContent = snapshot.politicalPower.toFixed(1);
  const stabEl = document.getElementById("simValStability");
  if (stabEl) stabEl.textContent = snapshot.stability.toFixed(0) + "%";
  const wsEl = document.getElementById("simValWarSupport");
  if (wsEl) wsEl.textContent = snapshot.warSupport.toFixed(0) + "%";
  const cpEl = document.getElementById("simValCP");
  if (cpEl) cpEl.textContent = snapshot.commandPower.toFixed(0);
  setSimManpower(typeof snapshot.manpower === "number" ? snapshot.manpower : 0);
  setSimResearchSlots(typeof snapshot.researchSlots === "number" ? snapshot.researchSlots : 3);
  simNotSimulated = new Set(Array.isArray(snapshot.notSimulated) ? snapshot.notSimulated : []);
  const axpEl = document.getElementById("simValArmyXp");
  if (axpEl) axpEl.textContent = snapshot.armyXp.toFixed(0);
  const nxpEl = document.getElementById("simValNavyXp");
  if (nxpEl) nxpEl.textContent = snapshot.navyXp.toFixed(0);
  const aixpEl = document.getElementById("simValAirXp");
  if (aixpEl) aixpEl.textContent = snapshot.airXp.toFixed(0);
  
  const spiritsList = document.getElementById("simSpiritsList");
  if (spiritsList) {
    spiritsList.innerHTML = "";
    if (snapshot.activeSpirits.length === 0) {
      spiritsList.innerHTML = '<div class="sim-empty-text">No active spirits</div>';
    } else {
      snapshot.activeSpirits.forEach(id => {
        spiritsList.appendChild(renderSimSpiritItem(id));
      });
    }
  }
  
  const flagsList = document.getElementById("simFlagsList");
  if (flagsList) {
    flagsList.innerHTML = "";
    if (snapshot.activeFlags.length === 0) {
      flagsList.innerHTML = '<div class="sim-empty-text">No active flags</div>';
    } else {
      snapshot.activeFlags.forEach(flag => {
        const item = document.createElement("div");
        item.className = "sim-flag-badge";
        item.textContent = flag;
        flagsList.appendChild(item);
      });
    }
  }
  
  const dateEl = document.getElementById("simDateDisplay");
  if (dateEl) dateEl.textContent = getSimDateString(simDays);
  const label = document.getElementById("simScrubberLabel");
  if (label) label.textContent = `${index + 1} / ${simSnapshots.length}`;

  updateSimUi();
  updateAllNodesVisualOnly();
}

function addSimSpirit(ideaId) {
  const list = document.getElementById("simSpiritsList");
  if (!list) return;
  const empty = list.querySelector(".sim-empty-text");
  if (empty) empty.remove();
  if (list.querySelector(`[data-idea-id="${ideaId}"]`)) return;
  list.appendChild(renderSimSpiritItem(ideaId));
}

/** Render the "applies in-game — not projected here" list and the projected
 *  full-path timeline in the ledger. */
function renderSimNotSimulated() {
  const list = document.getElementById("simNotSimulatedList");
  if (list) {
    const items = Array.from(simNotSimulated).sort();
    if (items.length === 0) {
      list.innerHTML = '<div class="sim-empty-text">Nothing skipped yet — completed focuses only had projectable effects.</div>';
    } else {
      list.innerHTML = items.map(t => `<div class="sim-notsim-item">• ${t}</div>`).join("");
    }
  }
  const tl = document.getElementById("simTimelineList");
  const tlSection = document.getElementById("simTimelineSection");
  if (tl && tlSection) {
    if (!simLastTimeline || simLastTimeline.length === 0) {
      tlSection.style.display = "none";
    } else {
      tlSection.style.display = "";
      const last = simLastTimeline[simLastTimeline.length - 1];
      const totalDays = last ? last.day : 0;
      const yrs = (totalDays / 365);
      tl.innerHTML =
        `<div class="sim-timeline-summary">${simLastTimeline.length} focuses · ${totalDays} days (~${yrs.toFixed(1)} yr) · finishes ${getSimDateString(totalDays)}</div>` +
        simLastTimeline.map(t => `<div class="sim-timeline-item"><span class="sim-timeline-day">${getSimDateString(t.day)}</span><span class="sim-timeline-title">${t.title}</span></div>`).join("");
    }
  }
}

// #falsy-zero — A FOCUS MAY LEGITIMATELY COST 0, AND 0 IS FALSY.
//
// An instant focus is legal HOI4 and shipping content is full of them: vanilla 22 `cost = 0` lines,
// Millennium Dawn 12, Rise of Nations 19. `focus.cost || 10` reads every one of those as "absent" and
// substitutes the ten-week default, so the simulator ran an instant focus for 70 days — the halo filled,
// the current-focus widget counted down, and every later focus in the plan slipped by ten weeks.
//
// Nova already fixed this twice, in the sidebar loader and in the serializer, each with a comment saying
// exactly why. The simulator's four sites never adopted it. One helper now, so there is no fifth.
function simFocusCostWeeks(focus) {
  const raw = focus && focus.cost;
  if (raw === undefined || raw === null || raw === "" || !Number.isFinite(Number(raw))) return 10;
  return Number(raw);
}
function simFocusTotalDays(focus) { return simFocusCostWeeks(focus) * 7; }

function updateSimUi() {
  const display = document.getElementById("simDateDisplay");
  if (display) display.textContent = getSimDateString(simDays);

  const deltaEl = document.getElementById("simDeltaPP");
  if (deltaEl) deltaEl.textContent = "+" + getDailyPpGain().toFixed(1) + "/d";

  renderSimNotSimulated();

  const widget = document.getElementById("simCurrentFocusDisplay");
  if (widget) {
    if (simCurrentFocusId && parsed && Array.isArray(parsed.focuses)) {
      const focus = parsed.focuses.find(f => f.id === simCurrentFocusId);
      if (focus) {
        const title = stripLocDisplayCodes((window.localizationMap && window.localizationMap[focus.id]) || focus.displayName || focus.id);
        const total = simFocusTotalDays(focus);
        const percent = Math.min(100, Math.floor((simCurrentProgress / total) * 100));
        widget.innerHTML = `
          <div class="sim-current-focus-title" style="margin-bottom: 4px;">${title}</div>
          <div class="sim-current-focus-progress-bar-container" style="margin-bottom: 6px;">
            <div class="sim-current-focus-progress-bar" style="width: ${percent}%;"></div>
          </div>
          <div class="sim-current-focus-progress-text">
            <span>Researching</span>
            <span>${simCurrentProgress} / ${total} days (${percent}%)</span>
          </div>
        `;
      } else {
        widget.innerHTML = `<div class="sim-empty-text">Unknown Active Focus ID: ${simCurrentFocusId}</div>`;
      }
    } else {
      widget.innerHTML = `
        <div class="sim-empty-text" style="color: #58a6ff; font-weight: 500; font-style: normal; display: flex; flex-direction: column; gap: 6px;">
          <span>No focus selected for simulation.</span>
          <span style="font-size: 10px; color: #8b949e; line-height: 1.4;">👉 Click any glowing blue focus node in the tree to start researching it.</span>
        </div>
      `;
    }
  }
}

function updateAllNodesVisualOnly() {
  if (!parsed || !Array.isArray(parsed.focuses)) return;
  const nodes = document.querySelectorAll(".node");
  nodes.forEach(node => {
    const focusId = node.dataset.focusId;
    const focus = parsed.focuses.find(f => f.id === focusId);
    if (focus) {
      updateFocusNodeVisual(node, focus, parseInt(node.dataset.index, 10), globalMutexColorMap);
    }
  });
}

function startSimLoop() {
  if (simInterval) clearInterval(simInterval);
  const msPerDay = simSpeed === 1 ? 1000 : (simSpeed === 2 ? 500 : 200);
  simInterval = setInterval(() => {
    tickSimDay();
  }, msPerDay);
}

function stopSimLoop() {
  if (simInterval) {
    clearInterval(simInterval);
    simInterval = null;
  }
}

function toggleSimPlay() {
  const btn = document.getElementById("simPlayBtn");
  if (!btn) return;
  isPlaying = !isPlaying;
  if (isPlaying) {
    btn.textContent = "⏸";
    startSimLoop();
  } else {
    btn.textContent = "▶";
    stopSimLoop();
  }
}

function tickSimDay() {
  simDays += 1;
  addSimDailyPp();

  if (simCurrentFocusId && parsed && Array.isArray(parsed.focuses)) {
    const focus = parsed.focuses.find(f => f.id === simCurrentFocusId);
    if (focus) {
      simCurrentProgress += 1;
      const totalCost = simFocusTotalDays(focus);
      if (simCurrentProgress >= totalCost) {
        completeSimFocus(focus);
      }
    }
  }

  saveSimSnapshot();
  updateSimUi();
  updateAllNodesVisualOnly();
}

/** Auto-run: complete every reachable focus in prerequisite/mutex order, day by
 *  day, accumulating political power and applying each focus's effects. Produces
 *  a projected timeline. Keeps manual stepping available; this is the "run the
 *  whole path" mode. */
function runFullPath() {
  if (!parsed || !Array.isArray(parsed.focuses) || parsed.focuses.length === 0) return;
  stopSimLoop();
  isPlaying = false;
  const playBtn = document.getElementById("simPlayBtn");
  if (playBtn) playBtn.textContent = "▶";

  simLastTimeline = [];
  let guard = parsed.focuses.length + 2;
  while (guard-- > 0) {
    let focus = null;
    if (simCurrentFocusId) {
      focus = parsed.focuses.find(f => f.id === simCurrentFocusId);
    }
    if (!focus) {
      focus = parsed.focuses.find(f =>
        !simCompletedFocuses.has(f.id) &&
        arePrereqsCompleted(f, simCompletedFocuses) &&
        !isMutexCompleted(f, simCompletedFocuses));
      if (!focus) break;
      simCurrentFocusId = focus.id;
    }
    const total = simFocusTotalDays(focus);
    let safety = total + 2;
    while (simCurrentProgress < total && safety-- > 0) {
      simDays += 1;
      addSimDailyPp();
      simCurrentProgress += 1;
    }
    completeSimFocus(focus);
    const title = stripLocDisplayCodes((window.localizationMap && window.localizationMap[focus.id]) || focus.displayName || focus.id);
    simLastTimeline.push({ day: simDays, id: focus.id, title });
    saveSimSnapshot();
  }

  updateSimUi();
  updateAllNodesVisualOnly();
}

/** Reset the simulation back to its 1 Jan 1936 baseline (generic starting stats). */
function resetSim() {
  stopSimLoop();
  isPlaying = false;
  const playBtn = document.getElementById("simPlayBtn");
  if (playBtn) playBtn.textContent = "▶";
  simDays = 0;
  simCompletedFocuses = new Set();
  simCurrentFocusId = null;
  simCurrentProgress = 0;
  simSnapshots = [];
  simCurrentSnapshotIndex = -1;
  simNotSimulated = new Set();
  simLastTimeline = [];
  setSimPP(150);
  setSimStability(50);
  setSimWarSupport(50);
  setSimCommandPower(0);
  setSimManpower(0);
  setSimResearchSlots(3);
  setSimStatText("simValArmyXp", "0");
  setSimStatText("simValNavyXp", "0");
  setSimStatText("simValAirXp", "0");
  const spiritsList = document.getElementById("simSpiritsList");
  if (spiritsList) spiritsList.innerHTML = '<div class="sim-empty-text">No active spirits</div>';
  const flagsList = document.getElementById("simFlagsList");
  if (flagsList) flagsList.innerHTML = '<div class="sim-empty-text">No active flags</div>';
  saveSimSnapshot();
  updateSimUi();
  updateAllNodesVisualOnly();
}

function wireSimulatorUi() {
  const simToggleBtn = document.getElementById("simToggleBtn");
  const simHud = document.getElementById("simHud");
  const simLedger = document.getElementById("simLedger");
  if (!simToggleBtn) return;
  simToggleBtn.onclick = (e) => {
    e.preventDefault();
    simActive = !simActive;
    if (simActive) {
      simToggleBtn.classList.add("debug-toggle-btn--active");
      if (simHud) simHud.classList.remove("sim-hidden");
      if (simLedger) simLedger.classList.remove("sim-hidden");
      if (simSnapshots.length === 0) {
        simNotSimulated = new Set();
        simLastTimeline = [];
        saveSimSnapshot();
      }
      updateSimUi();
    } else {
      simToggleBtn.classList.remove("debug-toggle-btn--active");
      if (simHud) simHud.classList.add("sim-hidden");
      if (simLedger) simLedger.classList.add("sim-hidden");
      stopSimLoop();
      isPlaying = false;
      const playBtn = document.getElementById("simPlayBtn");
      if (playBtn) playBtn.textContent = "▶";
    }
    renderFocuses();
  };
  
  const playBtn = document.getElementById("simPlayBtn");
  if (playBtn) {
    playBtn.onclick = () => toggleSimPlay();
  }
  
  const stepBtn = document.getElementById("simStepBtn");
  if (stepBtn) {
    stepBtn.onclick = () => {
      stopSimLoop();
      isPlaying = false;
      if (playBtn) playBtn.textContent = "▶";
      tickSimDay();
    };
  }

  const runPathBtn = document.getElementById("simRunPathBtn");
  if (runPathBtn) {
    runPathBtn.onclick = () => {
      runPathBtn.disabled = true;
      const old = runPathBtn.textContent;
      runPathBtn.textContent = "Running…";
      // Defer so the button repaint lands before the (synchronous) projection.
      setTimeout(() => {
        try { runFullPath(); } finally {
          runPathBtn.disabled = false;
          runPathBtn.textContent = old;
        }
      }, 16);
    };
  }

  const resetBtn = document.getElementById("simResetBtn");
  if (resetBtn) {
    resetBtn.onclick = () => resetSim();
  }

  const speedBtn = document.getElementById("simSpeedBtn");
  if (speedBtn) {
    speedBtn.onclick = () => {
      if (simSpeed === 1) {
        simSpeed = 2;
        speedBtn.textContent = "2x";
      } else if (simSpeed === 2) {
        simSpeed = 3;
        speedBtn.textContent = "5x";
      } else {
        simSpeed = 1;
        speedBtn.textContent = "1x";
      }
      if (isPlaying) {
        startSimLoop();
      }
    };
  }
  
  const scrubber = document.getElementById("simScrubber");
  if (scrubber) {
    scrubber.oninput = (e) => {
      stopSimLoop();
      isPlaying = false;
      if (playBtn) playBtn.textContent = "▶";
      loadSimSnapshot(parseInt(e.target.value, 10));
    };
  }
}

let isAutoExpandEnabled = true;

function ensureCanvasSpace(canvasX, canvasY) {
  if (!isAutoExpandEnabled) return;
  const padding = 500;
  const currentW = parseInt(canvasEl.style.minWidth || "0", 10);
  const currentH = parseInt(canvasEl.style.minHeight || "0", 10);
  
  if (canvasX + padding > currentW) {
    const nextW = canvasX + padding;
    canvasEl.style.minWidth = nextW + "px";
    lineLayerEl.setAttribute("width", String(nextW));
    lineLayerEl.style.width = nextW + "px";
  }
  if (canvasY + padding > currentH) {
    const nextH = canvasY + padding;
    canvasEl.style.minHeight = nextH + "px";
    lineLayerEl.setAttribute("height", String(nextH));
    lineLayerEl.style.height = nextH + "px";
  }
}

