function stripOnePairOuterQuotes(s) {
  const t = String(s || "").trim();
  if (t.length < 2) return t;
  const a = t[0];
  const b = t[t.length - 1];
  if ((a === '"' && b === '"') || (a === "'" && b === "'")) {
    return t.slice(1, -1).trim();
  }
  return t;
}

function escapeHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function getActiveModPath() {
  return localStorage.getItem("activeModPath") || "";
}

function modPathHasParentSegment(p) {
  const t = String(p || "").trim();
  if (!t) return false;
  const norm = t.replace(/\\/g, "/").replace(/\/+/g, "/");
  return norm.split("/").some((seg) => seg === "..");
}

function setEffectAmountVerifyUiBusy(busy) {
  if (effectAmountApplyBtn) {
    effectAmountApplyBtn.disabled = Boolean(busy);
    effectAmountApplyBtn.textContent = busy ? "Verifying…" : EFFECT_AMOUNT_APPLY_LABEL;
    if (busy) effectAmountApplyBtn.setAttribute("aria-busy", "true");
    else effectAmountApplyBtn.removeAttribute("aria-busy");
  }
  if (effectAmountPairModeBtn) {
    effectAmountPairModeBtn.disabled = Boolean(busy);
  }
  if (effectAmountFormEl) {
    if (busy) effectAmountFormEl.setAttribute("aria-busy", "true");
    else effectAmountFormEl.removeAttribute("aria-busy");
  }
  if (effectAmountDialogEl) {
    effectAmountDialogEl.classList.toggle("effect-amount-dialog--verifying", Boolean(busy));
    effectAmountDialogEl.style.cursor = busy ? "wait" : "";
  }
  if (effectAmountCancelBtn) {
    const preset =
      effectAmountState && effectAmountState.presetKey
        ? EFFECT_PRESETS[effectAmountState.presetKey]
        : null;
    const ideaFlow = preset && preset.requiresIdeaModFolder;
    if (busy && ideaFlow) {
      effectAmountCancelBtn.title =
        "Close without applying. An in-flight check from this dialog will be ignored.";
    } else {
      effectAmountCancelBtn.title = "Close without changing effects.";
    }
  }
}
// #xp-presets-emit-a-nonexistent-effect — HEALS OUTPUT NOVA ITSELF WROTE.
//
// `add_army_experience` is not a HOI4 effect; `army_experience` is. Measured over vanilla and Millennium
// Dawn (914 files): the add_* forms appear ZERO times, the real ones 1,256 / 556 / 623.
//
// This map was populated in the first commit of this repository and emptied by 35ad677 (2026-05-21),
// "Audit and fix all EFFECT_PRESETS for valid HOI4 commands" — the same commit that changed the presets
// to the invalid spelling. Every focus Nova has written since carries a dead effect, so restoring the map
// is not cosmetic: normalizeLegacyEffectCommand runs on every effect line no other branch claims, and
