function getPresetRemovalMode(preset) {
  if (!preset) return "toggle_remove_line";
  if (preset.removalMode) return String(preset.removalMode);
  if (preset.effectShape === "block") return "toggle_remove_block";
  return "toggle_remove_line";
}

function getPresetQueueCommandKey(preset) {
  if (!preset) return "";
  if (preset.queueCommandKey) return String(preset.queueCommandKey);
  return String(preset.command || "");
}

function getPresetQueueCommandKeys(preset) {
  const out = new Set();
  if (!preset) return out;
  const primary = getPresetQueueCommandKey(preset);
  const command = String(preset.command || "");
  if (primary) out.add(primary);
  if (command) out.add(command);
  if (preset.dialogPairMode && preset.inversePresetKey) {
    const inv = EFFECT_PRESETS[preset.inversePresetKey];
    if (inv && inv.command) out.add(String(inv.command));
  }
  return out;
}

/** @param {{ presetKey: string, pairMode?: string } | null} state */
function getActiveEffectAmountPreset(state) {
  if (!state || !state.presetKey) return null;
  const base = EFFECT_PRESETS[state.presetKey];
  if (!base) return null;
  if (base.dialogPairMode && state.pairMode === "inverse" && base.inversePresetKey) {
    return EFFECT_PRESETS[base.inversePresetKey] || base;
  }
  return base;
}

function getEffectAmountPairModeButtonCaption(presetKey, pairMode) {
  const inv = pairMode === "inverse";
  return inv ? "Mode: Clear" : "Mode: Add";
}

function syncEffectAmountPairModeUi() {
  const state = effectAmountState;
  if (!effectAmountPairModeBtn || !effectAmountPairModeRowEl) return;
  if (!state || !state.presetKey) {
    effectAmountPairModeRowEl.classList.add("effect-amount-row--hidden");
    effectAmountPairModeBtn.removeAttribute("aria-pressed");
    return;
  }
  const base = EFFECT_PRESETS[state.presetKey];
  const showPair = Boolean(base && base.dialogPairMode);
  effectAmountPairModeRowEl.classList.toggle("effect-amount-row--hidden", !showPair);
  if (!showPair) {
    effectAmountPairModeBtn.removeAttribute("aria-pressed");
    if (effectAmountValueLabelEl) effectAmountValueLabelEl.classList.remove("effect-amount-row--hidden");
    if (effectAmountInputEl) {
      effectAmountInputEl.classList.remove("effect-amount-row--hidden");
      effectAmountInputEl.removeAttribute("disabled");
    }
    return;
  }
  const pairMode = state.pairMode === "inverse" ? "inverse" : "primary";
  effectAmountPairModeBtn.textContent = getEffectAmountPairModeButtonCaption(state.presetKey, pairMode);
  effectAmountPairModeBtn.setAttribute("aria-pressed", pairMode === "inverse" ? "true" : "false");
  effectAmountPairModeBtn.title =
    pairMode === "inverse"
      ? "Switch to add/apply mode for this effect."
      : "Switch to clear/remove mode for this effect.";
  if (effectAmountTitleEl && base) {
    effectAmountTitleEl.textContent = base.label;
  }
  const active = getActiveEffectAmountPreset(state);
  const hideValue = Boolean(active && active.command === "drop_cosmetic_tag");
  if (effectAmountValueLabelEl) {
    effectAmountValueLabelEl.classList.toggle("effect-amount-row--hidden", hideValue);
    if (!hideValue && active) {
      effectAmountValueLabelEl.textContent =
        active.valueLabel || (active.inputMode === "text" ? "ID" : "Amount");
    }
  }
  if (effectAmountInputEl) {
    effectAmountInputEl.classList.toggle("effect-amount-row--hidden", hideValue);
    if (hideValue) effectAmountInputEl.setAttribute("disabled", "");
    else effectAmountInputEl.removeAttribute("disabled");
    if (!hideValue && active) {
      effectAmountInputEl.title =
        active.inputHint ||
        (active.inputMode === "text"
          ? `Enter ${getPresetValueLabelForPrompt(active)} for this effect.`
          : "Enter a numeric value for this effect.");
    }
  }
}

function getPresetValueLabelForPrompt(preset) {
  if (!preset) return "value";
  if (preset.valueLabel) return String(preset.valueLabel);
  return preset.inputMode === "text" ? "ID" : "value";
}

function getPresetRemoveLabel(preset, fallbackLabel = "") {
  const explicit = preset && preset.removeLabel ? String(preset.removeLabel).trim() : "";
  if (explicit) return explicit;
  const base = String(fallbackLabel || (preset && preset.label) || "").trim();
  return base.replace(/^Add\s+/i, "");
}

function tokenizeEffectsSearchQuery(raw) {
  return String(raw || "")
    .toLowerCase()
    .split(/\s+/)
    .map((t) => t.trim())
    .filter(Boolean);
}

/** @param {Element} btn */
function effectMenuBtnMatchesEffectsSearch(btn, tokens) {
  if (!tokens || tokens.length === 0) return true;
  const presetKey = (btn.dataset.effectKey || "").toLowerCase();
  const rawLabel = btn.dataset.defaultLabel || btn.textContent || "";
  const label = String(rawLabel).toLowerCase();
  const preset = presetKey ? EFFECT_PRESETS[presetKey] : null;
  const command = preset && preset.command ? String(preset.command).toLowerCase() : "";
  let hay = `${presetKey} ${command} ${label}`.trim();
  if (preset && preset.inversePresetKey) {
    const invK = String(preset.inversePresetKey || "").toLowerCase();
    const invP = EFFECT_PRESETS[preset.inversePresetKey];
    const invCmd = invP && invP.command ? String(invP.command).toLowerCase() : "";
    hay = `${hay} ${invK} ${invCmd}`.trim();
  }
  return tokens.every((tok) => hay.includes(tok));
}

function applyEffectsSearchFilter() {
  if (!effectsSubmenuEl) return;
  const scroll = effectsSubmenuEl.querySelector(".effects-menu-scroll");
  if (!scroll) return;
  const query = effectsSearchInputEl ? effectsSearchInputEl.value : "";
  const tokens = tokenizeEffectsSearchQuery(query);

  const submenus = [
    scroll,
    ideaEffectsSubmenuEl,
    buildingEffectsSubmenuEl,
    nationalResourcesSubmenuEl,
    nationalMoodSubmenuEl,
    researchDoctrineSubmenuEl,
    flagsTagsSubmenuEl,
    tensionPoliticsSubmenuEl,
    diplomacySubmenuEl
  ];

  // Map opener buttons to their target submenus to check for visible children
  const openerToSubmenu = new Map();
  if (menuAddIdeaBtn) openerToSubmenu.set(menuAddIdeaBtn, ideaEffectsSubmenuEl);
  if (menuAddBuildingBtn) openerToSubmenu.set(menuAddBuildingBtn, buildingEffectsSubmenuEl);
  if (menuAddNationalResourcesBtn) openerToSubmenu.set(menuAddNationalResourcesBtn, nationalResourcesSubmenuEl);
  if (menuNationalMoodBtn) openerToSubmenu.set(menuNationalMoodBtn, nationalMoodSubmenuEl);
  if (menuResearchDoctrineBtn) openerToSubmenu.set(menuResearchDoctrineBtn, researchDoctrineSubmenuEl);
  if (menuFlagsTagsBtn) openerToSubmenu.set(menuFlagsTagsBtn, flagsTagsSubmenuEl);
  if (menuTensionPoliticsBtn) openerToSubmenu.set(menuTensionPoliticsBtn, tensionPoliticsSubmenuEl);
  if (menuOpenDiplomacyBtn) openerToSubmenu.set(menuOpenDiplomacyBtn, diplomacySubmenuEl);

  // Pass 1: Filter normal buttons
  submenus.forEach(submenu => {
    if (!submenu) return;
    submenu.querySelectorAll(".effects-menu-btn").forEach((btn) => {
      // Don't filter the submenu opener itself in this pass
      if (openerToSubmenu.has(btn)) return;

      if (
        btn.dataset.effectsManualOpen === "1" ||
        (effectsCustomBtn && btn === effectsCustomBtn)
      ) {
        btn.classList.remove("effects-menu-btn--search-hidden");
        return;
      }
      const match = effectMenuBtnMatchesEffectsSearch(btn, tokens);
      btn.classList.toggle("effects-menu-btn--search-hidden", !match);
    });
  });

  // Pass 2: Filter openers based on whether their submenu has any matching children
  openerToSubmenu.forEach((submenu, btn) => {
    if (!tokens.length) {
      btn.classList.remove("effects-menu-btn--search-hidden");
      return;
    }
    // Check if there's any visible non-opener button in the target submenu
    const hasVisibleChild = !!submenu.querySelector(".effects-menu-btn:not(.effects-menu-btn--search-hidden):not(.effects-menu-btn--submenu)");
    btn.classList.toggle("effects-menu-btn--search-hidden", !hasVisibleChild);
  });
}

/**
 * @param {string} text
 * @param {boolean | "warn" | "error" | "info"} [levelOrLegacy=false] Legacy: `true` = error. Prefer `"warn"` / `"error"` / `"info"`.
 */
function appendDebugLine(text, levelOrLegacy = false) {
  if (!debugLogEl) return;
  let level = "info";
  if (levelOrLegacy === true) level = "error";
  else if (levelOrLegacy === "warn" || levelOrLegacy === "error" || levelOrLegacy === "info") {
    level = levelOrLegacy;
  }
  const stamp = new Date().toISOString().slice(11, 23);
  const tag = level === "error" ? " [error]" : level === "warn" ? " [warn]" : "";
  const line = `[${stamp}]${tag} ${text}`;
  debugLogEntries.push({ line, level });
  if (debugLogEntries.length > MAX_DEBUG_LINES) {
    debugLogEntries.splice(0, debugLogEntries.length - MAX_DEBUG_LINES);
  }
  renderDebugLog();
  if (debugPanelEl && level === "error") {
    debugPanelEl.open = true;
  }
  try {
    if (level === "error") console.error(line);
    else if (level === "warn") console.warn(line);
    else console.log(line);
  } catch (_e) {
    // ignore
  }
}

function renderDebugLog() {
  if (!debugLogEl) return;
  const levelFilter = String((debugLevelFilterEl && debugLevelFilterEl.value) || "all");
  const query = String((debugSearchInputEl && debugSearchInputEl.value) || "").trim().toLowerCase();
  const visible = debugLogEntries.filter((entry) => {
    if (levelFilter === "error" && entry.level !== "error") return false;
    if (levelFilter === "warn" && entry.level === "info") return false;
    if (levelFilter === "info" && entry.level !== "info") return false;
    return !query || entry.line.toLowerCase().includes(query);
  });
  debugLogEl.textContent = visible.map((entry) => entry.line).join("\n");
  if (debugLogStatsEl) {
    const errCount = debugLogEntries.filter((entry) => entry.level === "error").length;
    const warnCount = debugLogEntries.filter((entry) => entry.level === "warn").length;
    debugLogStatsEl.textContent = `${visible.length}/${debugLogEntries.length} shown | err:${errCount} warn:${warnCount}`;
  }
  if (!debugAutoScrollEl || debugAutoScrollEl.checked) {
    debugLogEl.scrollTop = debugLogEl.scrollHeight;
  }
}

function dbgInfo(message, extra) {
  const line =
    extra !== undefined
      ? `${message} ${typeof extra === "object" ? JSON.stringify(extra) : String(extra)}`
      : String(message);
  appendDebugLine(`[info] ${line}`, false);
}

function dbgError(message, extra) {
  const line =
    extra !== undefined
      ? `${message} ${typeof extra === "object" ? JSON.stringify(extra) : String(extra)}`
      : String(message);
  appendDebugLine(line, "error");
}

function dbgWarn(message, extra) {
  const line =
    extra !== undefined
      ? `${message} ${typeof extra === "object" ? JSON.stringify(extra) : String(extra)}`
      : String(message);
  appendDebugLine(line, "warn");
}

function dbgVerbose(...parts) {
  if (!debugVerboseEl || !debugVerboseEl.checked) return;
  const line = parts.map((p) => (typeof p === "object" ? JSON.stringify(p) : String(p))).join(" ");
  appendDebugLine(`[verbose] ${line}`, false);
}

function logNationalIdeaOpEntry(entry) {
  try {
    if (window.focusEditorDebug && typeof window.focusEditorDebug.logNationalIdeaOp === "function") {
      window.focusEditorDebug.logNationalIdeaOp(entry);
    }
  } catch (_e) {
    // ignore
  }
}

function ensureMarqueeEl() {
  if (marqueeEl && marqueeEl.isConnected) return marqueeEl;
  let m = document.getElementById("marquee");
  if (!m) {
    m = document.createElement("div");
    m.id = "marquee";
    m.className = "marquee";
    m.setAttribute("aria-hidden", "true");
    if (!canvasEl) return null;
    canvasEl.appendChild(m);
    dbgError("[dom] Created missing #marquee (template was absent). Marquee selection may have been broken before this.");
  }
  marqueeEl = m;
  return marqueeEl;
}

/* Match vanilla nationalfocusview.gui: focus_spacing + national_focus_item */
const GRID_X = 96;  // Clausewitz Native
const GRID_Y = 130; // Vanilla HOI4 vertical step size
const BASE_OFFSET = 120;
const NODE_WIDTH = 165;
const NODE_HEIGHT = 128;
/* link_begin / link_end positionType in nationalfocusview.gui */
const LINK_BEGIN_X = 82;
const LINK_BEGIN_Y = 64; // Absolute Center of Focus
const LINK_END_X = 82;
const LINK_END_Y = 64;   // Absolute Center of Focus
/** Large goal art in editor: center X in node; center Y in upper brown band (bg starts y=40; title y=58). */
const EDITOR_FOCUS_ICON_CENTER_X = NODE_WIDTH / 2;
const EDITOR_FOCUS_ICON_CENTER_Y = 20; // Native center Y
const FOCUS_GOAL_ICON_PX = 100; // Native Width
const VANILLA_UI_BG_REL = "gfx/interface/techtree/technology_unavailable_item_bg.dds";
const MIN_ZOOM = 0.25;
const MAX_ZOOM = 2.0;
const ZOOM_STEP = 0.1;
/** Pixels of movement before a press counts as a drag (not a click). */
const DRAG_THRESHOLD_PX = 4;

let sourceText = "";

// #source-patch-invalidates-block-offsets — EDITS TO THE TREE HEADER MUST NOT TOUCH sourceText.
//
// parsed.focuses[].blockStart / blockEnd are BYTE OFFSETS INTO sourceText, and Save is
// rewriteCoordinates(sourceText, parsed), which splices each focus block by those offsets. Insert a line
// anywhere above a focus and every one of its offsets is wrong by the length of that line.
//
// Two places used to patch sourceText directly while the editor was open — the continuous-focus panel
// position and the shared_focus link toggle — each with a comment saying it kept the in-memory text "in
// sync so a later save preserves the change". Measured on Millennium Dawn's USA tree (776 focuses,
// 1.37 MB): staging a panel position inserted 51 bytes, and the save that followed produced a file
// 43,241 bytes SHORTER, losing 39,888 non-whitespace characters. It still parsed to 776 focuses with
// balanced braces, so "Save blocked: generated file is invalid" never fired — Nova would have reported a
// successful save of a tree with 40 KB missing.
//
// Header edits are staged here instead and applied to the OUTPUT of rewriteCoordinates, once every offset
// has been spent. Keyed, so re-dragging the panel replaces its own entry rather than stacking.
//
// ⚠️ PLAIN DATA, NEVER A CLOSURE. pushUndoEntry stores cloneJson(snapshot) and JSON drops functions: a
// first version held { apply: (t) => ... } and worked until you pressed Ctrl+Z then Ctrl+Y, after which
// the entry came back with no apply, was skipped, and the move vanished at save with nothing said.
// Entry shape: { kind: "upsert"|"remove", match: <regex source>, line, replace? }
//   line    — what to INSERT when the match is absent (indented under focus_tree = { )
//   replace — what to substitute when the match is PRESENT; defaults to `line`.
//
// #header-upsert-eats-the-newline — `replace` exists because a match may swallow more than the line itself.
// The shared_focus pattern starts `(^|\n)` so that removing it also takes the newline and leaves no blank
// line behind — but substituting the bare line then welded it onto the line above:
//     id = my_tree            became      id = my_treeshared_focus = grp
// which renames the tree to "my_treeshared_focus" and is a corrupt file. It puts the captured newline and
// the indent back explicitly now.
let pendingTreeHeaderEdits = new Map();

//
// #header-edit-lands-in-a-comment — THE WRITER READ THROUGH COMMENTS THE READER MASKS OUT.
//
// parseTreeContinuousPosition (below) strips comments before it looks for continuous_focus_position, so
// on a tree whose only one is commented out the editor correctly says "no position" — and then this
// writer, matching raw text, found that dead line and rewrote the numbers INSIDE the author's comment.
// Dragging the panel reported "moved — click Save when ready", the save reported success, the panel was
// still unpositioned in game and snapped back on reload, and the commented-out value the modder had
// parked there was silently altered. Measured over 763 shipping focus-tree files in 7 roots: 8 files
// (vanilla paraguay_uruguay_shared_branch, 4 in Road to 56, 3 in Old World Blues) have their ONLY
// continuous_focus_position behind a #.
//
// The insert fallback was comment-blind the same way: it anchored on the first `focus_tree = {` ANYWHERE
// in the text, including a commented-out one, and put a LIVE line under it — on 5 of those 763 files
// (OWB "New California Republic (NCR) Focus OLD"/"Sleepers (SLE)", R56 japan_old/r56_estonia_shared/
// silesia) that lands the property outside any tree, where HOI4 logs it and ignores it. Anchoring on the
// first LIVE focus_tree is also what makes this target the tree the user is editing on the 22 files that
// declare more than one — the tree-owner dialog says "this file has N trees; editing the first", and
// "first" has to mean the first real one, not the first one that appears in a comment.
//
// maskPdxComments is length-preserving, so an offset found in the masked copy indexes the real text.
/** Apply staged header edits to freshly rewritten tree text. Offsets are spent by this point. */
function applyPendingTreeHeaderEdits(text) {
  let out = text;
  for (const [key, edit] of pendingTreeHeaderEdits) {
    if (!edit || typeof edit.match !== "string") { dbgWarn("Skipping malformed tree header edit", key); continue; }
    try {
      const re = new RegExp(edit.match);
      const masked = maskPdxComments(out);   // #header-edit-lands-in-a-comment — look here, splice there
      const hit = re.exec(masked);
      if (edit.kind === "remove") {
        if (hit) out = out.slice(0, hit.index) + out.slice(hit.index + hit[0].length);
        continue;
      }
      if (hit) {
        const was = out.slice(hit.index, hit.index + hit[0].length);
        if (!re.test(was)) { dbgWarn("Tree header edit matched only through a comment", key); continue; }
        out = out.slice(0, hit.index) + was.replace(re, edit.replace != null ? edit.replace : edit.line) + out.slice(hit.index + hit[0].length);
        continue;
      }
      // The insert fallback. Line-anchored on the masked copy, so a commented-out container is invisible.
      const anchor = /(^|\n)[ \t]*focus_tree\s*=\s*\{[^\n]*\n/.exec(masked);
      if (!anchor) {
        // #staged-header-edit-vanishes — nothing to anchor to, and these are all focus_tree properties, so
        // there is nowhere legal to put one. String.replace used to return the text unchanged here and the
        // save reported success, so the user was told an edit landed that had been thrown away. 114 of 763
        // shipping focus files declare no focus_tree at all (shared_focus-only branches: china_shared,
        // baltic_shared, abdacom_shared_branch, …). cfStageTreePosition refuses up front now; this stays
        // as the backstop for every other stager, and it says so instead of going quiet.
        dbgWarn("Tree header edit dropped — this file declares no focus_tree to put it in", key);
        continue;
      }
      const at = anchor.index + anchor[0].length;
      out = out.slice(0, at) + "\t" + edit.line + "\n" + out.slice(at);
    } catch (e) {
      // A bad header edit must never take the whole save down with it — but it must not be silent either.
      dbgWarn("Tree header edit failed", { key, message: e && e.message });
    }
  }
  return out;
}
// #stale-focus-save — the fingerprint of the file EXACTLY as it was loaded from disk.
//
// Saving this tree writes the whole file, so if something else edited it in the meantime that edit would be
// replaced. The server compares this against the file on disk and refuses rather than overwrite. Taken at
// LOAD time on purpose: sourceText is mutated in place afterwards (shared_focus, continuous position), so
// hashing it at save time would compare the wrong thing.
let loadedFingerprint = "";
// Byte-identical twin of novaFileFingerprint in server.js — change one and you must change the other.
function novaFileFingerprint(text) {
  const s = String(text == null ? "" : text);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i += 1) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return s.length + "-" + h.toString(16);
}
let loadedPath = "";
let modsRootPath = "";
/** Server active mod root from last /api/root (used when no focus file path is available). */
let editorActiveRootPath = "";
// The base game's folder as the server found it (/api/root) — never a mod, wherever it is installed. #vanilla-tree-made-the-active-mod
let hoi4GameRootPath = "";
// …and whether it found the game at all (/api/root hoi4GameExeFound; null until asked). #nova-does-not-find-the-game
let hoi4GameFound = null;
let parsed = null;

let cachedStates = [];
let cachedCountries = [];
let _globalDataModKey = null;   // the mod cachedStates/cachedCountries were fetched FOR

/**
 * The mod root a request from this page must name. #editor-requests-do-not-name-the-mod
 *
 * A request that names no mod is answered for the SERVER's active mod — whatever active-mod.json last
 * recorded — and the tree on the canvas can easily belong to a different one: you open a tree by path, or
 * from another mod, or the active mod was left pointing somewhere else. Nothing errors; the answer is just
 * about the wrong mod. That is what put a raw focus id under every node on the canvas
 * (#loc-map-follows-the-active-mod-not-the-open-tree), and the same reasoning was then needed by the state
 * and country catalogues that label focus effects.
 *
 * Prefer the open tree's mod; fall back to the active mod when no tree is open (page init).
 *
 * ⚠️ …but NOT for a vanilla tree. inferModRootFromFocusPath strips at common/national_focus with none of
 * the game-root exclusion the server's detectModRootFromFocusPath has, so for a tree opened out of the
 * HOI4 install it hands back the install itself — and asking for THAT root drops every key the user's own
 * mod defines. Studying a vanilla tree is ordinary and must not cost you your mod's data, so fall through
 * to the active mod, exactly as the server does when detectModRootFromFocusPath returns null.
 *
 * Returns "" when neither is known, meaning "let the server choose" — callers must then key their cache
 * on a sentinel, never on "", or one mod's answer gets stored under another mod's name.
 */
function editorRequestModRoot() {
  const treeRoot = (loadedPath && !isLoadedFocusUnderVanillaGameInstall(loadedPath))
    ? (inferModRootFromFocusPath(loadedPath) || "")
    : "";
  return treeRoot || (localStorage.getItem("activeModPath") || "").trim();
}
/** The cache key for a given request root. A sentinel for "server chose", so it cannot collide with a path. */
function editorRequestModKey(root) { return root || "(server-active-mod)"; }
/** `?modPath=…` for a request root, or "" when the server should choose. */
function editorModPathQuery(root) { return root ? `?modPath=${encodeURIComponent(root)}` : ""; }

async function ensureGlobalDataLoaded() {
  // #editor-requests-do-not-name-the-mod — THESE TWO NAMED NO MOD, AND THE GUARD HAD NO MOD KEY.
  //
  // Both catalogues are answered for whichever mod the SERVER thinks is active, and both feed
  // resolveStateName/resolveCountryName — the labels on every focus effect that touches a state or a
  // country. With a tree open from another mod they named the wrong mod's state 42, or fell back to the
  // bare "State 42" when the current mod's catalogue was never fetched. That is the same thing the user
  // reported seeing on the canvas: an id where a name should be.
  //
  // And it could not self-correct: the guard was a bare "do I have anything?" check, so the first mod
  // asked was the only mod ever asked for the life of the page.
  const root = editorRequestModRoot();
  const key = editorRequestModKey(root);
  if (_globalDataModKey === key && cachedStates.length > 0 && cachedCountries.length > 0) return;
  try {
    const q = editorModPathQuery(root);
    const [statesRes, countriesRes] = await Promise.all([
      fetch(`/api/buildings/state-catalog${q}`),
      fetch(`/api/countries/catalog${q}`)
    ]);
    const statesData = await statesRes.json();
    const countriesData = await countriesRes.json();
    cachedStates = Array.isArray(statesData.items) ? statesData.items : [];
    cachedCountries = Array.isArray(countriesData) ? countriesData : [];
    // Record what was actually asked for, not what the page wishes were active.
    _globalDataModKey = key;
    dbgInfo(`Global data loaded: ${cachedStates.length} states, ${cachedCountries.length} countries.`);
  } catch (err) {
    dbgError("ensureGlobalDataLoaded", err);
  }
}

function resolveStateName(id) {
  const s = cachedStates.find(x => String(x.stateId) === String(id));
  return s ? s.displayName : `State ${id}`;
}

function resolveCountryName(tag) {
  const c = cachedCountries.find(x => String(x.tag).toUpperCase() === String(tag).toUpperCase());
  return c ? c.name : tag;
}


let dirty = false;
const DOCUMENT_TITLE_BASE = "Focus Tree — Nova Modding Suite";

function applyChromeDirtyIndicator() {
  document.title = dirty ? `${DOCUMENT_TITLE_BASE} · unsaved` : DOCUMENT_TITLE_BASE;
  if (document.body) document.body.classList.toggle("app-dirty", dirty);
}
let dragState = null;
/** @type {{ focus: object, nodeEl: Element, startClientX: number, startClientY: number, hadMultiWithFocus: boolean } | null} */
let pendingDrag = null;
/** @type {Set<string>} */
let selectedIds = new Set();

// Command Sidebar Elements are declared at top level

function initSidebar() {
  sbFocusIdEl = document.getElementById("sidebar-focus-id");
  sbFocusNameEl = document.getElementById("sb-focus-name");
  sbFocusDescEl = document.getElementById("sb-focus-desc");
  sbFocusIconEl = document.getElementById("sb-focus-icon");
  sbIconPreviewEl = document.getElementById("sb-icon-preview");
  sbFocusCostEl = document.getElementById("sb-focus-cost");
  sbFocusXEl = document.getElementById("sb-focus-x");
  sbFocusYEl = document.getElementById("sb-focus-y");
  sbPrereqListEl = document.getElementById("sb-prereq-list");
  sbMutexListEl = document.getElementById("sb-mutex-list");
  sbRewardListEl = document.getElementById("sb-reward-list");
  sbSaveBtnEl = document.getElementById("sb-save-btn");
  sbCloseBtnEl = document.getElementById("sidebar-close-btn");
  sbEffectSearchEl = document.getElementById("sb-effect-search");

  const addPrereqBtn = document.getElementById("sb-add-prereq");
  const addMutexBtn = document.getElementById("sb-add-mutex");
  const addEffectBtn = document.getElementById("sb-add-effect-btn");

  if (sbCloseBtnEl) {
    sbCloseBtnEl.addEventListener("click", closeSidebar);
  }

  if (sbSaveBtnEl) {
    // Button removed, but keep listener just in case of programmatic calls
    sbSaveBtnEl.addEventListener("click", applySidebarLiveChanges);
  }

  // Wire up live updates
  [sbFocusNameEl, sbFocusDescEl, sbFocusIconEl, sbFocusCostEl, sbFocusXEl, sbFocusYEl].forEach(el => {
    if (el) el.addEventListener("input", applySidebarLiveChanges);
  });
  ["sb-focus-available", "sb-focus-allowbranch", "sb-focus-aiwilldo", "sb-focus-bypass", "sb-focus-warwith", "sb-focus-selecteffect"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("input", applySidebarLiveChanges);
  });

  // Genesis "plain English" preview for the focus condition fields (read-only, additive — never
  // changes what is saved). Same kill-coding aid as the makers, on the flagship focus editor:
  // a modder reads "has completed the focus X; is at peace" instead of raw Paradox triggers.
  function refreshFocusConditionPreview(taId, boxId, label) {
    const ta = document.getElementById(taId);
    const box = document.getElementById(boxId);
    if (!ta || !box) return;
    const raw = (ta.value || "").trim();
    if (!raw) { box.style.display = "none"; box.textContent = ""; return; }
    let english = "";
    try {
      if (window.GenesisEngine && typeof window.GenesisEngine.translateTriggers === "function") {
        english = window.GenesisEngine.translateTriggers(raw);
      }
    } catch (_) { english = ""; }
    box.style.display = "";
    box.textContent = "";
    const lab = document.createElement("span");
    lab.className = "genesis-preview-label";
    lab.textContent = label;
    box.appendChild(lab);
    if (english) {
      box.classList.remove("genesis-preview-empty");
      box.appendChild(document.createTextNode(english));
    } else {
      box.classList.add("genesis-preview-empty");
      box.appendChild(document.createTextNode("Couldn't auto-translate this condition — it will still be saved exactly as written."));
    }
  }
  function refreshFocusConditionPreviews() {
    refreshFocusConditionPreview("sb-focus-available", "sb-focus-available-preview", "🔮 Available when");
    refreshFocusConditionPreview("sb-focus-bypass", "sb-focus-bypass-preview", "🔮 Bypassed when");
    refreshFocusConditionPreview("sb-focus-allowbranch", "sb-focus-allowbranch-preview", "🔮 Branch shown when");
  }
  [["sb-focus-available", "sb-focus-available-preview", "🔮 Available when"],
   ["sb-focus-bypass", "sb-focus-bypass-preview", "🔮 Bypassed when"],
   ["sb-focus-allowbranch", "sb-focus-allowbranch-preview", "🔮 Branch shown when"]].forEach(([taId, boxId, label]) => {
    const el = document.getElementById(taId);
    if (el) el.addEventListener("input", () => refreshFocusConditionPreview(taId, boxId, label));
  });
  window.__novaRefreshFocusConditions = refreshFocusConditionPreviews;
  ["sb-focus-cancel", "sb-focus-continue", "sb-focus-capitulated"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("change", applySidebarLiveChanges);
  });

  // Relative position anchor: switching between absolute and relative keeps the
  // focus visually put by converting stored x/y between absolute coords and an
  // offset from the anchor (matching how the renderer resolves relative focuses).
  const sbRelativeEl = document.getElementById("sb-focus-relative");
  if (sbRelativeEl) {
    sbRelativeEl.addEventListener("change", () => {
      const [id] = [...selectedIds];
      const focus = (parsed?.focuses || []).find((f) => f.id === id);
      if (!focus) return;
      const newRel = sbRelativeEl.value.trim() || null;
      if (newRel === (focus.relativePositionId || null)) return;
      if (newRel === focus.id) { sbRelativeEl.value = focus.relativePositionId || ""; return; }
      const map = new Map((parsed.focuses || []).map((f) => [f.id, f]));
      if (newRel && !map.has(newRel)) {
        setStatus(`No focus with id "${newRel}" — relative anchor unchanged.`, true);
        sbRelativeEl.value = focus.relativePositionId || "";
        return;
      }
      const absX = focus.displayX, absY = focus.displayY;
      const newAnchor = newRel ? map.get(newRel) : null;
      focus.relativePositionId = newRel;
      focus.relationType = newRel ? "relative" : "absolute";
      if (newRel && newAnchor) { focus.x = absX - newAnchor.displayX; focus.y = absY - newAnchor.displayY; }
      else { focus.x = absX; focus.y = absY; }
      focus.moved = false;
      // #clearing-an-anchor-keeps-the-offset — the frame the block is written in just changed, so the x/y
      // line HAS to be re-emitted. `moved` is cleared just above (resolveLayout reads it as "displayX/Y are
      // authoritative"), and computeWriteValues reaches this focus through neither of its rules:
      // explicitRelative needs an anchor that is still SET, and toAbsolute is seeded from `moved`. So
      // clearing an anchor removed the relative_position_id line — that rewrite runs unconditionally — and
      // left the old OFFSET behind as the new absolute position. A focus anchored to A at offset (3,2),
      // sitting at (43,12), reloaded at (3,2). positionDirty is the flag that survives whoever clears
      // `moved`, and focus.x/y already hold the right value in the right frame.
      focus.positionDirty = true;
      if (sbFocusXEl) sbFocusXEl.value = focus.x;
      if (sbFocusYEl) sbFocusYEl.value = focus.y;
      const hint = document.getElementById("sb-relative-hint");
      if (hint) hint.style.display = newRel ? "block" : "none";
      markDirty(true);
      refreshParsedDerived();
      renderFocuses();
    });
  }

  if (addPrereqBtn) {
    addPrereqBtn.addEventListener("click", () => {
      const [id] = [...selectedIds];
      if (id) startPrereqLinkMode(id, 0, 0, "add");
    });
  }

  if (addMutexBtn) {
    addMutexBtn.addEventListener("click", () => {
      const [id] = [...selectedIds];
      if (id) startMutexLinkMode(id, 0, 0, "add");
    });
  }

  if (addEffectBtn) {
    addEffectBtn.addEventListener("click", () => {
      const picker = document.getElementById("sb-effect-picker");
      if (picker) picker.classList.remove("sb-hidden");
      if (sbEffectSearchEl) {
        sbEffectSearchEl.value = "";
        renderSidebarEffectPickerList();
        sbEffectSearchEl.focus();
      }
    });
  }

  const sbOpenFileBtn = document.getElementById("sb-open-file-btn");
  if (sbOpenFileBtn) {
    sbOpenFileBtn.addEventListener("click", () => {
      openLoadedFocusTreeFile();
    });
  }

  const sbEffectPickerClose = document.getElementById("sb-effect-picker-close");
  if (sbEffectPickerClose) {
    sbEffectPickerClose.addEventListener("click", () => {
      const picker = document.getElementById("sb-effect-picker");
      if (picker) picker.classList.add("sb-hidden");
    });
  }

  if (sbEffectSearchEl) {
    sbEffectSearchEl.addEventListener("input", renderSidebarEffectPickerList);
  }

  if (sbFocusIconEl) {
    sbFocusIconEl.addEventListener("input", (e) => {
      updateSidebarIconPreview(e.target.value.trim());
    });
  }

}

function openSidebarForSelection() {
  // Reset view to general info by hiding effect picker when focus changes
  const picker = document.getElementById("sb-effect-picker");
  if (picker) picker.classList.add("sb-hidden");

  if (selectedIds.size !== 1) {
    closeSidebar();
    try { localStorage.removeItem("lastSelectedFocusId"); } catch (_e) {}
    return;
  }
  const [id] = [...selectedIds];
  const focus = (parsed?.focuses || []).find(f => f.id === id);
  if (!focus) {
    closeSidebar();
    try { localStorage.removeItem("lastSelectedFocusId"); } catch (_e) {}
    return;
  }

  try { localStorage.setItem("lastSelectedFocusId", id); } catch (_e) {}
  updateSidebarContent(focus);
  if (propertySidebarEl) {
    propertySidebarEl.setAttribute("aria-hidden", "false");
    document.body.classList.add("sidebar-open");
  }
}

function closeSidebar() {
  if (propertySidebarEl) {
    propertySidebarEl.setAttribute("aria-hidden", "true");
    document.body.classList.remove("sidebar-open");
  }
}

function updateSidebarContent(focus) {
  if (!sbFocusIdEl) return;
  sbFocusIdEl.textContent = focus.id;

  // Use localization map if name/desc are keys or missing
  const locName = localizationMap[focus.id] || "";
  const locDesc = localizationDescMap[`${focus.id}_desc`] || "";

  // #focus-sidebar-strips-loc-on-load — THE EDIT BOX HOLDS THE RAW VALUE.
  //
  // These two boxes are read back on save (line ~2709 below), so anything removed here is removed from
  // the author's .yml the next time they nudge a cost, an icon or an x/y. sanitizeLocalization eats
  // §<letter> colour codes and [SCOPE.Token] references: 27,990 of vanilla's 129,087 English values
  // (21.7%) and 24,634 of Millennium Dawn's 178,471 (13.8%) carry one.
  //
  // e2e-loc-token-name-roundtrip.js states the contract for the other three makers — display readable,
  // edit box and saved .yml RAW — and this sidebar never adopted it. Readability is handled the same way
  // they handle it: the canvas node titles and the preview use the display-only stripLocDisplayCodes.
  sbFocusNameEl.value = focus.name || locName || focus.id;
  sbFocusDescEl.value = focus.desc || locDesc || "";

  sbFocusIconEl.value = focus.iconKey || "";
  // A focus can legitimately cost 0 — it completes instantly (vanilla ships 15 of them, MD 12, RoN 19).
  // `focus.cost || 10` swallowed that real 0 (0 is falsy) and showed 70 days, so merely OPENING such a
  // focus and hitting Save silently rewrote its cost from 0 to 10. Keep a real 0; fall back to the
  // 10-week default only when cost is genuinely absent. #falsy-zero
  const _rawCost = focus.cost;
  const _costWeeks = (_rawCost === undefined || _rawCost === null || _rawCost === "" || !Number.isFinite(Number(_rawCost))) ? 10 : Number(_rawCost);
  sbFocusCostEl.value = _costWeeks * 7;
  sbFocusXEl.value = focus.x;
  sbFocusYEl.value = focus.y;
  const availEl = document.getElementById("sb-focus-available");
  const allowBranchEl = document.getElementById("sb-focus-allowbranch");
  const aiEl = document.getElementById("sb-focus-aiwilldo");
  if (availEl) availEl.value = focus.available || "";
  if (allowBranchEl) allowBranchEl.value = focus.allowBranch || "";
  if (aiEl) aiEl.value = focus.aiWillDo || "";
  const bypassEl = document.getElementById("sb-focus-bypass");
  const cancelEl = document.getElementById("sb-focus-cancel");
  const continueEl = document.getElementById("sb-focus-continue");
  if (bypassEl) bypassEl.value = focus.bypass || "";
  if (cancelEl) cancelEl.value = focus.cancelIfInvalid || "";
  if (continueEl) continueEl.value = focus.continueIfInvalid || "";
  const capitEl = document.getElementById("sb-focus-capitulated");
  if (capitEl) capitEl.value = focus.availableIfCapitulated || "";
  const warEl = document.getElementById("sb-focus-warwith");
  const selEl = document.getElementById("sb-focus-selecteffect");
  if (warEl) warEl.value = focus.willLeadToWarWith || "";
  if (selEl) selEl.value = focus.selectEffect || "";
  if (window.__novaRefreshFocusConditions) window.__novaRefreshFocusConditions();
  const relEl = document.getElementById("sb-focus-relative");
  if (relEl) {
    relEl.value = focus.relativePositionId || "";
    const hint = document.getElementById("sb-relative-hint");
    if (hint) hint.style.display = focus.relativePositionId ? "block" : "none";
    const dl = document.getElementById("focusIdDatalist");
    if (dl) {
      dl.innerHTML = (parsed?.focuses || [])
        .filter((f) => f.id !== focus.id)
        .map((f) => `<option value="${f.id}">${f.displayName ? `${f.id} (${f.displayName})` : f.id}</option>`).join("");
    }
  }
  updateSidebarIconPreview(focus.iconKey);
  renderSidebarLists(focus);
}

function updateSidebarIconPreview(gkey) {
  if (!sbIconPreviewEl) return;
  const noteEl = document.getElementById("sb-icon-note");
  const showGeneric = () => {
    if (genericFocusIconUrl) { sbIconPreviewEl.src = genericFocusIconUrl; sbIconPreviewEl.style.display = "block"; sbIconPreviewEl.style.opacity = "0.5"; }
    else sbIconPreviewEl.style.display = "none";
  };
  if (!gkey) {
    // No icon chosen → show the generic default the game will use, faded, plus a visible warning note.
    showGeneric();
    if (noteEl) noteEl.style.display = "block";
    return;
  }
  if (noteEl) noteEl.style.display = "none";
  sbIconPreviewEl.style.opacity = "1";

  // Resolve the chosen icon via the API; if it can't resolve, fall back to the faded generic (never blank).
  fetch(`/api/icon?key=${encodeURIComponent(gkey)}`)
    .then(res => res.json())
    .then(payload => {
      const bestUrl = payload.imageUrl || payload.url || "";
      if (bestUrl) {
        sbIconPreviewEl.src = bestUrl;
        sbIconPreviewEl.style.display = "block";
        sbIconPreviewEl.style.opacity = "1";
      } else {
        showGeneric();
      }
    })
    .catch(() => { showGeneric(); });
}

// Apply an icon chosen from the icon browser DIRECTLY to the selected focus, using the exact texture file
// the thumbnail rendered. This avoids the slow/fallible resolve-by-key (#7/#8 — ~18s cold on Millennium
// Dawn, and a "?" when it doesn't resolve), so the node and sidebar preview show the picked image instantly.
// When the continuous-focus editor opened the shared icon picker, the pick belongs to ITS icon field, not
// to whichever focus happens to be selected on the canvas behind the dialog. Set while that editor has the
// picker open, cleared the moment a pick lands (#cf-icon-picker).
let cfIconPickTarget = false;

function applyPickedFocusIcon(key, texturefile) {
  if (cfIconPickTarget) {
    cfIconPickTarget = false;
    const el = document.getElementById("cfEdIcon");
    if (el) { el.value = key; el.dispatchEvent(new Event("input", { bubbles: true })); }
    const modal = document.getElementById("iconPickerModal");
    if (modal) modal.style.display = "none";
    return;
  }
  const url = texturefile ? `/api/buildings/icon-file?path=${encodeURIComponent(texturefile)}` : "";
  if (sbIconPreviewEl) {
    if (url) { sbIconPreviewEl.src = url; sbIconPreviewEl.style.display = "block"; }
    else { sbIconPreviewEl.style.display = "none"; }
  }
  if (typeof selectedIds !== "undefined" && selectedIds.size === 1) {
    const [id] = [...selectedIds];
    const focus = ((parsed && parsed.focuses) || []).find((f) => f.id === id);
    if (focus) {
      focus.iconKey = key;
      focus.iconUrl = url;
      focus.iconSource = "picked";
      const sel = (window.CSS && CSS.escape) ? CSS.escape(id) : id;
      const node = canvasEl && canvasEl.querySelector(`.node[data-focus-id="${sel}"]`);
      const iconEl = node && node.querySelector(".node-icon");
      if (iconEl && url) { delete iconEl.dataset.lazySrc; iconEl.src = url; iconEl.style.display = ""; }
      markDirty(true);
    }
  }
}

function renderSidebarLists(focus) {
  if (!sbPrereqListEl || !sbMutexListEl || !sbRewardListEl) return;

  sbPrereqListEl.innerHTML = "";
  (focus.prerequisites || []).forEach(p => {
    addSidebarListItem(sbPrereqListEl, p, () => {
      // #sidebar-removes-outside-undo — one click deletes a prerequisite. Snapshot before, like every other
      // destructive action in this file, or the only way back is to remember what it was and re-add it.
      pushUndoSnapshot();
      focus.prerequisites = focus.prerequisites.filter(x => x !== p);
      focus.prereqsEdited = true; // user edited prereqs → allow the save to rebuild this focus's prereq block
      markDirty(true);
      refreshParsedDerived();
      renderFocuses();
      updateSidebarContent(focus);
    });
  });

  sbMutexListEl.innerHTML = "";
  (focus.mutuallyExclusive || []).forEach(m => {
    addSidebarListItem(sbMutexListEl, m, () => {
      // #sidebar-removes-outside-undo — this one edits TWO focuses (the link is bidirectional), so the
      // manual repair is twice as fiddly and the snapshot matters twice as much.
      pushUndoSnapshot();
      // Bidirectional removal
      focus.mutuallyExclusive = focus.mutuallyExclusive.filter(x => x !== m);
      // #mutex-rebuild-eats-a-commented-out-focus — user edited this focus's mutex set → let the save
      // rebuild its block. Both ends, because the removal above is bidirectional.
      focus.mutexEdited = true;
      const other = getFocusById(m);
      if (other && Array.isArray(other.mutuallyExclusive)) {
        other.mutuallyExclusive = other.mutuallyExclusive.filter(x => x !== focus.id);
        other.mutexEdited = true;
      }
      markDirty(true);
      refreshParsedDerived();
      renderFocuses();
      updateSidebarContent(focus);
    });
  });

  sbRewardListEl.innerHTML = "";
  const effects = pendingEffectEdits.get(focus.id) || focus.reward || [];

  effects.forEach((eff, index) => {
    let displayText = eff;
    if (window.genesisEnabled) {
      const trans = translateHoi4ToEnglish(eff);
      if (trans) {
        displayText = trans;
      } else if (eff.includes("INDENT") || eff.includes("MARKER") || eff.includes("focus_editor")) {
        return; // Intentionally skip structural markers
      }
    }

    const onRemove = () => {
      // #sidebar-removes-outside-undo — deleting a reward line throws away authored HOI4 script, which is
      // the most expensive thing on this panel to retype. Snapshot before, as the other × buttons now do.
      pushUndoSnapshot();
      const next = [...effects];
      next.splice(index, 1);
      if (next.length > 0) pendingEffectEdits.set(focus.id, next);
      else pendingEffectEdits.delete(focus.id);
      markDirty(true);
      renderFocuses();
      renderSidebarLists(focus);
    };

    const onEdit = (itemEl) => {
       itemEl.classList.add("sidebar-list-item--editing");
       const label = itemEl.querySelector("span");
       const oldText = label.textContent;
       const textarea = document.createElement("textarea");
       textarea.className = "sidebar-edit-area";
       textarea.value = eff;
       
       const saveBtn = document.createElement("button");
       saveBtn.className = "sidebar-save-btn";
       saveBtn.innerHTML = "Save";
       
       const cancelBtn = document.createElement("button");
       cancelBtn.className = "sidebar-cancel-btn";
       cancelBtn.innerHTML = "Cancel";

       const originalActions = itemEl.querySelector(".sidebar-item-actions");
       originalActions.style.display = "none";
       label.style.display = "none";

       const editActions = document.createElement("div");
       editActions.className = "sidebar-edit-actions";
       editActions.appendChild(saveBtn);
       editActions.appendChild(cancelBtn);

       itemEl.appendChild(textarea);
       itemEl.appendChild(editActions);

       textarea.focus();

       saveBtn.onclick = () => {
          const next = [...effects];
          next[index] = textarea.value;
          pendingEffectEdits.set(focus.id, next);
          markDirty(true);
          renderFocuses();
          
          // GENESIS PASS 3: Premium success indicator
          itemEl.innerHTML = `<div style="padding: 10px; display: flex; align-items: center; justify-content: center; gap: 8px; background: rgba(46, 160, 67, 0.15); border-radius: 6px; border: 1px solid #2ea043; color: #3fb950; font-weight: 600; font-size: 13px;">
             <span style="font-size: 16px;">✓</span> Logic Applied Successfully
          </div>`;
          
          setTimeout(() => {
             renderSidebarLists(focus);
          }, 850);
       };

       cancelBtn.onclick = () => {
          renderSidebarLists(focus);
       };
    };

    addSidebarListItem(sbRewardListEl, sanitizeLocalization(displayText), onRemove, eff, onEdit); 
  });
}

function addSidebarListItem(container, text, onRemove, rawCode = "", onEdit = null) {
  const item = document.createElement("div");
  item.className = "sidebar-list-item";
  if (rawCode) {
    item.title = rawCode; 
  }
  const label = document.createElement("span");
  label.textContent = text;
  item.appendChild(label);

  const btnContainer = document.createElement("div");
  btnContainer.className = "sidebar-item-actions";

  if (onEdit) {
    const editBtn = document.createElement("button");
    editBtn.className = "edit-item-btn";
    editBtn.innerHTML = "✎";
    editBtn.title = "Edit Raw Code";
    editBtn.onclick = (e) => {
      e.stopPropagation();
      onEdit(item);
    };
    btnContainer.appendChild(editBtn);
  }

  const removeBtn = document.createElement("button");
  removeBtn.className = "remove-item-btn";
  removeBtn.innerHTML = "&times;";
  removeBtn.onclick = (e) => {
    e.stopPropagation();
    onRemove();
  };
  btnContainer.appendChild(removeBtn);

  item.appendChild(btnContainer);
  container.appendChild(item);
}

function applySidebarLiveChanges() {
  const [id] = [...selectedIds];
  const focus = (parsed?.focuses || []).find(f => f.id === id);
  if (!focus) return;

  // #sidebar-edits-outside-undo — THE SIDEBAR IS THE MAIN EDITING SURFACE AND IT WAS NOT IN THE HISTORY.
  //
  // This function writes 16 focus fields — name, description, icon, cost, grid x/y, available, allow_branch,
  // ai_will_do, bypass, cancel/continue if invalid, available_if_capitulated, will_lead_to_war_with,
  // select_effect — plus the localisation maps, and then called markDirty and nothing else. Seventeen other
  // mutating actions in this file push a snapshot first.
  //
  // That asymmetry is worse than a plain gap: because the surrounding actions DO push, Ctrl+Z did not simply
  // ignore sidebar edits, it OVERSHOT — restoring the snapshot taken at the last covered action and throwing
  // away every keystroke since, with no way forward except redo.
  //
  // Snapshot BEFORE the assignments below, and only on the first change to this field of this focus (see
  // sidebarUndoBurstKey). document.activeElement is the field being typed in at the moment an input/change
  // event fires, which is what distinguishes one burst from the next.
  {
    const active = (typeof document !== "undefined" && document.activeElement) || null;
    const burstKey = String(id) + "|" + ((active && active.id) || "");
    if (sidebarUndoBurstKey !== burstKey) {
      pushUndoSnapshot();            // nulls the key…
      sidebarUndoBurstKey = burstKey; // …so claim it afterwards
    }
  }

  const nextName = sbFocusNameEl.value.trim();
  const nextDesc = sbFocusDescEl.value.trim();

  focus.name = nextName;
  focus.desc = nextDesc;
  focus.iconKey = sbFocusIconEl.value.trim();

  // Convert Days back to Cost (weeks). 0 days = a legitimate INSTANT focus (cost 0) — the old
  // `parseInt(...) || 70` turned a real 0 into the 70-day default, and Math.max(1, …) then floored any
  // 0 up to 1, so a cost-0 focus could neither be authored nor survive a round-trip. Keep 0 exactly;
  // otherwise preserve the old behaviour (a 1-3 day entry still floors to the 1-week minimum). #falsy-zero
  const _parsedDays = parseInt(sbFocusCostEl.value, 10);
  const nDays = Number.isFinite(_parsedDays) ? Math.max(0, _parsedDays) : 70;
  focus.cost = nDays === 0 ? 0 : Math.max(1, Math.round(nDays / 7));

  const availEl = document.getElementById("sb-focus-available");
  const allowBranchEl = document.getElementById("sb-focus-allowbranch");
  const aiEl = document.getElementById("sb-focus-aiwilldo");
  if (availEl) focus.available = availEl.value.trim();
  if (allowBranchEl) focus.allowBranch = allowBranchEl.value.trim();
  if (aiEl) focus.aiWillDo = aiEl.value.trim();
  const bypassEl = document.getElementById("sb-focus-bypass");
  const cancelEl = document.getElementById("sb-focus-cancel");
  const continueEl = document.getElementById("sb-focus-continue");
  if (bypassEl) focus.bypass = bypassEl.value.trim();
  if (cancelEl) focus.cancelIfInvalid = cancelEl.value;
  if (continueEl) focus.continueIfInvalid = continueEl.value;
  const capitEl = document.getElementById("sb-focus-capitulated");
  if (capitEl) focus.availableIfCapitulated = capitEl.value;
  const warEl = document.getElementById("sb-focus-warwith");
  const selEl = document.getElementById("sb-focus-selecteffect");
  if (warEl) focus.willLeadToWarWith = warEl.value.trim();
  if (selEl) focus.selectEffect = selEl.value.trim();

  const nx = parseInt(sbFocusXEl.value);
  const ny = parseInt(sbFocusYEl.value);
  // #sidebar-coordinate-never-saved — compare BEFORE assigning, or nothing can tell a retyped coordinate
  // from the one already there.
  const gridChanged = (!isNaN(nx) && nx !== focus.x) || (!isNaN(ny) && ny !== focus.y);
  if (!isNaN(nx)) focus.x = nx;
  if (!isNaN(ny)) focus.y = ny;

  // Typing a coordinate IS moving the focus, and a drag that happened before this edit is still unwritten.
  // Both have to outlive the line below, which exists only to hand displayX/Y back to resolveLayout.
  if (gridChanged || focus.moved) focus.positionDirty = true;

  // Reset moved flag so resolveLayout can re-calculate displayX/Y from new focus.x/y
  focus.moved = false;

  // Sync with localization system
  localizationMap[focus.id] = nextName;
  localizationDescMap[`${focus.id}_desc`] = nextDesc;
  pendingLocalizationEdits.set(focus.id, { name: nextName, desc: nextDesc });

  markDirty(true);
  refreshParsedDerived(); // Recalculate layout (displayX/Y)
  renderFocuses();
  // No setStatus on live update to avoid spam
}
