function setStatus(message, isError = false) {
  if (!statusTextEl) return;
  statusTextEl.setAttribute("aria-live", isError ? "assertive" : "polite");
  statusTextEl.textContent = message;
  statusTextEl.classList.toggle("status-text--error", Boolean(isError));
  syncOpenDialogErrorBanner(message, isError);
}

/** Clipboard API is unavailable or blocked on some origins; fall back to execCommand. */
async function copyTextToClipboard(text) {
  try {
    // Priority 1: Native Electron Bridge (most reliable)
    if (window.focusEditor && typeof window.focusEditor.writeToClipboard === "function") {
      await window.focusEditor.writeToClipboard(text);
      return;
    }
    // Priority 2: Modern Navigator API
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return;
    }
    // Priority 3: Ghost element fallback
    const ghost = document.createElement("textarea");
    ghost.value = text;
    ghost.style.cssText = "position:fixed;pointer-events:none;opacity:0;left:-9999px;";
    document.body.appendChild(ghost);
    ghost.select();
    document.execCommand("copy");
    document.body.removeChild(ghost);
  } catch (err) {
    console.error("Clipboard failed:", err);
    throw new Error("Clipboard access denied. Please try again.");
  }
}


function pathEquals(a, b) {
  const normalize = (p) =>
    String(p || "")
      .trim()
      .replace(/\//g, "\\")
      .replace(/[\\]+$/, "")
      .toLowerCase();
  const left = normalize(a);
  const right = normalize(b);
  return !!left && left === right;
}

function hasOpenDialog() {
  return Boolean(document.querySelector("dialog[open]"));
}

/** Modal <dialog> + ::backdrop use the top layer; toolbar status sits underneath. Mirror errors into the open dialog so they stay visible. */
function clearDialogInlineStatus(dialog) {
  if (!dialog) return;
  const host = dialog.querySelector(".dialog-inline-status-host");
  if (!host) return;
  host.textContent = "";
  host.removeAttribute("role");
  host.classList.remove("dialog-inline-status-host--visible", "dialog-inline-status-host--error");
}

function syncOpenDialogErrorBanner(message, isError) {
  const openDialog = document.querySelector("dialog[open]");
  if (!openDialog) return;
  const showError = Boolean(isError && String(message || "").trim());
  if (!showError) {
    clearDialogInlineStatus(openDialog);
    return;
  }
  let host = openDialog.querySelector(".dialog-inline-status-host");
  if (!host) {
    host = document.createElement("div");
    host.className = "dialog-inline-status-host";
    openDialog.insertBefore(host, openDialog.firstChild);
  }
  host.textContent = message;
  host.setAttribute("role", "alert");
  host.classList.add("dialog-inline-status-host--error", "dialog-inline-status-host--visible");
}

for (const dlg of document.querySelectorAll("dialog")) {
  dlg.addEventListener("close", () => clearDialogInlineStatus(dlg));
}

function setDiagnostics(lines = []) {
  if (!diagnosticsEl) return;
  diagnosticsEl.textContent = lines.join("\n");
}

function updateHistoryButtons() {
  if (!HISTORY_ENABLED) {
    if (undoBtn) undoBtn.disabled = true;
    if (redoBtn) redoBtn.disabled = true;
    return;
  }
  if (undoBtn) undoBtn.disabled = !parsed || undoHistory.length === 0 || saveInFlight || loadInFlight;
  if (redoBtn) redoBtn.disabled = !parsed || redoHistory.length === 0 || saveInFlight || loadInFlight;
}

function refreshPrimaryButtons() {
  if (loadBtn) {
    loadBtn.disabled = saveInFlight || loadInFlight;
    loadBtn.setAttribute("aria-busy", loadInFlight ? "true" : "false");
  }
  if (saveBtn) {
    saveBtn.disabled = !parsed || !dirty || saveInFlight || loadInFlight;
    saveBtn.setAttribute("aria-busy", saveInFlight ? "true" : "false");
  }
  if (addFocusBtn) addFocusBtn.disabled = !parsed || saveInFlight || loadInFlight;
  const treeOwnerBtn = document.getElementById("treeOwnerBtn");
  if (treeOwnerBtn) treeOwnerBtn.disabled = !parsed || saveInFlight || loadInFlight;
  updateHistoryButtons();
  updateToolbarHints();
}

function updateToolbarHints() {
  if (loadBtn) {
    loadBtn.title = saveInFlight || loadInFlight ? "Wait for the current operation to finish." : "Choose and load a focus tree (.txt) from disk.";
  }
  if (saveBtn) {
    if (saveInFlight) saveBtn.title = "Saving to disk...";
    else if (loadInFlight) saveBtn.title = "Wait until loading finishes.";
    else if (!parsed) saveBtn.title = "Load a focus tree first.";
    else if (!dirty) saveBtn.title = "Nothing to save yet.";
    else saveBtn.title = "Write the focus tree (and pending localization, if any) to disk.";
  }
  if (addFocusBtn) {
    if (!parsed) addFocusBtn.title = "Load a focus tree first, then you can add focuses.";
    else if (saveInFlight || loadInFlight) addFocusBtn.title = "Wait for the current operation to finish.";
    else addFocusBtn.title = "Add a new focus at the current view center.";
  }
  if (undoBtn) {
    if (!HISTORY_ENABLED) undoBtn.title = "Undo is not enabled in this build.";
    else if (undoBtn.disabled) {
      undoBtn.title = !parsed
        ? "Load a focus tree first."
        : saveInFlight || loadInFlight
          ? "Wait for load or save to finish."
          : "Nothing to undo yet.";
    } else undoBtn.title = "Undo the last edit (keyboard: Ctrl+Z).";
  }
  if (redoBtn) {
    if (!HISTORY_ENABLED) redoBtn.title = "Redo is not enabled in this build.";
    else if (redoBtn.disabled) {
      redoBtn.title = !parsed
        ? "Load a focus tree first."
        : saveInFlight || loadInFlight
          ? "Wait for load or save to finish."
          : "Nothing to redo yet.";
    } else {
      redoBtn.title =
        "Redo the last undone change (Ctrl+Shift+Z, Ctrl+Y, or Ctrl+X — Ctrl+X is redo here, not cut to clipboard).";
    }
  }
  if (zoomOutBtn) {
    zoomOutBtn.title = saveInFlight || loadInFlight ? "Wait for load or save to finish." : "Zoom out (keyboard: Z or Ctrl+minus).";
  }
  if (zoomInBtn) {
    zoomInBtn.title = saveInFlight || loadInFlight ? "Wait for load or save to finish." : "Zoom in (keyboard: X or Ctrl+plus).";
  }
  if (zoomLabelEl) {
    zoomLabelEl.title = "Current zoom. Reset with Ctrl+0 (see Help).";
  }
  if (autosaveToggleEl) {
    let autTitle =
      "When checked, saves about every 30 seconds if the tree has unsaved changes, no blocking dialog is open, and validation passes.";
    if (
      autosaveEnabled &&
      dirty &&
      pendingLocalizationEdits.size > 0 &&
      !String(localizationTargetPath || "").trim()
    ) {
      autTitle +=
        " Autosave is paused until you choose a localization file for pending name/description edits (status line explains).";
    }
    autosaveToggleEl.title = autTitle;
  }
  if (diagnosticsEl) {
    diagnosticsEl.title =
      "Layout and validation notes from the last check. When Save is blocked, read errors here first.";
  }
  if (filePathEl) {
    const p = String(filePathEl.value || "").trim();
    filePathEl.title = p
      ? `Read-only — full path (use Load to open a different file):\n${p}`
      : "Read-only. No file loaded yet — use Load to choose a national_focus .txt file.";
  }
  if (rootInfoEl) {
    const t = String(rootInfoEl.textContent || "").trim();
    rootInfoEl.title = t
      ? `Workspace and game detection:\n${t}`
      : "Shows the active mod root and Hearts of Iron IV install detection after the editor connects to the server.";
  }
}

function cloneJson(value) {
  if (value === undefined || value === null) return value;
  return JSON.parse(JSON.stringify(value));
}

function snapshotEditorState() {
  return {
    parsed: cloneJson(parsed),
    sourceText: sourceText,
    // #source-patch-invalidates-block-offsets — part of the unsaved state, so Ctrl+Z puts the panel back
    // with everything else. Survives the cloneJson in pushUndoEntry precisely because it is plain data.
    pendingTreeHeaderEdits: [...pendingTreeHeaderEdits.entries()],
    dirty,
    selectedIds: [...selectedIds],
    pendingEffectEdits: [...pendingEffectEdits.entries()].map(([k, v]) => [k, [...(v || [])]]),
    pendingEffectRemovals: [...pendingEffectRemovals.entries()].map(([k, v]) => [k, [...(v || [])]]),
    pendingEffectBlockRemovals: [...pendingEffectBlockRemovals.entries()].map(([k, v]) => [k, [...(v || [])]]),
    pendingNewFocuses: [...pendingNewFocuses.entries()].map(([k, v]) => [k, cloneJson(v)]),
    pendingDeletedBlocks: [...pendingDeletedBlocks.entries()].map(([k, v]) => [k, cloneJson(v)]),
    pendingLocalizationEdits: [...pendingLocalizationEdits.entries()].map(([k, v]) => [k, cloneJson(v)]),
    pendingLocalizationDeletes: [...pendingLocalizationDeletes],
    localizationMap: cloneJson(localizationMap),
    localizationDescMap: cloneJson(localizationDescMap),
    localizationTargetPath,
  };
}

async function restoreEditorState(snapshot) {
  if (!snapshot) return;
  isApplyingHistory = true;
  try {
    sourceText = typeof snapshot.sourceText === "string" ? snapshot.sourceText : "";
    pendingTreeHeaderEdits = new Map(snapshot.pendingTreeHeaderEdits || []);
    dirty = Boolean(snapshot.dirty);
    applyChromeDirtyIndicator();
    // Important: never restore by reference, or future edits mutate history entries.
    parsed = snapshot.parsed ? cloneJson(snapshot.parsed) : null;
    selectedIds = new Set(snapshot.selectedIds || []);
    pendingEffectEdits = new Map((snapshot.pendingEffectEdits || []).map(([k, v]) => [k, [...(v || [])]]));
    pendingEffectRemovals = new Map((snapshot.pendingEffectRemovals || []).map(([k, v]) => [k, new Set(v || [])]));
    pendingEffectBlockRemovals = new Map((snapshot.pendingEffectBlockRemovals || []).map(([k, v]) => [k, [...(v || [])]]));
    pendingNewFocuses = new Map((snapshot.pendingNewFocuses || []).map(([k, v]) => [k, cloneJson(v)]));
    pendingDeletedBlocks = new Map((snapshot.pendingDeletedBlocks || []).map(([k, v]) => [k, cloneJson(v)]));
    pendingLocalizationEdits = new Map((snapshot.pendingLocalizationEdits || []).map(([k, v]) => [k, cloneJson(v)]));
    pendingLocalizationDeletes = new Set(snapshot.pendingLocalizationDeletes || []);
    localizationMap = snapshot.localizationMap ? cloneJson(snapshot.localizationMap) : {};
    localizationDescMap = snapshot.localizationDescMap ? cloneJson(snapshot.localizationDescMap) : {};
    localizationTargetPath = typeof snapshot.localizationTargetPath === "string" ? snapshot.localizationTargetPath : "";
    
    cancelPrereqLinkMode(true);
    cancelMutexLinkMode(true);
    if (parsed) {
      refreshParsedDerived();
      await resolveIcons(parsed);
      renderFocuses();
      markDirty(dirty);
      // #undo-leaves-the-sidebar-stale — REPAINT THE SIDEBAR FROM THE RESTORED MODEL.
      //
      // Undo restored `parsed` and redrew the canvas, but never refilled the property sidebar, so after
      // Ctrl+Z the boxes still showed the text that had just been undone. Measured: the model reverted
      // (cost 4 -> 3) while the name box still read the edited value.
      //
      // That is worse than a cosmetic lag. applySidebarLiveChanges reads these inputs, so the next
      // keystroke anywhere in the sidebar would write the stale values straight back over the restored
      // model - undoing the undo, silently.
      //
      // Safe here: pushUndoSnapshot returns early while isApplyingHistory is true, so repainting cannot
      // add a history entry of its own.
      openSidebarForSelection();
    } else {
      if (canvasEl) canvasEl.querySelectorAll(".node").forEach((n) => n.remove());
      setDiagnostics([]);
      markDirty(false);
    }
  } finally {
    isApplyingHistory = false;
    updateHistoryButtons();
  }
}

function clearHistory() {
  undoHistory = [];
  redoHistory = [];
  updateHistoryButtons();
}

function snapshotSignature(snapshot) {
  try {
    return JSON.stringify(snapshot);
  } catch (_err) {
    return `history:${Date.now()}:${Math.random()}`;
  }
}

function pushUndoEntry(snapshot) {
  if (!HISTORY_ENABLED || !snapshot || isApplyingHistory || !parsed) return;
  const entry = cloneJson(snapshot);
  undoHistory.push(entry);
  while (undoHistory.length > HISTORY_MAX_ENTRIES) undoHistory.shift();
  redoHistory = [];
  updateHistoryButtons();
}

// #sidebar-edits-outside-undo — which sidebar field is mid-edit, as "<focus id>|<element id>".
//
// applySidebarLiveChanges runs on the "input" event, i.e. on EVERY KEYSTROKE. Snapshotting each one would
// fill the 80-entry history with single characters and make Ctrl+Z step backwards letter by letter — worse
// than no undo at all. So one snapshot is taken per editing BURST: the first change to a given field of a
// given focus pushes the state as it was before you started typing there, and the rest of the burst adds
// nothing. Ctrl+Z then returns that field to what it said before you touched it, which is what a person
// means by undo.
let sidebarUndoBurstKey = null;

function pushUndoSnapshot() {
  if (isApplyingHistory || !parsed) return;
  // Any other undoable action ends the current typing burst, so returning to the same field afterwards
  // starts a new one instead of being silently folded into the old entry.
  sidebarUndoBurstKey = null;
  pushUndoEntry(snapshotEditorState());
}

async function undoLastChange() {
  if (!HISTORY_ENABLED) return;
  if (!parsed || undoHistory.length === 0) return;
  const current = snapshotEditorState();
  const prev = undoHistory.pop();
  redoHistory.push(cloneJson(current));
  while (redoHistory.length > HISTORY_MAX_ENTRIES) redoHistory.shift();
  await restoreEditorState(prev);
  setStatus("Undo applied.");
}

async function redoLastChange() {
  if (!HISTORY_ENABLED) return;
  if (!parsed || redoHistory.length === 0) return;
  const current = snapshotEditorState();
  const next = redoHistory.pop();
  undoHistory.push(cloneJson(current));
  while (undoHistory.length > HISTORY_MAX_ENTRIES) undoHistory.shift();
  await restoreEditorState(next);
  setStatus("Redo applied.");
}

function snapshotResolvedLayout(parsedData) {
  if (!parsedData) return;
  parsedData.focuses.forEach((focus) => {
    focus.baseDisplayX = focus.displayX;
    focus.baseDisplayY = focus.displayY;
  });
}

function iconSourceLabel(source) {
  if (source === "browser-asset") return "icon: mapped";
  if (source === "dds-only") return "icon: dds-only";
  if (source === "missing") return "icon: missing";
  if (source === "error") return "icon: error";
  return "icon: none";
}

function isTypingTarget(el) {
  if (!el) return false;
  const tag = String(el.tagName || "").toLowerCase();
  return tag === "input" || tag === "textarea" || tag === "select" || el.isContentEditable;
}

function updateZoomLabel() {
  if (!zoomLabelEl) return;
  zoomLabelEl.textContent = `${Math.round(viewScale * 100)}%`;
}

function updateLastZoomAnchorFromClient(clientX, clientY) {
  if (!canvasScrollEl) return;
  const r = canvasScrollEl.getBoundingClientRect();
  const relX = clientX - r.left;
  const relY = clientY - r.top;
  if (relX >= 0 && relX <= r.width && relY >= 0 && relY <= r.height) {
    lastZoomAnchorRel = { relX, relY };
  }
}

function setZoom(nextScale) {
  const clamped = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, Number(nextScale.toFixed(2))));
  if (clamped === viewScale) return;
  const oldScale = viewScale;
  if (!canvasScrollEl) {
    viewScale = clamped;
    updateZoomLabel();
    if (parsed) renderFocusesGeometryOnly();
    return;
  }
  const rect = canvasScrollEl.getBoundingClientRect();
  let ax = lastZoomAnchorRel ? lastZoomAnchorRel.relX : rect.width / 2;
  let ay = lastZoomAnchorRel ? lastZoomAnchorRel.relY : rect.height / 2;
  ax = Math.max(0, Math.min(ax, Math.max(0, rect.width - 1e-3)));
  ay = Math.max(0, Math.min(ay, Math.max(0, rect.height - 1e-3)));
  const contentX = canvasScrollEl.scrollLeft + ax;
  const contentY = canvasScrollEl.scrollTop + ay;
  const ratio = clamped / oldScale;

  viewScale = clamped;
  updateZoomLabel();
  if (parsed) {
    renderFocusesGeometryOnly();
    const applyScroll = () => {
      const maxL = Math.max(0, canvasScrollEl.scrollWidth - canvasScrollEl.clientWidth);
      const maxT = Math.max(0, canvasScrollEl.scrollHeight - canvasScrollEl.clientHeight);
      canvasScrollEl.scrollLeft = Math.max(0, Math.min(contentX * ratio - ax, maxL));
      canvasScrollEl.scrollTop = Math.max(0, Math.min(contentY * ratio - ay, maxT));
      if (lineLayerEl && canvasEl) {
        lineLayerEl.setAttribute("width", `${canvasEl.scrollWidth}`);
        lineLayerEl.setAttribute("height", `${canvasEl.scrollHeight}`);
      }
      renderConnectionLines();
    };
    requestAnimationFrame(() => {
      applyScroll();
      requestAnimationFrame(applyScroll);
    });
  } else if (lineLayerEl && canvasEl) {
    lineLayerEl.setAttribute("width", `${canvasEl.scrollWidth}`);
    lineLayerEl.setAttribute("height", `${canvasEl.scrollHeight}`);
    renderConnectionLines();
  }
}

async function fetchLocalizationMap(force = false) {
  // Skip the big re-fetch when nothing changed: same active mod as the last successful load and the map
  // is already populated. Callers that just edited localization pass force=true. (Page init + the tree
  // auto-load otherwise fetch the whole map twice on open — ~25-50 MB each on a mod like Millennium Dawn.)
  // #loc-map-follows-the-active-mod-not-the-open-tree — NAME THE MOD, OR EVERY FOCUS SHOWS ITS RAW ID.
  //
  // This asked /api/localization for nothing in particular, so the server answered for ITS active mod —
  // whatever active-mod.json last recorded. The tree on the canvas can easily belong to a different mod:
  // you open a tree by path, or from another mod, or the active mod was left pointing somewhere else. When
  // it does, none of that tree's focus ids are in the map, applyLocalization falls back to `focus.id`, and
  // every node on the canvas is labelled with its raw id.
  //
  // Worse, it did not self-correct. The cache key below was ALREADY the loaded tree's mod (loadFile writes
  // it to activeModPath a few lines before calling this), so the wrong map got stored under the right key
  // and every later load of that mod hit the cache and reused it.
  //
  // The mod is right there — loadFile has already resolved it from the path it just opened. Ask for it.
  // Falls back to the active mod when no tree is open (page init) and for a tree outside any mod, which is
  // exactly the previous behaviour for those cases.
  // ⚠️ THE CACHE KEY MUST DESCRIBE WHAT WAS ACTUALLY ASKED FOR, or it caches one mod's map under another's
  // name. That was the sharp edge here: page init runs before any tree is open, so it sent no modPath and
  // the server answered for ITS active mod — while the key below was taken from activeModPath, the mod the
  // user is really working in. The wrong map went in under the right key, and the load that followed hit
  // the guard on the next line and never refetched. Every focus stayed labelled with its raw id.
  //
  // So: pick one root, ask for THAT root, and key on it. Prefer the open tree's mod; fall back to the
  // active mod at page init. Only when neither is known do we let the server choose, and then the key says
  // so — a sentinel that cannot collide with a real path, so the next load refetches instead of reusing it.
  // ⚠️ …but NOT for a vanilla tree. inferModRootFromFocusPath only strips at common/national_focus, with
  // none of the game-root exclusion the server's detectModRootFromFocusPath has — so for a tree opened out
  // of the HOI4 install it hands back the install itself. Asking for that root is not harmful, it is just
  // wrong: the map comes back as vanilla ONLY, dropping every key the user's own mod defines (measured on
  // their `unity` mod: 111,064 keys down to 110,655). Studying a vanilla tree is ordinary, and it must not
  // cost you your mod's localisation — so fall through to the active mod, exactly as the server does when
  // detectModRootFromFocusPath returns null. #vanilla-focus-load-clears-active-mod
  // The reasoning above now lives in editorRequestModRoot, so the state and country catalogues below use
  // exactly this rule instead of a second copy of it that could drift. #editor-requests-do-not-name-the-mod
  const requestRoot = editorRequestModRoot();
  const modKey = editorRequestModKey(requestRoot);
  if (!force && _locMapModKey === modKey && Object.keys(localizationMap).length > 0) return;
  const response = await fetch(`/api/localization${editorModPathQuery(requestRoot)}`);
  const payload = await parseJsonSafe(response);
  if (!response.ok || (!payload.map && !payload.names)) {
    throw new Error(payload.error || "Localization load failed.");
  }
  localizationMap = payload.names || payload.map || {};
  localizationDescMap = payload.descriptions || {};
  _locMapModKey = modKey;
}

function applyLocalization(parsedData) {
  if (!parsedData) return;
  parsedData.focuses.forEach((focus) => {
    focus.displayName = localizationMap[focus.id] || focus.id;
    focus.displayDesc = localizationDescMap[`${focus.id}_desc`] || "";
  });
}

const GENERIC_FOCUS_ICON_KEY = "GFX_goal_generic_construct_civ_factory"; // the default the game (and our save) fall back to
let genericFocusIconUrl = ""; // resolved URL of that generic, so a no-icon focus shows it instead of a blank node
async function resolveIcons(parsedData) {
  if (!parsedData) return;
  // Resolve the generic icon alongside the real ones, so a focus with NO icon displays the same default
  // the game uses (and that we write on save) rather than an empty node.
  const uniqueKeys = [...new Set([...parsedData.focuses.map((f) => f.iconKey).filter(Boolean), GENERIC_FOCUS_ICON_KEY])];
  const iconMap = new Map();
  if (uniqueKeys.length > 0) {
    try {
      const response = await fetch("/api/icons/batch", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ keys: uniqueKeys })
      });
      if (response.ok) {
        const payload = await response.json();
        const batchMap = payload.icons || {};
        uniqueKeys.forEach((key) => {
          const res = batchMap[key];
          if (res) {
            const bestUrl = res.imageUrl || res.url || "";
            if (bestUrl) {
              iconMap.set(key, { url: bestUrl, source: res.source || "asset" });
            } else {
              iconMap.set(key, { url: "", source: res.ddsOnly ? "dds-only" : "missing" });
            }
          } else {
            iconMap.set(key, { url: "", source: "missing" });
          }
        });
      } else {
        throw new Error("Batch request failed");
      }
    } catch (err) {
      console.error("Batch icons resolution failed, falling back to individual fetches", err);
      await Promise.all(uniqueKeys.map(async (key) => {
        try {
          const response = await fetch(`/api/icon?key=${encodeURIComponent(key)}`);
          const payload = await parseJsonSafe(response);
          const bestUrl = payload.imageUrl || payload.url || "";
          if (response.ok && bestUrl) {
            iconMap.set(key, { url: bestUrl, source: payload.source || "asset" });
          } else {
            iconMap.set(key, { url: "", source: payload.ddsOnly ? "dds-only" : "missing" });
          }
        } catch (_err) {
          iconMap.set(key, { url: "", source: "error" });
        }
      }));
    }
  }
  genericFocusIconUrl = (iconMap.get(GENERIC_FOCUS_ICON_KEY) || {}).url || "";
  parsedData.focuses.forEach((focus) => {
    if (!focus.iconKey) {
      focus.iconUrl = genericFocusIconUrl; // show the generic default rather than a blank node
      focus.iconSource = "none";            // keep "none" so labels/warnings still say "no icon chosen"
      return;
    }
    const resolved = iconMap.get(focus.iconKey);
    focus.iconUrl = (resolved && resolved.url) ? resolved.url : genericFocusIconUrl; // missing → generic, never blank
    focus.iconSource = (resolved && resolved.url) ? resolved.source : "missing";
  });
}

function markDirty(value) {
  dirty = value;
  const tag = dirty ? " (unsaved)" : "";
  setStatus(`${parsed ? `Loaded ${parsed.focuses.length} focuses` : "Idle"}${tag}`);
  if (value) scheduleAutoValidation();
  refreshPrimaryButtons();
  applyChromeDirtyIndicator();
}

function markFocusesDirty(ids) {
  const arr = Array.isArray(ids) ? ids : [ids];
  arr.forEach((id) => {
    const key = String(id || "").trim();
    if (!key) return;
    dirtyFocusIds.add(key);
    managedEffectValidationCache.delete(key);
  });
}

function buildValidationScopeIds() {
  if (!parsed || !Array.isArray(parsed.focuses) || dirtyFocusIds.size === 0) return null;
  const byId = new Map(parsed.focuses.map((f) => [f.id, f]));
  const out = new Set();
  dirtyFocusIds.forEach((id) => {
    if (!byId.has(id)) return;
    out.add(id);
    const focus = byId.get(id);
    (focus.prerequisites || []).forEach((pid) => {
      if (byId.has(pid)) out.add(pid);
    });
    (focus.mutuallyExclusive || []).forEach((mid) => {
      if (byId.has(mid)) out.add(mid);
    });
  });
  parsed.focuses.forEach((focus) => {
    if (!focus || !focus.id) return;
    const prereqs = Array.isArray(focus.prerequisites) ? focus.prerequisites : [];
    const mutex = Array.isArray(focus.mutuallyExclusive) ? focus.mutuallyExclusive : [];
    if (prereqs.some((id) => dirtyFocusIds.has(id)) || mutex.some((id) => dirtyFocusIds.has(id))) {
      out.add(focus.id);
    }
  });
  return out;
}

function getManagedValidationSnapshot(focusId) {
  const id = String(focusId || "").trim();
  if (!id) return { managed: [], keys: new Set() };
  const cached = managedEffectValidationCache.get(id);
  if (cached) return cached;
  const managed = getEffectiveManagedEffectLines(id);
  const keys = collectTopManagedEffectKeys(managed);
  const snap = { managed, keys };
  managedEffectValidationCache.set(id, snap);
  return snap;
}

/** Returns nodes [a, b, …] forming a directed prerequisite cycle, or null if none. */
function findPrerequisiteCycleInTree(focusList) {
  if (!Array.isArray(focusList) || focusList.length === 0) return null;
  const byId = new Map(focusList.map((f) => [f.id, f]));
  const children = new Map();
  focusList.forEach((f) => {
    (f.prerequisites || []).forEach((p) => {
      if (!byId.has(p)) return;
      if (!children.has(p)) children.set(p, []);
      children.get(p).push(f.id);
    });
  });
  const WHITE = 0;
  const GRAY = 1;
  const BLACK = 2;
  const state = new Map();
  byId.forEach((_f, id) => state.set(id, WHITE));
  const stack = [];
  function dfs(u) {
    state.set(u, GRAY);
    stack.push(u);
    const outs = children.get(u) || [];
    for (let i = 0; i < outs.length; i += 1) {
      const w = outs[i];
      const st = state.get(w);
      if (st === GRAY) {
        const idx = stack.indexOf(w);
        if (idx >= 0) return stack.slice(idx);
      } else if (st === WHITE) {
        const cy = dfs(w);
        if (cy) return cy;
      }
    }
    stack.pop();
    state.set(u, BLACK);
    return null;
  }
  for (const id of byId.keys()) {
    if (state.get(id) === WHITE) {
      const cy = dfs(id);
      if (cy) return cy;
    }
  }
  return null;
}

function collectValidationIssues(parsedData, options = {}) {
  const lightweight = Boolean(options.lightweight);
  const scopeIds = options.scopeIds instanceof Set ? options.scopeIds : null;
  const skipManaged = Boolean(options.skipManaged);
  const issues = [];
  if (!parsedData || !Array.isArray(parsedData.focuses)) {
    issues.push({ level: "error", message: "No focus tree is loaded." });
    return issues;
  }
  const byId = new Map();
  const idCounts = new Map();
  parsedData.focuses.forEach((focus) => {
    const id = String(focus.id || "");
    idCounts.set(id, (idCounts.get(id) || 0) + 1);
    byId.set(id, focus);
    if (!isValidFocusId(id)) {
      issues.push({ level: "error", message: `Invalid focus id format: ${id}` });
    }
    if (focus.iconKey && !/^[A-Za-z0-9_\.:-]+$/.test(String(focus.iconKey))) {
      issues.push({ level: "warn", message: `Icon key has unsupported characters: ${id} -> ${focus.iconKey}` });
    }
    if (!focus.iconKey) {
      issues.push({ level: "warn", message: `No icon chosen for ${id} — the game will show a generic default. Pick an icon for a custom look.` });
    }
  });
  idCounts.forEach((count, id) => {
    if (count > 1) issues.push({ level: "error", message: `Duplicate focus id found: ${id}` });
  });
  const focusList = Array.isArray(parsedData.focuses) ? parsedData.focuses : [];
  const shouldCheckFocus = (focusId) => !scopeIds || scopeIds.has(focusId);
  focusList.forEach((focus) => {
    const fid = focus.id;
    if (!shouldCheckFocus(fid)) return;
    const prereqs = Array.isArray(focus.prerequisites) ? focus.prerequisites : [];
    prereqs.forEach((pid) => {
      if (pid === fid) issues.push({ level: "error", message: `Self prerequisite found: ${fid} -> ${pid}` });
      else if (!byId.has(pid)) issues.push({ level: "error", message: `Missing prerequisite target: ${fid} -> ${pid}` });
    });
    const mutexes = Array.isArray(focus.mutuallyExclusive) ? focus.mutuallyExclusive : [];
    mutexes.forEach((mid) => {
      if (mid === fid) issues.push({ level: "error", message: `Self mutually_exclusive found: ${fid} ↔ ${mid}` });
      else if (!byId.has(mid)) issues.push({ level: "warn", message: `Missing mutually_exclusive target: ${fid} ↔ ${mid}` });
      else {
        const other = byId.get(mid);
        const otherRefs = Array.isArray(other.mutuallyExclusive) ? other.mutuallyExclusive : [];
        if (!otherRefs.includes(fid)) {
          issues.push({ level: "warn", message: `Asymmetric mutually_exclusive: ${fid} ↔ ${mid}` });
        }
      }
    });
  });
  if (!lightweight && !scopeIds) {
    const prereqCycle = findPrerequisiteCycleInTree(parsedData.focuses);
    if (prereqCycle && prereqCycle.length > 0) {
      issues.push({
        level: "error",
        message: `Prerequisite cycle (impossible order): ${prereqCycle.join(" → ")}`,
      });
    }
  }
  if (!skipManaged) {
    focusList.forEach((focus) => {
      if (!shouldCheckFocus(focus.id)) return;
      const snap = getManagedValidationSnapshot(focus.id);
      const managed = snap.managed;
      const keys = snap.keys;
      if (keys.has("add_to_faction_tension")) {
        issues.push({
          level: "warn",
          message:
            `Effect scope risk on ${focus.id}: add_to_faction_tension may fail outside valid faction scope.`,
        });
      }
      if (keys.has("add_legitimacy")) {
        issues.push({
          level: "warn",
          message:
            `Effect scope risk on ${focus.id}: add_legitimacy may fail if the current country/government does not use legitimacy.`,
        });
      }

      managed.forEach((line) => {
        const t = String(line || "").trim();
        // #flag-block-form-truncated — same narrowing as the serializer: a block value is not a flag
        // token, so this warning has no business inspecting it.
        const m = t.match(/^(set_country_flag|clr_country_flag|set_global_flag|clr_global_flag)\s*=\s*([^\s{]\S*)/);
        if (!m) return;
        const keyName = m[2];
        // #flag-token-mangled, second half — THE WARNING NEVER ADOPTED THE RULE ITS SIBLING LEARNED.
        // The serializer was widened to preserve @ . - [ ] because those are what HOI4 actually writes:
        // 100 of vanilla's 8,393 scalar flag assignments carry an @ (dynamic scope, `warlord_supports_@ROOT`)
        // and 258 of Millennium Dawn's 14,122. This test stayed on [A-Za-z0-9_], so it cried "Suspicious
        // flag token … not filename/path" over hundreds of lines the game itself produces — and which the
        // serializer, three thousand lines away, deliberately leaves alone. Same charset, one rule.
        if (!/^[A-Za-z0-9_@.\-\[\]]+$/.test(keyName)) {
          issues.push({
            level: "warn",
            message:
              `Suspicious flag token on ${focus.id}: "${t}". Use a plain flag key token (letters/numbers/_), not filename/path.`,
          });
        }
      });
    });
  }
  if (pendingLocalizationEdits.size > 0 && !localizationTargetPath) {
    issues.push({
      level: "warn",
      message:
        "Pending localization edits exist but no localization file is selected yet. Save will ask you to choose one.",
    });
  }
  // Hot path profile note:
  // full rewrite+parse verification is expensive on large trees; keep it for non-lightweight runs.
  if (!lightweight && !scopeIds) {
    try {
      const rewritten = rewriteCoordinates(sourceText, parsedData);
      resolveLayout(parseFocuses(rewritten));
    } catch (err) {
      const msg = err && err.message ? err.message : String(err);
      issues.push({ level: "error", message: `Generated output parse check failed: ${msg}` });
    }
  }
  return issues;
}

function runValidationAndReport(options = {}) {
  const silent = Boolean(options.silent);
  const lightweight = Boolean(options.lightweight);
  const scopeIds = options.scopeIds instanceof Set ? options.scopeIds : null;
  const skipManaged = Boolean(options.skipManaged);
  const forceFresh = Boolean(options.forceFresh);
  const cacheKey = [
    lightweight ? "1" : "0",
    String(focusMutationVersion),
    scopeIds ? `scope:${scopeIds.size}` : "scope:all",
    skipManaged ? "sm:1" : "sm:0",
    String(pendingLocalizationEdits.size),
    String(localizationTargetPath || ""),
  ].join("|");
  if (!forceFresh && silent && cacheKey === lastValidationCacheKey) {
    return lastValidationCachedResult;
  }
  const issues = collectValidationIssues(parsed, { lightweight, scopeIds, skipManaged });
  const errors = issues.filter((i) => i.level === "error");
  const warns = issues.filter((i) => i.level === "warn");
  if (issues.length === 0) {
    if (!silent) setStatus("Validation passed. No issues found.");
    updateDiagnosticsPanel();
    const result = { ok: true, errors: 0, warnings: 0 };
    lastValidationCacheKey = cacheKey;
    lastValidationCachedResult = result;
    return result;
  }
  const lines = [
    `validation: errors ${errors.length} | warnings ${warns.length}`,
    ...issues.slice(0, 24).map((issue) => `- [${issue.level}] ${issue.message}`),
  ];
  if (issues.length > 24) lines.push(`- ... and ${issues.length - 24} more`);
  setDiagnostics(lines);
  if (errors.length > 0) {
    if (!silent) setStatus(`Validation failed: ${errors.length} error(s), ${warns.length} warning(s).`, true);
    const result = { ok: false, errors: errors.length, warnings: warns.length };
    lastValidationCacheKey = cacheKey;
    lastValidationCachedResult = result;
    return result;
  }
  if (!silent) setStatus(`Validation passed with ${warns.length} warning(s).`);
  const result = { ok: true, errors: 0, warnings: warns.length };
  lastValidationCacheKey = cacheKey;
  lastValidationCachedResult = result;
  return result;
}

function scheduleDeferredDeepValidation() {
  if (!parsed || saveInFlight || loadInFlight) return;
  deferredDeepValidationToken += 1;
  const token = deferredDeepValidationToken;
  if (deferredDeepValidationTimer) {
    clearTimeout(deferredDeepValidationTimer);
    deferredDeepValidationTimer = 0;
  }
  if (deferredDeepValidationRaf) {
    cancelAnimationFrame(deferredDeepValidationRaf);
    deferredDeepValidationRaf = 0;
  }
  deferredDeepValidationPending = true;
  deferredDeepValidationTimer = setTimeout(() => {
    if (token !== deferredDeepValidationToken) return;
    const focusList = Array.isArray(parsed && parsed.focuses) ? parsed.focuses.slice() : [];
    let idx = 0;
    const deepIssues = [];
    const step = () => {
      if (token !== deferredDeepValidationToken) return;
      const focus = focusList[idx];
      if (!focus) {
        lastDeferredDeepIssues = deepIssues;
        deferredDeepValidationPending = false;
        return;
      }
      idx += 1;
      const snap = getManagedValidationSnapshot(focus.id);
      const managed = snap.managed;
      const keys = snap.keys;
      if (keys.has("add_to_faction_tension")) {
        deepIssues.push({
          level: "warn",
          message: `Effect scope risk on ${focus.id}: add_to_faction_tension may fail outside valid faction scope.`,
        });
      }
      if (keys.has("add_legitimacy")) {
        deepIssues.push({
          level: "warn",
          message:
            `Effect scope risk on ${focus.id}: add_legitimacy may fail if the current country/government does not use legitimacy.`,
        });
      }

      setTimeout(step, 0);
    };
    step();
  }, DEFERRED_DEEP_VALIDATE_DELAY_MS);
}

function scheduleAutoValidation() {
  if (!parsed || saveInFlight || loadInFlight) return;
  if (autoValidateTimer) clearTimeout(autoValidateTimer);
  autoValidateTimer = setTimeout(() => {
    autoValidateTimer = null;
    if (!parsed || saveInFlight || loadInFlight) return;
    const scopeIds = buildValidationScopeIds();
    runValidationAndReport({
      silent: true,
      lightweight: true,
      scopeIds,
      skipManaged: true,
    });
    scheduleDeferredDeepValidation();
    dirtyFocusIds.clear();
  }, AUTO_VALIDATE_DEBOUNCE_MS);
}

function toCanvasX(gridX) {
  return Math.round((BASE_OFFSET + viewportShiftX + gridX * GRID_X) * viewScale);
}

function toCanvasY(gridY) {
  return Math.round((BASE_OFFSET + viewportShiftY + gridY * GRID_Y) * viewScale);
}

function toGridX(canvasX) {
  return Math.round((canvasX / viewScale - BASE_OFFSET - viewportShiftX) / GRID_X);
}

function toGridY(canvasY) {
  return Math.round((canvasY / viewScale - BASE_OFFSET - viewportShiftY) / GRID_Y);
}

function clientToCanvasContent(clientX, clientY) {
  if (!canvasScrollEl) {
    return { x: 0, y: 0 };
  }
  const r = canvasScrollEl.getBoundingClientRect();
  return {
    x: clientX - r.left + canvasScrollEl.scrollLeft,
    y: clientY - r.top + canvasScrollEl.scrollTop,
  };
}

function rectsIntersect(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax + aw > bx && ay + ah > by && bx + bw > ax && by + bh > ay;
}

function applySelectionClass() {
  if (!canvasEl) return;
  canvasEl.querySelectorAll(".node").forEach((node) => {
    const id = node.dataset.focusId || "";
    node.classList.toggle("node--selected", Boolean(id && selectedIds.has(id)));
  });
  if (typeof syncFocusEditRow === "function") syncFocusEditRow();
}

function getEffectiveCountryTag() {
  return (
    inferCountryTagFromLoadedPath() ||
    inferCountryTagFromParsedFocuses() ||
    "ZZZ"
  );
}

function getFocusById(focusId) {
  if (!parsed || !focusId) return null;
  if (focusByIdCache && focusByIdCache.has(focusId)) {
    return focusByIdCache.get(focusId);
  }
  const hit = parsed.focuses.find((f) => f.id === focusId) || null;
  if (hit) focusByIdCache.set(focusId, hit);
  return hit;
}

function getSelectedFocusSingle() {
  if (!parsed || selectedIds.size !== 1) return null;
  const [id] = [...selectedIds];
  return getFocusById(id);
}

function startMutexLinkMode(focusId, clientX, clientY, mode = "add") {
  const focus = getFocusById(focusId);
  if (!focus) return;
  if (prereqLinkState) cancelPrereqLinkMode(true);
  const pos = clientToCanvasContent(clientX, clientY);
  mutexLinkState = {
    sourceId: focus.id,
    mode: mode === "remove" ? "remove" : "add",
    cursorX: pos.x,
    cursorY: pos.y,
  };
  setStatus(
    mutexLinkState.mode === "remove"
      ? `Mutually exclusive unlink: click target focus to remove ${focus.id} ↔ target. Esc/click empty space to cancel.`
      : `Mutually exclusive link: click another focus to pair with ${focus.id}. Esc/click empty space to cancel.`
  );
  renderConnectionLines();
}

function cancelMutexLinkMode(silent = false) {
  if (!mutexLinkState) return;
  mutexLinkState = null;
  if (!silent) setStatus("Mutually exclusive link canceled.");
  renderConnectionLines();
}

function applyMutexLink(sourceId, targetId, mode = "add") {
  if (!parsed || !sourceId || !targetId || sourceId === targetId) return false;
  const source = getFocusById(sourceId);
  const target = getFocusById(targetId);
  if (!source || !target) return false;
  if (!Array.isArray(source.mutuallyExclusive)) source.mutuallyExclusive = [];
  if (!Array.isArray(target.mutuallyExclusive)) target.mutuallyExclusive = [];
  if (mode === "remove") {
    const beforeSource = source.mutuallyExclusive.length;
    const beforeTarget = target.mutuallyExclusive.length;
    if (!source.mutuallyExclusive.includes(target.id) && !target.mutuallyExclusive.includes(source.id)) {
      setStatus(`No mutually exclusive link to remove: ${source.id} ↔ ${target.id}.`, true);
      return false;
    }
    pushUndoSnapshot();
    source.mutuallyExclusive = source.mutuallyExclusive.filter((id) => id !== target.id);
    target.mutuallyExclusive = target.mutuallyExclusive.filter((id) => id !== source.id);
    if (source.mutuallyExclusive.length === beforeSource && target.mutuallyExclusive.length === beforeTarget) {
      setStatus(`No mutually exclusive link to remove: ${source.id} ↔ ${target.id}.`, true);
      return false;
    }
    // #mutex-rebuild-eats-a-commented-out-focus — both ends edited → both blocks may be rebuilt on save.
    source.mutexEdited = true;
    target.mutexEdited = true;
    markFocusesDirty([source.id, target.id]);
    markDirty(true);
    refreshParsedDerived();
    renderFocuses();
    if (selectedIds.has(source.id) || selectedIds.has(target.id)) {
      openSidebarForSelection([...selectedIds][0]); // Refresh existing sidebar
    }
    setStatus(`Mutually exclusive removed: ${source.id} ↔ ${target.id}`);
    return true;
  }
  if (source.mutuallyExclusive.includes(target.id) && target.mutuallyExclusive.includes(source.id)) {
    setStatus(`Mutually exclusive already linked: ${source.id} ↔ ${target.id}`);
    return false;
  }
  pushUndoSnapshot();
  if (!source.mutuallyExclusive.includes(target.id)) source.mutuallyExclusive.push(target.id);
  if (!target.mutuallyExclusive.includes(source.id)) target.mutuallyExclusive.push(source.id);
  // #mutex-rebuild-eats-a-commented-out-focus — both ends edited → both blocks may be rebuilt on save.
  source.mutexEdited = true;
  target.mutexEdited = true;
  markFocusesDirty([source.id, target.id]);
  markDirty(true);
  refreshParsedDerived();
  renderFocuses();
  if (selectedIds.has(source.id) || selectedIds.has(target.id)) {
    openSidebarForSelection([...selectedIds][0]); // Refresh existing sidebar
  }
  setStatus(`Mutually exclusive linked: ${source.id} ↔ ${target.id}`);
  return true;
}

function startPrereqLinkMode(focusId, clientX, clientY, mode = "add") {
  const focus = getFocusById(focusId);
  if (!focus) return;
  if (mutexLinkState) cancelMutexLinkMode(true);
  const pos = clientToCanvasContent(clientX, clientY);
  prereqLinkState = {
    anchorChildId: focus.id,
    mode: mode === "remove" ? "remove" : "add",
    cursorX: pos.x,
    cursorY: pos.y,
  };
  setStatus(
    prereqLinkState.mode === "remove"
      ? `Remove requirement: click an earlier focus that "${focus.id}" still requires. Esc or empty space cancels.`
      : `Requires earlier focus: click a focus that must be finished before "${focus.id}". Esc or empty space cancels.`
  );
  renderConnectionLines();
}

function cancelPrereqLinkMode(silent = false) {
  if (!prereqLinkState) return;
  prereqLinkState = null;
  if (!silent) setStatus("Prerequisite link mode canceled.");
  renderConnectionLines();
}

/** True if some focus transitively depends on `childId` before `parentId` (adding child→parent would cycle). */
function wouldPrerequisiteCreateCycle(focusList, childId, parentId) {
  if (!parentId || !childId || parentId === childId) return true;
  const visited = new Set();
  const queue = [childId];
  while (queue.length > 0) {
    const cur = queue.shift();
    if (cur === parentId) return true;
    if (visited.has(cur)) continue;
    visited.add(cur);
    for (let i = 0; i < focusList.length; i += 1) {
      const f = focusList[i];
      const pr = f.prerequisites;
      if (!Array.isArray(pr) || !pr.includes(cur)) continue;
      if (!visited.has(f.id)) queue.push(f.id);
    }
  }
  return false;
}

/** parentId = earlier focus that must complete; childId = dependent focus. */
function applyPrereqLink(parentId, childId, mode = "add") {
  if (!parsed || !parentId || !childId || parentId === childId) return false;
  const parent = getFocusById(parentId);
  const child = getFocusById(childId);
  if (!parent || !child) return false;
  if (!Array.isArray(child.prerequisites)) child.prerequisites = [];
  if (mode === "remove") {
    if (!child.prerequisites.includes(parent.id)) {
      setStatus(`No prerequisite link to remove: ${parent.id} (required) → ${child.id}.`, true);
      return false;
    }
    pushUndoSnapshot();
    child.prerequisites = child.prerequisites.filter((id) => id !== parent.id);
    child.prereqsEdited = true;
    markFocusesDirty([child.id, parent.id]);
    markDirty(true);
    refreshParsedDerived();
    renderFocuses();
    if (selectedIds.has(child.id) || selectedIds.has(parent.id)) {
      openSidebarForSelection([...selectedIds][0]); 
    }
    setStatus(`Prerequisite removed: ${parent.id} (required) → ${child.id}`);
    return true;
  }
  if (child.prerequisites.includes(parent.id)) {
    setStatus(`Prerequisite already exists: ${parent.id} (required first) → ${child.id}`);
    return false;
  }
  if (wouldPrerequisiteCreateCycle(parsed.focuses, child.id, parent.id)) {
    setStatus(
      `Cannot link: "${child.id}" is already required before "${parent.id}" somewhere on the tree. ` +
      "That would make an impossible cycle — remove or change one of those links first.",
      true,
    );
    return false;
  }
  pushUndoSnapshot();
  child.prerequisites.push(parent.id);
  child.prereqsEdited = true;
  markFocusesDirty([child.id, parent.id]);
  markDirty(true);
  refreshParsedDerived();
  renderFocuses();
  if (selectedIds.has(child.id) || selectedIds.has(parent.id)) {
    openSidebarForSelection([...selectedIds][0]);
  }
  setStatus(`Prerequisite linked: ${parent.id} (required first) → ${child.id}`);
  return true;
}

function getAllFocusIdsSet() {
  if (!parsed) return new Set();
  return new Set(parsed.focuses.map((f) => f.id));
}

// #focus-id-unique-per-file-only — FOCUS IDS ARE GLOBALLY UNIQUE IN HOI4, not per-file.
//
// Measured on the shipping game: 81 national_focus files, 10,608 distinct focus ids, ZERO id in more than one
// file. getAllFocusIdsSet above only knows the tree currently open, so creating or renaming a focus onto an id
// that ANOTHER TREE IN THE SAME MOD already uses was accepted silently — two focuses with one id (the second
// never loads) and two trees fighting over one localisation key, because the loc key IS the focus id.
//
// Refreshed from the server rather than kept in sync by hand: the editor loads one tree at a time and has no
// picture of the others. Cached per mod for the session and invalidated on save, because it is only consulted
// on the two id-entry paths and a stale entry there would block a name the user just freed.
let focusIdsAcrossModCache = null; // { modPath, mine: Set, inherited: Set }
function invalidateFocusIdsAcrossMod() { focusIdsAcrossModCache = null; }
async function loadFocusIdsAcrossMod() {
  const modPath = (typeof getModPath === "function" ? getModPath() : "") || "";
  if (focusIdsAcrossModCache && focusIdsAcrossModCache.modPath === modPath) return focusIdsAcrossModCache;
  try {
    const r = await fetch(`/api/focus/all-ids?modPath=${encodeURIComponent(modPath)}`);
    const j = await r.json();
    if (!j || !j.ok) throw new Error((j && j.error) || "lookup failed");
    focusIdsAcrossModCache = {
      modPath,
      mine: new Map(Object.entries(j.mine || {})),
      inherited: new Map(Object.entries(j.inherited || {})),
    };
  } catch (_) {
    // A lookup that fails must not block editing — fall back to the per-file check, which is what this
    // always did. Not cached, so the next attempt retries.
    return null;
  }
  return focusIdsAcrossModCache;
}
/**
 * "" when `id` is free, otherwise the reason it is not. `currentFile` is the tree being edited, whose own
 * ids are excluded — those are already covered by the per-file check and by the caller's own exclusions.
 */
function focusIdTakenElsewhere(all, id, currentFile) {
  if (!all) return "";
  const here = String(currentFile || "").split(/[\\/]/).pop();
  const mineFile = all.mine.get(id);
  if (mineFile && mineFile !== here) {
    return `Focus ID "${id}" is already used by ${mineFile} in this mod. Focus IDs are global in Hearts of ` +
      `Iron IV — two focuses cannot share one, and they would also fight over the same localisation key ` +
      `(the key IS the id). Pick a different ID.`;
  }
  const inhFile = all.inherited.get(id);
  if (inhFile) {
    return `WARN:Focus ID "${id}" already exists in the base game or a mod you depend on (${inhFile}). Focus ` +
      `IDs are global in Hearts of Iron IV, so this will collide with that focus and its localisation. ` +
      `Saved anyway — rename it if that was not deliberate.`;
  }
  return "";
}

function isValidFocusId(id) {
  return /^[A-Za-z0-9_\.:-]+$/.test(id || "");
}

function syncFocusEditRow() {
  const selected = getSelectedFocusSingle();
  if (!focusIdInputEl || !applyFocusIdBtn || !deleteFocusBtn) return;
  if (!selected) {
    focusIdInputEl.value = "";
    focusIdInputEl.disabled = true;
    focusIdInputEl.title =
      selectedIds.size > 1
        ? "Several focuses are selected. Click one focus alone (or Shift/Ctrl-click down to one) to rename its ID."
        : "Select exactly one focus on the canvas to edit its ID.";
    applyFocusIdBtn.disabled = true;
    applyFocusIdBtn.title =
      selectedIds.size > 1
        ? "Rename ID needs a single selected focus — click one focus or reduce the selection first."
        : "Select one focus on the canvas to enable ID editing.";
    deleteFocusBtn.disabled = selectedIds.size === 0;
    deleteFocusBtn.title =
      selectedIds.size === 0 ? "Select one or more focuses to delete." : "Delete all selected focuses (asks for confirmation).";
    return;
  }
  focusIdInputEl.disabled = false;
  focusIdInputEl.value = selected.id;
  focusIdInputEl.title = "Edit the focus ID, then Apply or press Enter.";
  applyFocusIdBtn.disabled = false;
  applyFocusIdBtn.title = "Apply the new ID to this focus (updates links and pending edits).";
  deleteFocusBtn.disabled = false;
  deleteFocusBtn.title =
    selectedIds.size > 1
      ? `Delete these ${selectedIds.size} selected focuses (asks for confirmation).`
      : "Delete this focus (asks for confirmation).";
}

function focusBlockTemplate(focus, lineBreak, effectLines = [], mutuallyExclusive = [], prerequisites = []) {
  const indent = "\t";
  const rewardIndent = "\t\t";
  const normalizedEffects = effectLines
    .join("\n")
    .replace(/\r\n/g, "\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  const mutexRefs = Array.from(new Set((mutuallyExclusive || []).filter(Boolean))).sort();
  const prereqRefs = Array.from(new Set((prerequisites || []).filter(Boolean))); // insertion order — the author's, not the alphabet's
  // search_filters = the in-game focus-search category. A focus with NONE doesn't appear under
  // any filter in the search dropdown, so new focuses need a sensible default. (Existing focuses
  // keep their own via the targeted rewrite path; this template is new-focus-only.)
  const searchFilter = (focus.searchFilter && String(focus.searchFilter).trim()) || "FOCUS_FILTER_POLITICAL";
  const body = [
    "focus = {",
    `${indent}id = ${focus.id}`,
    `${indent}icon = ${focus.iconKey || "GFX_goal_generic_construct_civ_factory"}`,
    `${indent}search_filters = { ${searchFilter} }`,
  ];
  // #prereq-and-blocks-collapsed-to-or — ONE BLOCK PER PREREQUISITE, i.e. AND.
  //
  // Sibling `prerequisite` blocks are ANDed; several entries in ONE block are ORed. A new focus put every
  // parent into a single block, so clicking "+ Add Prerequisite" twice produced "unlocks after EITHER" —
  // while the editor's own status line says "required first" for each link. There was no gesture that could
  // express "requires both" at all. Each parent now gets its own block, which is both what the wording
  // promises and what vanilla writes for a chain of requirements.
  //
  // Grouping several ids into one block (OR) is what `prerequisiteGroups` carries for content read off disk;
  // a brand-new focus has no groups yet, so AND is the only honest default here.
  for (const id of prereqRefs) {
    body.push(`${indent}prerequisite = {`, `${indent}\tfocus = ${id}`, `${indent}}`);
  }
  if (mutexRefs.length > 0) {
    body.push(
      `${indent}mutually_exclusive = {`,
      ...mutexRefs.map((id) => `${indent}\tfocus = ${id}`),
      `${indent}}`,
    );
  }
  // `focus.cost || 10` would emit 10 for a real cost of 0 (0 is falsy) — an instant focus is legal HOI4
  // and vanilla/MD/RoN all ship them, so preserve an explicit 0 and default only when cost is absent.
  const _emitCost = (focus.cost === undefined || focus.cost === null || focus.cost === "" || !Number.isFinite(Number(focus.cost))) ? 10 : Number(focus.cost);
  body.push(
    `${indent}x = ${focus.x}`,
    `${indent}y = ${focus.y}`,
    `${indent}cost = ${_emitCost}`,
  );
  // #available-if-capitulated-field — WRITTEN ONLY WHEN ASKED FOR, like every other optional flag here.
  //
  // This used to be emitted unconditionally as `yes`, so every focus Nova created could be taken while the
  // country was capitulated — HOI4's own default is no, and real content agrees: Millennium Dawn omits the
  // key in 21,994 of 22,015 focuses and vanilla writes `no` 4,128 times against `yes` 1,689. There was no
  // control for it anywhere, so the modder could neither see nor change what was being written for them.
  // It is a sidebar field now, and behaves like cancel_if_invalid below: absent unless chosen.
  if (focus.availableIfCapitulated) {
    body.push(`${indent}available_if_capitulated = ${focus.availableIfCapitulated}`);
  }
  // Emit the Advanced trigger/condition blocks the user filled in (available, allow_branch,
  // ai_will_do, bypass) so a brand-NEW focus keeps them on its FIRST save — existing focuses
  // get these via rewriteFocusBlockConditions, but new focuses only go through this template.
  const emitTriggerSection = (name, raw) => {
    const lines = String(raw || "").split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    if (lines.length === 0) return;
    body.push(`${indent}${name} = {`, ...lines.map((l) => `${indent}\t${l}`), `${indent}}`);
  };
  emitTriggerSection("available", focus.available);
  emitTriggerSection("allow_branch", focus.allowBranch);
  emitTriggerSection("ai_will_do", focus.aiWillDo);
  emitTriggerSection("bypass", focus.bypass);
  if (focus.cancelIfInvalid) body.push(`${indent}cancel_if_invalid = ${focus.cancelIfInvalid}`);
  if (focus.continueIfInvalid) body.push(`${indent}continue_if_invalid = ${focus.continueIfInvalid}`);
  if (focus.willLeadToWarWith) body.push(`${indent}will_lead_to_war_with = ${focus.willLeadToWarWith}`);
  emitTriggerSection("select_effect", focus.selectEffect);
  if (normalizedEffects.length > 0) {
    body.push(
      `${indent}completion_reward = {`,
      `${rewardIndent}${FOCUS_EFFECTS_BEGIN_MARK}`,
      ...normalizedEffects.map((line) => `${rewardIndent}${line}`),
      `${rewardIndent}${FOCUS_EFFECTS_END_MARK}`,
      `${indent}}`,
    );
  } else {
    body.push(`${indent}completion_reward = { }`);
  }
  body.push("}");
  return body.join(lineBreak);
}

// #focus-rename-leaves-dangling-refs — WHERE ELSE A FOCUS ID IS WRITTEN DOWN.
//
// Renaming a focus used to rewrite only the places the TREE STRUCTURE points at it — prerequisite,
// mutually_exclusive, relative_position_id. But a focus id is also a value that triggers and effects take,
// and those live in the same file: 3,269 `has_completed_focus` in vanilla's trees and 2,385 in Millennium
// Dawn, of which 2,613 and 2,231 name a focus defined IN THE SAME FILE. A rename left every one of them
// pointing at an id that no longer exists, and `has_completed_focus = <gone>` is a condition that can never
// become true — so the sibling focus it gated stayed locked, silently and forever.
//
// Both lists are derived from data/hoi4-spec.json (the CWTools definitions) rather than typed from memory;
// test-focus-rename-updates-references.js re-derives the candidates from that file and fails if a new
// focus-related effect or trigger appears that is in neither list nor the documented exclusions.
//
// ⚠️ RENAME ONLY. A DELETE is not the same question — dropping `has_completed_focus = X` out of an
// `available` block does not remove a reference, it LOOSENS a gate, and choosing that silently would be a
// worse bug than the one being fixed. Deletes keep going through the existing dangling-reference warning.
const FOCUS_ID_SCALAR_KEYWORDS = [
  "has_completed_focus",        // trigger — 5,654 uses across the two corpora, the reason this exists
  "complete_national_focus",    // effect
  "unlock_national_focus",      // effect
  "activate_shine_on_focus",    // effect
  "deactivate_shine_on_focus",  // effect
  "has_shine_effect_on_focus",  // trigger
];
// These take a one-level block whose `focus = <id>` is the reference: `focus_progress = { focus = x
// progress = 0.5 }`. [^{}] keeps the match inside that single level, so no brace walking is needed.
const FOCUS_ID_BLOCK_KEYWORDS = [
  "focus_progress",               // trigger — 25 in vanilla
  "reduce_focus_completion_cost", // effect — 26 in vanilla
  "uncomplete_national_focus",    // effect
];
function cleanupReferencesInBlock(blockText, deletedIds, renameMap) {
  let out = blockText;
  const sectionNames = ["prerequisite", "prerequisites", "mutually_exclusive"];
  sectionNames.forEach((sectionName) => {
    const sectionRegex = new RegExp(`(^|\\n)\\s*${sectionName}\\s*=\\s*\\{`, "g");
    let match;
    while ((match = sectionRegex.exec(out)) !== null) {
      const openIdx = out.indexOf("{", match.index);
      const closeIdx = findMatchingBrace(out, openIdx);
      if (openIdx === -1 || closeIdx === -1) break;
      let sectionText = out.slice(match.index, closeIdx + 1);
      deletedIds.forEach((id) => {
        const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const removeLineRe = new RegExp(`(^|\\n)([ \\t]*)focus\\s*=\\s*${escaped}(?=\\s*(\\n|\\r|\\}))`, "g");
        sectionText = sectionText.replace(removeLineRe, "");
        // …and the INLINE form, which is how nearly all real content writes it. Measured across the
        // shipping trees: 15,534 of vanilla's 16,505 prerequisite/mutually_exclusive references (94%)
        // and 22,473 of Millennium Dawn's 32,823 (68%) sit on one line as `prerequisite = { focus = X }`.
        // The line-anchored pattern above cannot touch any of them, so deleting a focus left the
        // reference behind and every focus that named it could never be taken — silently, since a
        // prerequisite pointing at nothing is simply a condition that never comes true.
        //
        // The leading `(^|[^A-Za-z0-9_])` is load-bearing: without it this also matches the tail of
        // `has_completed_focus = X`, which is a different key with a different meaning.
        const removeInlineRe = new RegExp(`(^|[^A-Za-z0-9_])focus\\s*=\\s*${escaped}\\b[ \\t]*`, "g");
        sectionText = sectionText.replace(removeInlineRe, (m, lead) => lead);
      });
      renameMap.forEach((nextId, oldId) => {
        const escaped = oldId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const renameRe = new RegExp(`(focus\\s*=\\s*)${escaped}(?=\\s*(\\n|\\r|\\}))`, "g");
        sectionText = sectionText.replace(renameRe, `$1${nextId}`);
      });
      out = `${out.slice(0, match.index)}${sectionText}${out.slice(closeIdx + 1)}`;
      sectionRegex.lastIndex = match.index + sectionText.length;
    }
  });
  deletedIds.forEach((id) => {
    const escaped = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const removeRelativeRe = new RegExp(`(^|\\n)([ \\t]*)relative_position_id\\s*=\\s*${escaped}(?=\\s*(\\n|\\r|\\}))`, "g");
    out = out.replace(removeRelativeRe, "");
  });
  renameMap.forEach((nextId, oldId) => {
    const escaped = oldId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const renameRelativeRe = new RegExp(`(relative_position_id\\s*=\\s*)${escaped}(?=\\s*(\\n|\\r|\\}))`, "g");
    out = out.replace(renameRelativeRe, `$1${nextId}`);
    // …and everywhere the id is USED rather than pointed at. A function replacement, not `$1${nextId}`:
    // a `$` in the replacement STRING is a substitution token, and ids are user input.
    FOCUS_ID_SCALAR_KEYWORDS.forEach((kw) => {
      const scalarRe = new RegExp(`(\\b${kw}\\s*=\\s*)${escaped}\\b`, "g");
      out = out.replace(scalarRe, (m, lead) => `${lead}${nextId}`);
    });
    FOCUS_ID_BLOCK_KEYWORDS.forEach((kw) => {
      const blockRe = new RegExp(`(\\b${kw}\\s*=\\s*\\{[^{}]*?\\bfocus\\s*=\\s*)${escaped}\\b`, "g");
      out = out.replace(blockRe, (m, lead) => `${lead}${nextId}`);
    });
  });
  return out;
}

function refreshParsedDerived() {
  // Hot path profile note:
  // this runs after most focus mutations and can feed expensive canvas redraws + validation.
  if (!parsed) return;
  const focuses = parsed.focuses;
  const focusMap = new Map(focuses.map((f) => [f.id, f]));
  focuses.forEach((focus) => {
    if (!Array.isArray(focus.prerequisites)) focus.prerequisites = [];
    focus.prerequisites = Array.from(new Set(focus.prerequisites.filter((id) => id && id !== focus.id)));
    if (!Array.isArray(focus.mutuallyExclusive)) focus.mutuallyExclusive = [];
    focus.mutuallyExclusive = Array.from(new Set(focus.mutuallyExclusive.filter((id) => id && id !== focus.id)));
    focus.mutuallyExclusive.forEach((id) => {
      const other = focusMap.get(id);
      if (!other) return;
      if (!Array.isArray(other.mutuallyExclusive)) other.mutuallyExclusive = [];
      if (!other.mutuallyExclusive.includes(focus.id)) other.mutuallyExclusive.push(focus.id);
    });
  });
  const idSet = new Set(focuses.map((f) => f.id));
  const edges = [];
  const mutexPairs = [];
  let unresolvedEdges = 0;
  const diagnostics = [];
  focuses.forEach((focus) => {
    (focus.prerequisites || []).forEach((parentId) => {
      if (idSet.has(parentId)) {
        edges.push({ from: parentId, to: focus.id, type: "prerequisite" });
      } else {
        unresolvedEdges += 1;
      }
    });
    (focus.mutuallyExclusive || []).forEach((otherId) => {
      if (!idSet.has(otherId)) return;
      const a = focus.id < otherId ? focus.id : otherId;
      const b = focus.id < otherId ? otherId : focus.id;
      const pairKey = `${a}::${b}`;
      if (!mutexPairs.some((p) => p.key === pairKey)) {
        mutexPairs.push({ key: pairKey, a, b });
      }
    });
  });
  mutexPairs.forEach((pair) => {
    edges.push({ from: pair.a, to: pair.b, type: "mutually_exclusive", pairKey: pair.key });
  });
  const next = {
    ...parsed,
    focuses,
    edges,
    mutexPairs,
    diagnostics,
    stats: {
      ...parsed.stats,
      parsedEdges: edges.length,
      unresolvedEdges,
    },
  };
  parsed = resolveLayout(next);
  applyLocalization(parsed);
  focusByIdCache = new Map((parsed.focuses || []).map((f) => [f.id, f]));
  focusMutationVersion += 1;
  if (nationalSpiritEditorState && nationalSpiritEditorState.usageCache) {
    nationalSpiritEditorState.usageCache.clear();
    nationalSpiritEditorState.usageCacheVersion = focusMutationVersion;
  }
  try {
    const tag = getEffectiveCountryTag();
    if (tag && tag !== "ZZZ") {
      localStorage.setItem("activeCountryTag", tag);
      const flagEl = document.getElementById("simCountryFlag");
      if (flagEl) flagEl.textContent = tag;
    }
  } catch (_e) {}
}

function getEffectCommandKey(line) {
  const trimmed = String(line || "").trim();
  const match = trimmed.match(/^([A-Za-z0-9_\.:-]+)\s*[=<>]/);
  if (!match) return "";
  
  const key = match[1];
  // If it's a numeric scope (State ID) or ROOT, look inside for the actual command
  if ((/^\d+$/.test(key) || key.toUpperCase() === "ROOT") && trimmed.includes("{")) {
    const innerMatch = trimmed.match(/\{[\s\n]*([A-Za-z0-9_]+)\s*[=<>]/);
    if (innerMatch) return innerMatch[1];
  }
  
  return key;
}

function effectLineBraceBalanceDelta(s) {
  const str = String(s || "");
  let inString = false;
  let quote = "";
  let delta = 0;
  for (let i = 0; i < str.length; i += 1) {
    const c = str[i];
    if (!inString && c === "#") {
      // For multiline strings, a '#' only comments out the rest of the CURRENT line.
      const nextNewline = str.indexOf("\n", i);
      if (nextNewline === -1) break; // End of string
      i = nextNewline; // Skip to newline
      continue;
    }
    if (inString) {
      if (c === "\\") {
        i += 1;
        continue;
      }
      if (c === quote) {
        inString = false;
        quote = "";
      }
      continue;
    }
    if (c === '"' || c === "'") {
      inString = true;
      quote = c;
      continue;
    }
    if (c === "{") delta += 1;
    if (c === "}") delta -= 1;
  }
  return delta;
}

