function extractTimedIdeaIdFromBlockLines(lines) {
  const arr = Array.isArray(lines) ? lines : [];
  for (let i = 0; i < arr.length; i += 1) {
    const im = String(arr[i] || "").trim().match(/^idea\s*=\s*([A-Za-z0-9_]+)/);
    if (im) return im[1];
  }
  const joined = arr.map((line) => String(line || "").trim()).join(" ");
  const inline = joined.match(/\bidea\s*=\s*([A-Za-z0-9_]+)/);
  return inline ? inline[1] : "";
}

const EFFECT_BLOCK_KEYS = new Set([
  "add_named_threat",
  "add_autonomy_ratio",
  "add_tech_bonus",
  "add_doctrine_cost_reduction",
  "add_building_construction",
  "add_extra_state_shared_building_slots",
  "add_offsite_building",
  "add_timed_idea",
  "create_wargoal",
  "annex_country",
  "add_equipment_to_stockpile",
  // set_technology = { <tech> = 1 } is a MULTI-LINE block (the { and } land on separate lines). Without
  // listing it here, queueEffectLines didn't recognise it as a block, so it fell through to single-line
  // handling that kept only the first line ("set_technology = {") — producing unbalanced braces that
  // made the focus impossible to save ("effect rewrite blocked: Unbalanced braces"). It is a single
  // instance per focus, so it's handled like the other single-instance block effects above.
  "set_technology",
  "set_politics",
  "add_popularity",
  "declare_war_on",
  "add_resource",
  "state_scope",
  "every_state",
  "any_state",
  "random_state",
  "every_owned_state",
  "any_owned_state",
  "random_owned_state",
  "every_neighbor_state",
  "random_neighbor_state",
  "every_controlled_state",
  "any_controlled_state",
  "random_controlled_state",
  "every_core_state",
  "any_core_state",
  "random_core_state",
  "every_other_country",
  "any_other_country",
  "random_other_country",
  "every_neighbor_country",
  "any_neighbor_country",
  "random_neighbor_country",
  "every_country",
  "any_country",
  "random_country",
  "every_ally",
  "any_ally",
  "random_ally",
  "limit",
  "IF",
  "ELSE",
  "ELSE_IF",
  "AND",
  "OR",
  "NOT",
  "hidden_effect",
  "custom_effect_tooltip",
  "effect_tooltip"
]);

function detectBlockEffectKey(line) {
  const t = String(line || "").trim();
  const stateScopedMatch = t.match(/^(\d+)\s*=\s*\{(?:\s*#\s*focus_editor_key\s*=\s*([A-Za-z0-9_\.:-]+))?/);
  if (stateScopedMatch) {
    const tagged = String(stateScopedMatch[2] || "").trim();
    if (tagged && EFFECT_BLOCK_KEYS.has(tagged)) return tagged;
    return "state_scope";
  }
  const m = t.match(/^([A-Za-z0-9_\.:-]+)\s*=\s*\{/);
  if (m) return String(m[1] || "");
  if (/^(IF|ELSE|ELSE_IF|limit|OR|AND|NOT)\s*=\s*\{/i.test(t)) {
    const lm = t.match(/^([A-Za-z0-9_]+)/i);
    return lm ? lm[1].toLowerCase() : "logic_block";
  }
  return "";
}

// `limit` is a TRIGGER, not an effect, and counting it as one is what split scoped blocks apart.
//
// A scoped block such as `every_state = { limit = { … } add_building_construction = { … } }` was seen as TWO
// manageable effect units, which tipped the adoption heuristic into re-emitting each inner statement as its
// own `every_state = { … }`. The limit then sat alone in a block that does nothing, and the effect block lost
// its filter entirely — so `add_building_construction` applied to EVERY state instead of the six the author
// named. Vanilla's MEX_focus_rural_infrastructure is exactly this shape, and it happens on the first save of
// any tree Nova has not stamped, whether or not the user touched that focus.
//
// Same reasoning for the other trigger-shaped keys that legally sit beside effects inside a scope.
// #focus-scoped-limit-split
const TRIGGER_ONLY_BLOCK_KEYS = new Set(["limit", "trigger", "if", "else", "else_if"]);

function isRecognizedEffectUnit(unit) {
  if (!unit) return false;
  if (unit.kind === "block" && TRIGGER_ONLY_BLOCK_KEYS.has(String(unit.key || "").toLowerCase())) return false;
  if (unit.kind === "block") return true;
  if (unit.kind === "line") {
    const t = String(unit.lines[0] || "").trim();
    if (EFFECT_PRESETS[unit.key]) return true;
    for (const pk in EFFECT_PRESETS) {
      if (EFFECT_PRESETS[pk].command === unit.key) return true;
    }
    if (/^(army|navy|air)_experience\s*=/.test(t)) return true;
    if (IDEA_LIKE_EFFECT_RE.test(t)) return true;
    // Support scripted effects: name = yes/no
    if (/^[A-Za-z0-9_]+\s*=\s*(yes|no)\b/i.test(t)) return true;
    return false;
  }
  return false;
}

// #focus-effect-adopted-twice
//
// EVERY CONDITIONAL IN EVERY FOCUS WAS WRITTEN TO THE FILE TWICE, on every save, whether or not the user
// touched that focus. A focus granting 1000 manpower granted 2000; a `start_civil_war` fired twice. Measured
// over the shipping corpus — 184 trees, vanilla + Millennium Dawn, one focus marked moved — the save added
// 23,887 `if`/`else`/`else_if`/`limit`/`trigger` blocks and 7.0 MB of script. Vanilla's germany.txt alone
// went 846,720 -> 1,114,543 bytes.
//
// The mechanism is two halves of one rewrite that disagree about what "adopted" means. When a
// completion_reward carries no `# focus_editor:` markers, ADOPTION copies every top-level unit of the body
// verbatim into a fresh managed segment. The MIGRATION step then deletes from the body the units it thinks
// adoption took — and it asked `isRecognizedEffectUnit`, which answers a different question ("can the Reward
// Lab render this?"). It says NO for `limit`/`trigger`/`if`/`else`/`else_if` (they are triggers, not
// effects — #focus-scoped-limit-split), and NO for anything else it has no preset for, such as
// `custom_effect_tooltip` or a bare `## comment ##`. Those are exactly the units adoption had just copied,
// so they stayed in the body AND appeared in the segment.
//
// The predicate below asks the question that actually matters: DID THIS BODY UNIT END UP IN THE SEGMENT? It
// has to, because the segment is not simply the adopted payload — `reorderManagedSegmentLines`,
// `sanitizeNationalIdeaManagedLinesForSave` and `processManagedSegmentCosmeticHiddenEffect` run over it
// afterwards and each may drop or rewrite units. Vanilla's AFG_return_of_the_emir is the case that pins
// this: it holds two `remove_ideas` whose matching `add_ideas` live in other focuses, and the national-idea
// sanitiser deletes an unmatched `remove_ideas` from the segment. Adoption took them, the sanitiser threw
// them away, and a body prune that trusted adoption left them in neither place.
//
// TWO PLACEMENTS THAT LOOK RIGHT AND ARE NOT — both were tried and measured before this one:
//   * Prune the body against the ADOPTED payload. Kills the duplication and loses real content: afghanistan
//     drops `set_cosmetic_tag = AFG_khorasan` and three `remove_ideas`, japan drops `popup = no` and
//     `suicide_craft = 1`, germany drops `days = 2` / `hours = 6` — every unit the three passes discard.
//   * Prune against the final segment, but by KEY or by "does this text appear anywhere". Afghanistan still
//     loses the same four. `custom_effect_tooltip = generic_skip_one_line_tt` occurs four times in one
//     reward and `remove_ideas` twice; a set-membership test cannot tell four survivors from three, so it
//     prunes all four bodies against three segment copies. Matching must be MULTIPLICITY-AWARE — each body
//     unit consumes one segment occurrence, or it is not a match.
//
// Hence: compare whole RUNS of lines, consume what you match, and fall back to the old predicate only for a
// unit the segment and the payload both fail to mention (which is how a Reward Lab deletion still deletes).
/**
 * Compare key for one effect unit: trimmed, legacy-renamed, blank lines dropped.
 *
 * `focusId` puts the unit through `sanitizeLegacyManagedEffectLines` first, which is what the adopted
 * payload was built with — COMPARE LIKE WITH LIKE. That sanitiser rewrites as well as drops, and the
 * rewrites are invisible until you diff two corpora: vanilla's BEL_cockerill_shipyards writes
 * `category = naval_doctrine # optional` and the sanitiser re-emits it as `category = naval_doctrine`,
 * comment stripped. Comparing the raw body line against the sanitised payload line said "not the same
 * statement", so the whole `ELSE = { … }` around it was written to the file a second time. 142 of the 248
 * residual duplicates were this one mismatch.
 */
function effectUnitCompareLines(lines, focusId) {
  const flat = (Array.isArray(lines) ? lines : [])
    .flatMap((ln) => String(ln == null ? "" : ln).split("\n"))
    .map((ln) => String(ln).trim())
    .filter((ln) => ln.length > 0);
  const sanitized = focusId === undefined ? flat : sanitizeLegacyManagedEffectLines(flat, focusId);
  return sanitized
    .map((ln) => normalizeLegacyEffectCommand(String(ln).trim()).trim())
    .filter((ln) => ln.length > 0);
}

/**
 * Find an unconsumed contiguous occurrence of `needle` inside `haystack` and consume it.
 * `consumed` is a parallel boolean array, so N copies of a statement match N times and no more.
 */
function consumeEffectLineRun(haystack, consumed, needle) {
  if (!needle || needle.length === 0) return false;
  for (let i = 0; i + needle.length <= haystack.length; i += 1) {
    let ok = true;
    for (let k = 0; k < needle.length; k += 1) {
      if (consumed[i + k] || haystack[i + k] !== needle[k]) { ok = false; break; }
    }
    if (!ok) continue;
    for (let k = 0; k < needle.length; k += 1) consumed[i + k] = true;
    return true;
  }
  return false;
}

/**
 * Decide, unit by unit, what survives in the body once the managed segment has been built.
 * `finalSegmentLines` is the segment AFTER the reorder/idea/cosmetic passes; `adoptedLines` is what
 * adoption handed those passes. Returns the new body lines.
 *
 * Longest units are matched first on purpose. A one-line `custom_effect_tooltip = …` sitting beside an
 * `if = { … custom_effect_tooltip = … }` would otherwise consume the line nested inside the block's run,
 * and the block would then fail to match and be written twice.
 */
function pruneAdoptedUnitsFromFocusBody(bodyLines, finalSegmentLines, adoptedLines, focusId) {
  // All three sides go through the SAME normaliser. The payload reaches this function already sanitised
  // when the save carries pending Reward Lab edits and NOT sanitised line-by-line when it is only healing
  // an adopted reward (that path hands `sanitizeLegacyManagedEffectLines` whole multi-line unit strings, so
  // its per-line rules never fire on the inner lines). Normalising only the body side made the two paths
  // disagree — the seeded path measured clean and the heal path still duplicated 88 blocks over 22 trees.
  const units = splitIncomingEffectPayload(bodyLines);
  const segment = effectUnitCompareLines(finalSegmentLines, focusId);
  const segmentConsumed = new Array(segment.length).fill(false);
  const adopted = effectUnitCompareLines(adoptedLines, focusId);
  const adoptedConsumed = new Array(adopted.length).fill(false);

  const order = units.map((u, i) => i).sort((a, b) => {
    const d = (units[b].lines || []).length - (units[a].lines || []).length;
    return d !== 0 ? d : a - b;
  });
  const keep = new Array(units.length).fill(false);
  order.forEach((i) => {
    const cmp = effectUnitCompareLines(units[i].lines, focusId);
    // The segment carries it — dropping the body copy is what stops the duplicate.
    if (consumeEffectLineRun(segment, segmentConsumed, cmp)) return;
    // Adoption took it but a segment pass discarded it — keeping the body copy is what stops the loss.
    if (consumeEffectLineRun(adopted, adoptedConsumed, cmp)) { keep[i] = true; return; }
    // Neither mentions it: a Reward Lab removal, or something adoption never saw. Unchanged behaviour.
    keep[i] = !isRecognizedEffectUnit(units[i]);
  });

  const out = [];
  units.forEach((u, i) => { if (keep[i]) out.push(...u.lines); });
  return out;
}

function removeAddTechBonusBlocksFromTrimmedLines(lines) {
  const arr = [...lines];
  for (let i = arr.length - 1; i >= 0; i -= 1) {
    const t = String(arr[i] || "").trim();
    if (!/^add_tech_bonus\s*=\s*\{/.test(t)) continue;
    let bal = effectLineBraceBalanceDelta(arr[i]);
    let j = i;
    while (bal > 0 && j + 1 < arr.length) {
      j += 1;
      bal += effectLineBraceBalanceDelta(String(arr[j] || ""));
    }
    arr.splice(i, j - i + 1);
  }
  return arr;
}

function removeEffectBlocksByKeyFromTrimmedLines(lines, commandKey) {
  const arr = [...lines];
  for (let i = arr.length - 1; i >= 0; i -= 1) {
    const blockKey = detectBlockEffectKey(arr[i]);
    if (!blockKey || blockKey !== commandKey) continue;
    let bal = effectLineBraceBalanceDelta(arr[i]);
    let j = i;
    while (bal > 0 && j + 1 < arr.length) {
      j += 1;
      bal += effectLineBraceBalanceDelta(String(arr[j] || ""));
    }
    arr.splice(i, j - i + 1);
  }
  return arr;
}

/** Raw completion_reward body lines (may include indentation). */
function removeAddTechBonusBlocksFromRawBodyLines(bodyLines) {
  for (let i = bodyLines.length - 1; i >= 0; i -= 1) {
    const t = String(bodyLines[i] || "").trim();
    if (!/^add_tech_bonus\s*=\s*\{/.test(t)) continue;
    let bal = effectLineBraceBalanceDelta(bodyLines[i]);
    let j = i;
    while (bal > 0 && j + 1 < bodyLines.length) {
      j += 1;
      bal += effectLineBraceBalanceDelta(String(bodyLines[j] || ""));
    }
    bodyLines.splice(i, j - i + 1);
  }
}

function removeAddTechBonusBlocksFromIndentedSegmentLines(segmentLines) {
  const copy = [...segmentLines];
  removeAddTechBonusBlocksFromRawBodyLines(copy);
  return copy;
}

function collectTopManagedEffectKeys(lines) {
  const keys = new Set();
  const arr = lines || [];
  let i = 0;
  while (i < arr.length) {
    const t = String(arr[i] || "").trim();
    if (!t) {
      i += 1;
      continue;
    }
    const blockKey = detectBlockEffectKey(t);
    if (blockKey || isHiddenEffectBlockStartLine(t)) {
      const start = i;
      let bal = effectLineBraceBalanceDelta(String(arr[i] || ""));
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        bal += effectLineBraceBalanceDelta(String(arr[j] || ""));
        j += 1;
      }
      if (bal !== 0) {
        const k0 = getEffectCommandKey(String(arr[start] || "").trim());
        if (k0) keys.add(k0);
        i = start + 1;
        continue;
      }
      if (blockKey) keys.add(blockKey);
      if (!blockKey && isHiddenEffectBlockStartLine(String(arr[start] || ""))) {
        keys.add("hidden_effect");
        const inner = arr
          .slice(start + 1, j - 1)
          .map((ln) => String(ln || "").trim())
          .filter((ln) => ln.length > 0 && !ln.startsWith("#"));
        if (inner.some((ln) => /^set_cosmetic_tag\s*=/.test(ln))) {
          keys.add("set_cosmetic_tag");
        }
      }
      i = j;
      continue;
    }
    const k = getEffectCommandKey(t);
    if (k) keys.add(k);
    i += 1;
  }
  return keys;
}

/** Split pending effect lines into single-line units and one multi-line add_tech_bonus block unit. */
function splitIncomingEffectPayload(linesRaw) {
  const units = [];
  const arr = Array.isArray(linesRaw) ? linesRaw.map((l) => String(l || "")) : [];
  let i = 0;
  while (i < arr.length) {
    const raw = arr[i];
    const t = raw.trim();
    if (!t) {
      i += 1;
      continue;
    }
    const blockKey = detectBlockEffectKey(t);
    if (blockKey) {
      const blockLines = [raw];
      let bal = effectLineBraceBalanceDelta(raw);
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        blockLines.push(arr[j]);
        bal += effectLineBraceBalanceDelta(arr[j]);
        j += 1;
      }
      if (bal !== 0) {
        units.push({ kind: "line", key: getEffectCommandKey(t) || blockKey, lines: [raw] });
        i += 1;
        continue;
      }
      units.push({ kind: "block", key: blockKey, lines: blockLines });
      i = j;
      continue;
    }
    if (isHiddenEffectBlockStartLine(t)) {
      const blockLines = [raw];
      let bal = effectLineBraceBalanceDelta(raw);
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        blockLines.push(arr[j]);
        bal += effectLineBraceBalanceDelta(arr[j]);
        j += 1;
      }
      if (bal !== 0) {
        units.push({ kind: "line", key: getEffectCommandKey(t) || "hidden_effect", lines: [raw] });
        i += 1;
        continue;
      }
      units.push({ kind: "block", key: "hidden_effect", lines: blockLines });
      i = j;
      continue;
    }
    units.push({ kind: "line", key: getEffectCommandKey(t), lines: [raw] });
    i += 1;
  }
  return units;
}

function parseBuildingBlockSignatureFromUnit(unit) {
  if (!unit || unit.kind !== "block" || !unit.key) return null;

  const stateScopes = [
    "random_core_state",
    "random_owned_state",
    "every_owned_state",
    "any_owned_state",
    "capital_scope",
    "every_state",
    "any_state",
    "all_state",
    "random_state",
  ];
  const isStateScope = /^\d+$/.test(unit.key) || stateScopes.includes(unit.key);

  let command = unit.key;
  if (isStateScope) {
    const text = (unit.lines || []).join(" ");
    if (text.includes("add_building_construction")) command = "add_building_construction";
    else if (text.includes("add_offsite_building")) command = "add_offsite_building";
    else if (text.includes("add_extra_state_shared_building_slots")) command = "add_extra_state_shared_building_slots";
    else if (text.includes("add_resource")) command = "add_resource";
    else return null;
  } else if (
    command !== "add_building_construction" &&
    command !== "add_offsite_building" &&
    command !== "add_extra_state_shared_building_slots" &&
    command !== "add_resource"
  ) {
    return null;
  }

  const joined = (unit.lines || []).map((line) => String(line || "").trim()).join(" ");
  const tm = joined.match(/\btype\s*=\s*([A-Za-z0-9_]+)/);
  const am = joined.match(/\bamount\s*=\s*([^\s#\}]+)/);
  const lm = joined.match(/\blevel\s*=\s*([^\s#\}]+)/);
  const sm = joined.match(/\bstate\s*=\s*([^\s#\}]+)/);
  const firstLine = String((unit.lines && unit.lines[0]) || "").trim();
  const stateScopeMatch = firstLine.match(/^([A-Za-z0-9_]+)\s*=\s*\{/);
  const stateScope = stateScopeMatch ? stateScopeMatch[1] : "";
  const slotsMatch = joined.match(/\badd_extra_state_shared_building_slots\s*=\s*([^\s#\}]+)/);
  const levelToken = lm
    ? String(lm[1])
    : am
      ? String(am[1])
      : slotsMatch
        ? String(slotsMatch[1])
        : "1";
  const stateToken = sm ? String(sm[1]) : (stateScope && stateScope !== command ? stateScope : "");
  return {
    command,
    type: command === "add_extra_state_shared_building_slots" ? "__state_slots__" : (tm ? tm[1] : ""),
    level: /^\d+$/.test(levelToken) ? Number.parseInt(levelToken, 10) : 1,
    stateId: stateToken,
    levelToken,
    stateToken,
  };
}

function sameBuildingSignature(a, b) {
  if (!a || !b) return false;
  const levelA = String(a.levelToken || a.level || "1");
  const levelB = String(b.levelToken || b.level || "1");
  const stateA = String(a.stateToken || a.stateId || "");
  const stateB = String(b.stateToken || b.stateId || "");
  return (
    String(a.command || "") === String(b.command || "") &&
    String(a.type || "") === String(b.type || "") &&
    levelA === levelB &&
    stateA === stateB
  );
}

function parseTechBonusSignatureFromUnit(unit) {
  if (!unit || unit.kind !== "block" || unit.key !== "add_tech_bonus") return null;
  const joined = (unit.lines || []).map((line) => String(line || "").trim()).join(" ");
  const nm = joined.match(/\bname\s*=\s*([A-Za-z0-9_]+)/);
  if (!nm) return null;
  return { kind: "tech_bonus", nameToken: nm[1] };
}

function parseTechBonusCategoryFromUnit(unit) {
  if (!unit || unit.kind !== "block" || unit.key !== "add_tech_bonus") return "";
  const joined = (unit.lines || []).map((line) => String(line || "").trim()).join(" ");
  const m = joined.match(/\bcategory\s*=\s*([A-Za-z0-9_]+)/);
  return m ? String(m[1] || "").trim() : "";
}

function humanizeResearchBonusCategoryDisplay(categoryRaw) {
  let s = String(categoryRaw || "").trim();
  if (!s) return "";
  if (/^CAT_/i.test(s)) s = s.replace(/^CAT_/i, "");
  s = s.replace(/_/g, " ").trim().toLowerCase();
  return s;
}

function simplifyResearchBonusNameTokenForRemove(focusId, nameToken) {
  let t = String(nameToken || "").trim();
  if (!t) return "";
  const safeFocus = String(focusId || "").replace(/[^A-Za-z0-9_]/g, "_");
  const prefix = `${safeFocus}_`;
  if (t.startsWith(prefix)) t = t.slice(prefix.length);
  if (/^CAT_/i.test(t)) t = t.replace(/^CAT_/i, "");
  t = t.replace(/_bonus$/i, "");
  t = t.replace(/_/g, " ").trim().toLowerCase();
  return t || "bonus";
}

function sameTechBonusSignature(a, b) {
  if (!a || !b) return false;
  const ka = String(a.kind || "tech_bonus");
  const kb = String(b.kind || "tech_bonus");
  if (ka !== "tech_bonus" || kb !== "tech_bonus") return false;
  return String(a.nameToken || "") === String(b.nameToken || "");
}

function parseDoctrineCostSignatureFromUnit(unit) {
  if (!unit || unit.kind !== "block" || unit.key !== "add_doctrine_cost_reduction") return null;
  const joined = (unit.lines || []).map((line) => String(line || "").trim()).join(" ");
  const nm = joined.match(/\bname\s*=\s*([A-Za-z0-9_]+)/);
  if (!nm) return null;
  return { kind: "doctrine_cost", nameToken: nm[1] };
}

function sameDoctrineCostRemovalSignature(a, b) {
  if (!a || !b) return false;
  if (String(a.kind || "") !== "doctrine_cost" || String(b.kind || "") !== "doctrine_cost") return false;
  return String(a.nameToken || "") === String(b.nameToken || "");
}

function removeDoctrineCostBlocksBySignatures(linesRaw, signatures) {
  const list = Array.isArray(signatures) ? signatures : [];
  if (!list.length) return Array.isArray(linesRaw) ? [...linesRaw] : [];
  const units = splitIncomingEffectPayload(linesRaw);
  const kept = [];
  const remaining = [...list];
  units.forEach((unit) => {
    const sig = parseDoctrineCostSignatureFromUnit(unit);
    if (!sig) {
      kept.push(...unit.lines);
      return;
    }
    const idx = remaining.findIndex((target) => sameDoctrineCostRemovalSignature(sig, target));
    if (idx === -1) {
      kept.push(...unit.lines);
      return;
    }
    remaining.splice(idx, 1);
  });
  return kept;
}

function removeTechBonusBlocksBySignatures(linesRaw, signatures) {
  const list = Array.isArray(signatures) ? signatures : [];
  if (!list.length) return Array.isArray(linesRaw) ? [...linesRaw] : [];
  const units = splitIncomingEffectPayload(linesRaw);
  const kept = [];
  const remaining = [...list];
  units.forEach((unit) => {
    const sig = parseTechBonusSignatureFromUnit(unit);
    if (!sig) {
      kept.push(...unit.lines);
      return;
    }
    const idx = remaining.findIndex((target) => sameTechBonusSignature(sig, target));
    if (idx === -1) {
      kept.push(...unit.lines);
      return;
    }
    remaining.splice(idx, 1);
  });
  return kept;
}

function partitionBlockRemovalSigs(sigs) {
  const buildings = [];
  const techBonuses = [];
  const doctrineCosts = [];
  const diplomacy = [];
  const resources = [];
  (Array.isArray(sigs) ? sigs : []).forEach((s) => {
    if (!s) return;
    if (s.kind === "tech_bonus" && s.nameToken) {
      techBonuses.push(s);
      return;
    }
    if (s.kind === "doctrine_cost" && s.nameToken) {
      doctrineCosts.push(s);
      return;
    }
    if (s.kind === "diplomacy") {
      diplomacy.push(s);
      return;
    }
    if (s.command === "add_resource") {
      resources.push(s);
      return;
    }
    buildings.push(s);
  });
  return { buildings, techBonuses, doctrineCosts, diplomacy, resources };
}

function formatResearchBonusRemoveLabel(friendlyName) {
  const name = String(friendlyName || "").trim() || "this bonus";
  const withSuffix = `Remove ${name} research bonus`;
  if (withSuffix.length > 52) {
    return `Remove ${name}`;
  }
  return withSuffix;
}

function formatDoctrineCostRemoveLabel(nameToken) {
  const name = String(nameToken || "").trim() || "doctrine";
  const withSuffix = `Remove ${name} doctrine reduction`;
  if (withSuffix.length > 52) {
    return `Remove ${name}`;
  }
  return withSuffix;
}

function removeBuildingBlocksBySignatures(linesRaw, signatures) {
  const list = Array.isArray(signatures) ? signatures : [];
  if (!list.length) return Array.isArray(linesRaw) ? [...linesRaw] : [];
  const units = splitIncomingEffectPayload(linesRaw);
  const kept = [];
  const remaining = [...list];
  units.forEach((unit) => {
    const sig = parseBuildingBlockSignatureFromUnit(unit);
    if (!sig) {
      kept.push(...unit.lines);
      return;
    }
    const idx = remaining.findIndex((target) => sameBuildingSignature(sig, target));
    if (idx === -1) {
      kept.push(...unit.lines);
      return;
    }
    remaining.splice(idx, 1);
  });
  return kept;
}

function inferCountryTagFromFocusPath(filePath) {
  const parts = (filePath || "").split(/[\\\/]/);
  const base = (parts[parts.length - 1] || "").toUpperCase();
  const match = base.match(/^([A-Z0-9]{3})(_|\s|$)/);
  return match ? match[1] : "";
}

function getCanonicalSignature(lines) {
  return lines
    .map((l) => {
      let t = l.trim().replace(/\s+/g, " ");
      t = t.replace(/\s*=\s*/g, " = ");
      t = t.replace(/\s*\{\s*/g, " { ");
      t = t.replace(/\s*\}\s*/g, " } ");
      return t.trim();
    })
    .join("|");
}

function removeDiplomacyBySignatures(linesRaw, signatures) {
  const list = Array.isArray(signatures) ? signatures : [];
  if (!list.length) return Array.isArray(linesRaw) ? [...linesRaw] : [];
  const units = splitIncomingEffectPayload(linesRaw);
  const kept = [];
  const remaining = [...list];
  units.forEach((unit) => {
    const sig = getCanonicalSignature(unit.lines);
    const idx = remaining.findIndex((target) => target.sig === sig);
    if (idx === -1) {
      kept.push(...unit.lines);
      return;
    }
    remaining.splice(idx, 1);
  });
  return kept;
}

function validateManagedEffectsSegmentLines(lines) {
  const arr = Array.isArray(lines) ? lines : [];
  let bal = 0;
  const safeBraceDelta = (rawLine) => {
    const s = String(rawLine || "");
    let inString = false;
    let quote = "";
    let delta = 0;
    for (let i = 0; i < s.length; i += 1) {
      const c = s[i];
      if (!inString && c === "#") {
        const nextNewline = s.indexOf("\n", i);
        if (nextNewline === -1) break;
        i = nextNewline;
        continue;
      }
      if (inString) {
        if (c === "\\") {
          i += 1;
          continue;
        }
        if (c === quote) {
          inString = false;
          quote = "";
        }
        continue;
      }
      if (c === '"' || c === "'") {
        inString = true;
        quote = c;
        continue;
      }
      if (c === "{") delta += 1;
      if (c === "}") delta -= 1;
    }
    return delta;
  };
  for (let i = 0; i < arr.length; i += 1) {
    const t = String(arr[i] || "").trim();
    if (!t) continue;
    // `idea =` / `days =` are valid only inside a timed-idea block.
    if (bal === 0 && /^(idea|days)\s*=/.test(t)) {
      return { ok: false, message: `Invalid top-level timed-idea field near "${t}".` };
    }
    const delta = safeBraceDelta(t);
    bal += delta;
    if (bal < 0) return { ok: false, message: "Unbalanced closing brace in managed effects segment." };
  }
  if (bal !== 0) return { ok: false, message: `Unbalanced braces (${bal > 0 ? "missing closing" : "extra closing"}) in managed effects segment.` };
  return { ok: true, message: "" };
}

function isHiddenEffectBlockStartLine(line) {
  return /^hidden_effect\s*=\s*\{/.test(String(line || "").trim());
}

function stripEmptyHiddenEffectBlocksFromSegment(segmentLines) {
  const lines = [...(segmentLines || [])];
  let i = 0;
  while (i < lines.length) {
    if (!isHiddenEffectBlockStartLine(lines[i])) {
      i += 1;
      continue;
    }
    let j = i;
    let bal = effectLineBraceBalanceDelta(lines[j]);
    j += 1;
    while (j < lines.length && bal > 0) {
      bal += effectLineBraceBalanceDelta(lines[j]);
      j += 1;
    }
    if (bal !== 0) {
      i += 1;
      continue;
    }
    // "EMPTY" means no statements BETWEEN THE BRACES — which is not the same as "no whole lines between
    // the opening line and the closing line". This used to take `lines.slice(i + 1, j - 1)`, so any
    // hidden_effect whose braces do not each sit on their own line read as empty and was deleted outright,
    // taking its contents with it:
    //     hidden_effect = { set_technology = { suicide_craft = 1 } }      one line   -> slice is empty
    //     hidden_effect = {
    //     add_ideas = intervention_neo_imperialism }                      two lines  -> slice is empty
    // Vanilla's JAP_strengthen_the_divine_wind loses `suicide_craft = 1` and `popup = no` to the first
    // shape (60-odd focuses across vanilla + Millennium Dawn), Millennium Dawn's BOS_Muslim_Nationalism
    // loses `add_ideas = intervention_neo_imperialism` to the second. Read the braces, not the line breaks.
    const openLine = String(lines[i] || "");
    const closeLine = String(lines[j - 1] || "");
    const innerRaw = (j - i === 1)
      ? [openLine.slice(openLine.indexOf("{") + 1, openLine.lastIndexOf("}"))]
      : [
        openLine.slice(openLine.indexOf("{") + 1),
        ...lines.slice(i + 1, j - 1),
        closeLine.slice(0, closeLine.lastIndexOf("}")),
      ];
    const inner = innerRaw
      .map((ln) => String(ln || "").trim())
      .filter((ln) => ln.length > 0 && !ln.startsWith("#"));
    if (inner.length === 0) {
      lines.splice(i, j - i);
      continue;
    }
    i = j;
  }
  return lines;
}

function segmentHasHiddenSetCosmeticTag(segmentLines) {
  const lines = segmentLines || [];
  let i = 0;
  while (i < lines.length) {
    if (!isHiddenEffectBlockStartLine(lines[i])) {
      i += 1;
      continue;
    }
    let j = i;
    let bal = effectLineBraceBalanceDelta(lines[j]);
    j += 1;
    while (j < lines.length && bal > 0) {
      bal += effectLineBraceBalanceDelta(lines[j]);
      j += 1;
    }
    if (bal !== 0) {
      i += 1;
      continue;
    }
    const inner = lines
      .slice(i + 1, j - 1)
      .map((ln) => String(ln || "").trim())
      .filter((ln) => ln.length > 0 && !ln.startsWith("#"));
    if (inner.some((ln) => /^set_cosmetic_tag\s*=/.test(ln))) return true;
    i = j;
  }
  return false;
}

// STANDALONE means at the segment's top level, and this scan has to count braces to know that.
//
// It used to match the first `set_cosmetic_tag` at ANY depth. When the line it found was already nested —
// Millennium Dawn's KOR_ignite_the_rebellion buries one inside
// `hidden_effect = { random_country_with_original_tag = { … set_cosmetic_tag = KOR_REB_S } }` — the
// `alreadyInHidden` test then said "there is a hidden one, so drop the standalone", and the line it dropped
// was that same nested one. The tag was deleted outright: the country changed its ruling party in a civil
// war and kept its old flag and name. 4 focuses across the shipping corpus (vanilla + Millennium Dawn) lose
// a nested tag this way. A top-level tag is wrapped exactly as before.
function wrapStandaloneCosmeticTagInHiddenEffectSegment(segmentLines, bodyIndent) {
  const lines = [...(segmentLines || [])];
  let cosmeticIdx = -1;
  let stemToken = "";
  let depth = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const t = String(lines[i] || "").trim();
    const lineDepth = depth;
    depth += effectLineBraceBalanceDelta(lines[i]);
    if (depth < 0) depth = 0;
    if (lineDepth !== 0) continue;
    const m = t.match(/^set_cosmetic_tag\s*=\s*(.+)$/);
    if (m) {
      cosmeticIdx = i;
      stemToken = String(m[1] || "").trim();
      const hashIdx = stemToken.indexOf("#");
      if (hashIdx >= 0) stemToken = stemToken.slice(0, hashIdx).trim();
      if (stemToken.startsWith('"') && stemToken.endsWith('"') && stemToken.length >= 2) {
        stemToken = stemToken.slice(1, -1).trim();
      } else if (stemToken.startsWith("'") && stemToken.endsWith("'") && stemToken.length >= 2) {
        stemToken = stemToken.slice(1, -1).trim();
      }
      break;
    }
  }
  if (cosmeticIdx < 0) return lines;
  if (!stemToken) {
    return lines.filter((_, j) => j !== cosmeticIdx);
  }
  const alreadyInHidden = segmentHasHiddenSetCosmeticTag(lines);
  const withoutStandalone = lines.filter((_, j) => j !== cosmeticIdx);
  if (alreadyInHidden) return withoutStandalone;
  const innerLine = `${bodyIndent}\t${normalizeLegacyEffectCommand(`set_cosmetic_tag = ${stemToken}`)}`;
  // The anchor this block is placed after must be at the segment's TOP LEVEL as well. Anchoring on a
  // `custom_effect_tooltip` or `add_ideas` nested inside a conditional spliced the new
  // `hidden_effect = { set_cosmetic_tag = … }` INTO that conditional — so the country only changed its
  // flag when the condition held, and the block it was spliced into no longer matched the copy the
  // migration step was trying to retire, which wrote the whole conditional to the file twice.
  // Vanilla's AFG_the_faqirs_revolt is the case; 26 focuses across the corpus.
  const topLevelIdx = [];
  let anchorDepth = 0;
  withoutStandalone.forEach((line, i) => {
    if (anchorDepth === 0) topLevelIdx.push(i);
    anchorDepth += effectLineBraceBalanceDelta(line);
    if (anchorDepth < 0) anchorDepth = 0;
  });
  const atTopLevel = new Set(topLevelIdx);
  let lastTt = -1;
  for (let i = 0; i < withoutStandalone.length; i += 1) {
    if (!atTopLevel.has(i)) continue;
    const t = String(withoutStandalone[i] || "").trim();
    if (/^custom_effect_tooltip\s*=/.test(t)) lastTt = i;
  }
  const block = [`${bodyIndent}hidden_effect = {`, innerLine, `${bodyIndent}}`];
  if (lastTt >= 0) {
    const at = lastTt + 1;
    return [...withoutStandalone.slice(0, at), ...block, ...withoutStandalone.slice(at)];
  }
  let ideaIdx = withoutStandalone.findIndex((line, i) => atTopLevel.has(i) && /^add_ideas\s*=/.test(String(line || "").trim()));
  if (ideaIdx < 0) {
    ideaIdx = withoutStandalone.findIndex((line, i) => atTopLevel.has(i) && /^add_timed_idea\s*=\s*\{/.test(String(line || "").trim()));
  }
  if (ideaIdx < 0) ideaIdx = withoutStandalone.length;
  return [...withoutStandalone.slice(0, ideaIdx), ...block, ...withoutStandalone.slice(ideaIdx)];
}

function processManagedSegmentCosmeticHiddenEffect(segmentLines, bodyIndent, removeKeySet) {
  const rs = removeKeySet instanceof Set ? removeKeySet : new Set();
  let lines = [...(segmentLines || [])];
  if (rs.has("set_cosmetic_tag")) {
    lines = removeAllSetCosmeticTagFromManagedLines(lines);
  } else {
    lines = stripEmptyHiddenEffectBlocksFromSegment(lines);
    lines = wrapStandaloneCosmeticTagInHiddenEffectSegment(lines, bodyIndent);
  }
  return lines;
}

/** Trim-only managed lines: remove all set_cosmetic_tag lines and drop empty hidden_effect wrappers. */
function removeAllSetCosmeticTagFromManagedLines(lines) {
  const arr = [...(lines || [])];
  const out = [];
  let i = 0;
  while (i < arr.length) {
    const t = String(arr[i] || "").trim();
    if (!t) {
      out.push(arr[i]);
      i += 1;
      continue;
    }
    if (!isHiddenEffectBlockStartLine(arr[i])) {
      if (!/^set_cosmetic_tag\s*=/.test(t)) out.push(arr[i]);
      i += 1;
      continue;
    }
    let j = i;
    let bal = effectLineBraceBalanceDelta(arr[j]);
    j += 1;
    while (j < arr.length && bal > 0) {
      bal += effectLineBraceBalanceDelta(arr[j]);
      j += 1;
    }
    if (bal !== 0) {
      out.push(arr[i]);
      i += 1;
      continue;
    }
    const block = arr.slice(i, j);
    const open = block[0];
    const close = block[block.length - 1];
    const innerKept = block.slice(1, -1).filter((ln) => !/^set_cosmetic_tag\s*=/.test(String(ln || "").trim()));
    const innerNonEmpty = innerKept
      .map((ln) => String(ln || "").trim())
      .filter((ln) => ln.length > 0 && !ln.startsWith("#"));
    if (innerNonEmpty.length === 0) {
      i = j;
      continue;
    }
    out.push(open, ...innerKept, close);
    i = j;
  }
  return stripEmptyHiddenEffectBlocksFromSegment(out);
}

/** Trim-only: drop every balanced hidden_effect { ... } block (whole block). */
function removeAllHiddenEffectBlocksFromManagedLines(lines) {
  const arr = [...(lines || [])];
  const out = [];
  let i = 0;
  while (i < arr.length) {
    if (!isHiddenEffectBlockStartLine(arr[i])) {
      out.push(arr[i]);
      i += 1;
      continue;
    }
    let j = i;
    let bal = effectLineBraceBalanceDelta(arr[j]);
    j += 1;
    while (j < arr.length && bal > 0) {
      bal += effectLineBraceBalanceDelta(arr[j]);
      j += 1;
    }
    if (bal !== 0) {
      out.push(arr[i]);
      i += 1;
      continue;
    }
    i = j;
  }
  return out;
}

const MANAGED_EFFECT_ORDER = [
  "add_political_power",
  "add_stability",
  "set_stability",
  "add_war_support",
  "set_war_support",
  "add_army_xp",
  "add_navy_xp",
  "add_air_xp",
  "add_command_power",
  "add_manpower",
  "add_research_slot",
  "add_fuel",
  "set_country_flag",
  "clr_country_flag",
  "add_building_construction",
  "add_extra_state_shared_building_slots",
  "add_offsite_building",
  "add_tech_bonus",
  "add_doctrine_cost_reduction",
  "add_named_threat",
  "add_autonomy_ratio",
  "add_legitimacy",
  "random_core_state",
  "random_owned_state",
  "every_owned_state",
  "any_owned_state",
  "capital_scope",
  "every_state",
  "any_state",
  "all_state",
  "random_state",
  "state_scope",
  "custom_effect_tooltip",
  "hidden_effect",
  "add_to_tech_sharing_group",
  // Keep idea/timed-idea entries near the end so normal effects appear first in tooltip.
  "add_ideas",
  "remove_ideas",
  "add_timed_idea",
  "remove_timed_idea",
];
const MANAGED_EFFECT_ORDER_INDEX = new Map(MANAGED_EFFECT_ORDER.map((k, i) => [k, i]));

function reorderManagedSegmentLines(segmentLines) {
  const arr = Array.isArray(segmentLines) ? segmentLines : [];
  if (arr.length <= 1) return arr;
  const units = [];
  let i = 0;
  while (i < arr.length) {
    const raw = String(arr[i] || "");
    const t = raw.trim();
    if (!t) {
      units.push({ lines: [raw], key: "", idx: units.length });
      i += 1;
      continue;
    }
    const blockKey = detectBlockEffectKey(t);
    if (blockKey || isHiddenEffectBlockStartLine(t)) {
      const effKey = blockKey || "hidden_effect";
      const block = [raw];
      let bal = effectLineBraceBalanceDelta(raw);
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        const nextRaw = String(arr[j] || "");
        block.push(nextRaw);
        bal += effectLineBraceBalanceDelta(nextRaw);
        j += 1;
      }
      if (bal !== 0) {
        units.push({
          lines: [raw],
          key: getEffectCommandKey(t) || effKey,
          idx: units.length,
        });
        i += 1;
        continue;
      }
      i = j;
      units.push({ lines: block, key: effKey, idx: units.length });
      continue;
    }
    units.push({ lines: [raw], key: getEffectCommandKey(t), idx: units.length });
    i += 1;
  }
  units.sort((a, b) => {
    const ar = MANAGED_EFFECT_ORDER_INDEX.has(a.key) ? MANAGED_EFFECT_ORDER_INDEX.get(a.key) : 9999;
    const br = MANAGED_EFFECT_ORDER_INDEX.has(b.key) ? MANAGED_EFFECT_ORDER_INDEX.get(b.key) : 9999;
    if (ar !== br) return ar - br;
    return a.idx - b.idx;
  });
  const getIdeaPairMeta = (unit) => {
    const key = String(unit && unit.key ? unit.key : "");
    const rawLines = unit && Array.isArray(unit.lines) ? unit.lines : [];
    if (!key || rawLines.length === 0) return null;
    if (key === "add_ideas" || key === "remove_ideas" || key === "remove_timed_idea") {
      const m = String(rawLines[0] || "").trim().match(/^[A-Za-z0-9_\.:-]+\s*=\s*([A-Za-z0-9_]+)/);
      if (!m) return null;
      return {
        id: m[1],
        kind: key.startsWith("remove_") ? "remove" : "add",
        timed: key === "remove_timed_idea",
      };
    }
    if (key === "add_timed_idea") {
      let ideaId = "";
      for (let i = 0; i < rawLines.length; i += 1) {
        const im = String(rawLines[i] || "").trim().match(/^idea\s*=\s*([A-Za-z0-9_]+)/);
        if (im) {
          ideaId = im[1];
          break;
        }
      }
      if (!ideaId) return null;
      return { id: ideaId, kind: "add", timed: true };
    }
    return null;
  };

  const isIdeaKey = (k) =>
    k === "add_ideas" || k === "remove_ideas" || k === "add_timed_idea" || k === "remove_timed_idea";

  const nonIdeaUnits = [];
  const ideaUnits = [];
  units.forEach((u) => {
    if (isIdeaKey(String(u.key || ""))) ideaUnits.push(u);
    else nonIdeaUnits.push(u);
  });

  const orderedIdeaUnits = [];
  const used = new Set();
  for (let i = 0; i < ideaUnits.length; i += 1) {
    if (used.has(i)) continue;
    const addMeta = getIdeaPairMeta(ideaUnits[i]);
    if (!addMeta || addMeta.kind !== "add") continue;
    orderedIdeaUnits.push(ideaUnits[i]);
    used.add(i);
    for (let j = 0; j < ideaUnits.length; j += 1) {
      if (used.has(j)) continue;
      const rmMeta = getIdeaPairMeta(ideaUnits[j]);
      if (!rmMeta || rmMeta.kind !== "remove") continue;
      if (rmMeta.id !== addMeta.id) continue;
      if (rmMeta.timed !== addMeta.timed) continue;
      orderedIdeaUnits.push(ideaUnits[j]);
      used.add(j);
    }
  }
  for (let i = 0; i < ideaUnits.length; i += 1) {
    if (!used.has(i)) orderedIdeaUnits.push(ideaUnits[i]);
  }

  return [...nonIdeaUnits, ...orderedIdeaUnits].flatMap((u) => u.lines);
}

function normalizeLegacyEffectCommand(line) {
  const raw = String(line || "");
  const leadMatch = raw.match(/^[ \t]*/);
  const lead = leadMatch ? leadMatch[0] : "";
  const trimmed = raw.trim();
  if (!trimmed) return "";
  const key = getEffectCommandKey(trimmed);
  const mapped = LEGACY_XP_COMMAND_RENAMES.get(key);
  if (!mapped) return `${lead}${trimmed}`;
  return `${lead}${trimmed.replace(new RegExp(`^${key}\\b`), mapped)}`;
}

function findFocusBlockInSource(focusId) {
  if (!parsed || !sourceText || !focusId) return null;
  const focus = getFocusById(focusId);
  if (!focus || focus.blockStart < 0 || focus.blockEnd <= focus.blockStart) return null;
  return {
    start: focus.blockStart,
    end: focus.blockEnd,
    text: sourceText.slice(focus.blockStart, focus.blockEnd),
  };
}

function extractCompletionRewardManagedLines(blockText) {
  const completionRegex = /(^|\n)([ \t]*)completion_reward\s*=\s*\{/g;
  const completionMatch = completionRegex.exec(blockText || "");
  if (!completionMatch) return [];
  const openIndex = blockText.indexOf("{", completionMatch.index);
  const closeIndex = findMatchingBrace(blockText, openIndex);
  if (openIndex === -1 || closeIndex === -1) return [];
  const body = blockText.slice(openIndex + 1, closeIndex).replace(/\r\n/g, "\n");
  const bodyLines = body.split("\n");
  const beginIdx = bodyLines.findIndex((line) => line.trimStart() === FOCUS_EFFECTS_BEGIN_MARK);
  const endIdx = bodyLines.findIndex((line, idx) => idx > beginIdx && line.trimStart() === FOCUS_EFFECTS_END_MARK);

  if (beginIdx >= 0 && endIdx > beginIdx) {
    const rawLines = bodyLines.slice(beginIdx + 1, endIdx);
    // Use unit splitting to keep blocks together as single strings in the Reward Lab list
    return splitIncomingEffectPayload(rawLines).map(unit =>
      unit.lines.map(l => l.trim()).filter(Boolean).join("\n")
    ).filter(s => s.length > 0);
  }

  // HEURISTIC ADOPTION — markers absent, so this completion_reward is the AUTHOR'S, not Nova's.
  //
  // #focus-adoption-decomposes-scoped-rewards — this used to keep only the statements it RECOGNISED, and to
  // decompose a state scope holding several effects into one copy of the scope per effect. Both are lossy,
  // and what it returns is what a later save re-emits, so opening a focus Nova did not write and saving it
  // rewrote the reward from a partial transcript:
  //
  //   every_owned_state = {                          became   every_owned_state = { add_to_variable = { … } }
  //     limit = { is_owned_and_controlled_by = AFG }           every_owned_state = { add_to_variable = { … } }
  //     custom_effect_tooltip = AFG_modify_er_ns_intro         every_owned_state = { add_to_variable = { … } }
  //     add_to_variable = { … }  ×3
  //   }
  //
  // — the `limit` gone, so the effect now applies to every state instead of the filtered ones; the tooltip
  // gone; and the braces no longer matching, which is what made Nova's own pre-save check refuse the save
  // with "Malformed focus block: unmatched brace". Measured by running this extractor and the effect
  // rewriter over every shipping tree: 4,512 of 31,798 vanilla + Millennium Dawn focuses came back broken.
  //
  // Adoption is VERBATIM now: every top-level unit of the body, exactly as written. Re-emitting them
  // reproduces the block, which is the only property that makes adopting someone else's script safe at all.
  // The Reward Lab shows a scope as one entry rather than several, which is the truthful rendering of it.
  const units = splitIncomingEffectPayload(bodyLines);
  const adopted = [];
  units.forEach((unit) => {
    const unitText = unit.lines.map((l) => l.trim()).filter(Boolean).join("\n");
    if (unitText) adopted.push(unitText);
  });

  return adopted;
}

/** Single-line national-idea command parser for managed completion_reward lines. */
function parseNationalIdeaEffectFromManagedLine(trimmedLine) {
  const t = String(trimmedLine || "").trim();
  if (!t) return null;
  let m = t.match(/^add_ideas\s*=\s*([A-Za-z0-9_]+)/);
  if (m) return { kind: "add", timed: false, id: m[1] };
  m = t.match(/^remove_ideas\s*=\s*([A-Za-z0-9_]+)/);
  if (m) return { kind: "remove", timed: false, id: m[1] };
  m = t.match(/^remove_timed_idea\s*=\s*([A-Za-z0-9_]+)/);
  if (m) return { kind: "remove", timed: true, id: m[1] };
  return null;
}

function parseNationalIdeaEffectFromEffectUnit(unit) {
  if (!unit) return null;
  if (unit.kind === "line") {
    return parseNationalIdeaEffectFromManagedLine(String(unit.lines[0] || "").trim());
  }
  if (unit.kind === "block" && unit.key === "add_timed_idea") {
    const timedId = extractTimedIdeaIdFromBlockLines(unit.lines || []);
    if (!timedId) return null;
    return { kind: "add", timed: true, id: timedId };
  }
  return null;
}

function stripManagedLineBodyPrefix(line, bodyIndent) {
  const s = String(line || "");
  const bi = String(bodyIndent || "");
  if (bi && s.startsWith(bi)) return s.slice(bi.length);
  return s.trimStart();
}

function managedLinesForIdeaSanitize(lines, bodyIndent) {
  const bi = String(bodyIndent || "");
  return (Array.isArray(lines) ? lines : [])
    .map((line) => stripManagedLineBodyPrefix(line, bi))
    .filter((line) => String(line || "").trim().length > 0);
}

/**
 * Save-time national-idea cleanup.
 * Rule 1: last intent wins per (timed,id).
 * Rule 2: remove-only lines without a matching add in this managed segment are dropped.
 */
function sanitizeNationalIdeaManagedLinesForSave(trimmedBodies) {
  const bodies = Array.isArray(trimmedBodies)
    ? trimmedBodies.filter((line) => String(line || "").trim().length > 0)
    : [];
  if (bodies.length === 0) return trimmedBodies;
  const units = splitIncomingEffectPayload(bodies);
  if (units.length === 0) return trimmedBodies;
  const lastWinByKey = new Map();
  for (let i = units.length - 1; i >= 0; i -= 1) {
    const meta = parseNationalIdeaEffectFromEffectUnit(units[i]);
    if (!meta) continue;
    const k = `${meta.timed ? 1 : 0}:${meta.id}`;
    if (!lastWinByKey.has(k)) lastWinByKey.set(k, i);
  }
  if (lastWinByKey.size === 0) return trimmedBodies;

  const keptUnits = [];
  for (let i = 0; i < units.length; i += 1) {
    const meta = parseNationalIdeaEffectFromEffectUnit(units[i]);
    if (!meta) {
      keptUnits.push(units[i]);
      continue;
    }
    const k = `${meta.timed ? 1 : 0}:${meta.id}`;
    if (lastWinByKey.get(k) === i) keptUnits.push(units[i]);
  }

  const keptAddKeys = new Set();
  keptUnits.forEach((unit) => {
    const meta = parseNationalIdeaEffectFromEffectUnit(unit);
    if (meta && meta.kind === "add") {
      keptAddKeys.add(`${meta.timed ? 1 : 0}:${meta.id}`);
    }
  });

  return keptUnits.flatMap((unit) => {
    const meta = parseNationalIdeaEffectFromEffectUnit(unit);
    if (!meta) return unit.lines || [];
    if (meta.kind === "remove") {
      const k = `${meta.timed ? 1 : 0}:${meta.id}`;
      if (!keptAddKeys.has(k)) return [];
    }
    return unit.lines || [];
  });
}

/**
 * Merge on-disk managed completion_reward lines with pending removals/edits.
 * Does not run national-idea add/remove collapse, so pruneOrphanQueuedIdeaRemovals
 * can still see raw adds alongside queued remove_ideas before save.
 */
function getMergedManagedEffectLinesBeforeNationalSanitize(focusId) {
  const block = findFocusBlockInSource(focusId);
  const baseLines = block ? extractCompletionRewardManagedLines(block.text) : [];
  const removalKeys = pendingEffectRemovals.get(focusId) || new Set();
  const blockRemovalSigs = pendingEffectBlockRemovals.get(focusId) || [];
  let lines = [...baseLines];
  for (const blockKey of EFFECT_BLOCK_KEYS) {
    if (removalKeys.has(blockKey)) {
      lines = removeEffectBlocksByKeyFromTrimmedLines(lines, blockKey);
    }
  }
  lines = lines.filter((line) => {
    const key = getEffectCommandKey(line);
    if (!key) return true;
    if (removalKeys.has("set_cosmetic_tag") && key === "set_cosmetic_tag") return true;
    return !removalKeys.has(key);
  });
  if (removalKeys.has("set_cosmetic_tag")) {
    lines = removeAllSetCosmeticTagFromManagedLines(lines);
  }
  const { buildings: blockRemovalBuildings, techBonuses: blockRemovalTech, doctrineCosts: blockRemovalDoctrine, diplomacy: blockRemovalDiplomacy, resources: blockRemovalResources } =
    partitionBlockRemovalSigs(blockRemovalSigs);
  lines = removeBuildingBlocksBySignatures(lines, blockRemovalBuildings);
  lines = removeBuildingBlocksBySignatures(lines, blockRemovalResources); // Resources use same block removal logic
  lines = removeDiplomacyBySignatures(lines, blockRemovalDiplomacy);
  lines = removeTechBonusBlocksBySignatures(lines, blockRemovalTech);
  lines = removeDoctrineCostBlocksBySignatures(lines, blockRemovalDoctrine);
  const queued = pendingEffectEdits.get(focusId) || [];
  splitIncomingEffectPayload(queued).forEach((unit) => {
    if (unit.kind === "block" && unit.key === "hidden_effect") {
      lines = removeAllHiddenEffectBlocksFromManagedLines(lines);
      unit.lines.forEach((raw) => {
        const t = String(raw || "").trim();
        if (t) lines.push(t);
      });
      return;
    }
    if (unit.kind === "block" && unit.key && EFFECT_BLOCK_KEYS.has(unit.key)) {
      if (!isMultiInstanceBlockEffectKey(unit.key)) {
        lines = removeEffectBlocksByKeyFromTrimmedLines(lines, unit.key);
      }
      unit.lines.forEach((raw) => {
        const t = String(raw || "").trim();
        if (t) lines.push(t);
      });
      return;
    }
    const trimmed = String(unit.lines[0] || "").trim();
    if (!trimmed) return;
    const key = unit.key;
    if (key && !isMultiInstanceManagedEffectKey(key)) {
      if (key === "set_cosmetic_tag") {
        lines = removeAllSetCosmeticTagFromManagedLines(lines);
      } else {
        lines = lines.filter((existing) => getEffectCommandKey(existing) !== key);
      }
    } else if (lines.includes(trimmed)) {
      return;
    }
    lines.push(trimmed);
  });
  return lines;
}

/** Same national-idea cleanup as Save — UI / validation / tooltips match written file. */
function getEffectiveManagedEffectLines(focusId) {
  const merged = getMergedManagedEffectLinesBeforeNationalSanitize(focusId);
  return sanitizeNationalIdeaManagedLinesForSave(managedLinesForIdeaSanitize(merged, ""));
}

function queueEffectLines(focusId, lines) {
  if (!focusId || !Array.isArray(lines) || lines.length === 0) return;
  if (!getFocusById(focusId)) return;
  markFocusesDirty([focusId]);

  // Normalize and join the incoming lines if they represent a single block unit
  const incoming = lines
    .map((line) => String(line || "").replace(/\r\n/g, "\n"))
    .flatMap((line) => line.split("\n"))
    .map((line) => normalizeLegacyEffectCommand(line))
    .filter((line) => line.length > 0);

  if (incoming.length === 0) return;

  const current = pendingEffectEdits.get(focusId) || [];
  let merged = [...current];
  const priorRemovals = pendingEffectRemovals.get(focusId) || new Set();
  const nextRemovals = new Set(priorRemovals);
  const priorBlockRemovals = pendingEffectBlockRemovals.get(focusId) || [];
  let nextBlockRemovals = [...priorBlockRemovals];

  const seen = new Set(merged.map((line) => String(line).trim()));
  const incomingUnits = splitIncomingEffectPayload(incoming);
  const serializeBlockUnit = (unit) =>
    (unit && Array.isArray(unit.lines) ? unit.lines : [])
      .map((line) => normalizeLegacyEffectCommand(String(line || "").trim()))
      .filter(Boolean)
      .join("\n");
  incomingUnits.forEach((unit) => {
    if (unit.kind === "block" && unit.key === "hidden_effect") {
      merged = removeAllHiddenEffectBlocksFromManagedLines(merged);
      seen.clear();
      merged.forEach((ln) => seen.add(String(ln).trim()));
      unit.lines.forEach((raw) => {
        const s = String(raw || "").trim();
        if (!s) return;
        if (seen.has(s)) return;
        seen.add(s);
        merged.push(raw);
      });
      return;
    }
    if (unit.kind === "block" && unit.key && EFFECT_BLOCK_KEYS.has(unit.key)) {
      const sig = parseBuildingBlockSignatureFromUnit(unit);
      if (sig) {
        nextBlockRemovals = nextBlockRemovals.filter((existing) => !sameBuildingSignature(existing, sig));
      }
      if (unit.key === "add_tech_bonus") {
        const techSig = parseTechBonusSignatureFromUnit(unit);
        if (techSig) {
          nextBlockRemovals = nextBlockRemovals.filter(
            (existing) =>
              !(existing.kind === "tech_bonus" && sameTechBonusSignature(existing, techSig))
          );
        }
      }
      if (unit.key === "add_doctrine_cost_reduction") {
        const docSig = parseDoctrineCostSignatureFromUnit(unit);
        if (docSig) {
          nextBlockRemovals = nextBlockRemovals.filter(
            (existing) =>
              !(existing.kind === "doctrine_cost" && sameDoctrineCostRemovalSignature(existing, docSig))
          );
        }
      }
      if (!isMultiInstanceBlockEffectKey(unit.key)) {
        merged = removeEffectBlocksByKeyFromTrimmedLines(merged, unit.key);
      }
      if (isMultiInstanceBlockEffectKey(unit.key)) {
        const mergedUnits = splitIncomingEffectPayload(merged);
        const incomingSerialized = serializeBlockUnit(unit);
        const exists = mergedUnits.some(
          (existing) =>
            existing.kind === "block" &&
            existing.key === unit.key &&
            serializeBlockUnit(existing) === incomingSerialized
        );
        if (exists) return;
      }
      seen.clear();
      merged.forEach((ln) => seen.add(String(ln).trim()));
      if (nextRemovals.has(unit.key)) nextRemovals.delete(unit.key);
      if (isMultiInstanceBlockEffectKey(unit.key)) {
        const joined = unit.lines.map(l => String(l || "").trim()).join("\n");
        merged.push(joined);
      } else {
        const joined = unit.lines.map(l => String(l || "").trim()).join("\n");
        merged.push(joined);
      }
      return;
    }
    // A multi-line unit that didn't match the EFFECT_BLOCK_KEYS branch above is still a block — e.g.
    // add_autonomy_score = { value = N }, or a state-scope `<id> = { add_core_of = ROOT }` whose key is
    // a NUMBER and so can never be listed in EFFECT_BLOCK_KEYS. Falling through to the single-line path
    // below would push only unit.lines[0] ("add_autonomy_score = {"), dropping the body + closing brace
    // and leaving unbalanced braces that block EVERY save of the focus (the set_technology class bug).
    // Preserve the whole block instead, de-duping single-instance keys like the block branch does.
    if (unit.lines.length > 1) {
      const blockKey = unit.key;
      if (blockKey && !isMultiInstanceBlockEffectKey(blockKey)) {
        merged = removeEffectBlocksByKeyFromTrimmedLines(merged, blockKey);
        seen.clear();
        merged.forEach((ln) => seen.add(String(ln).trim()));
      }
      const joinedBlock = unit.lines.map((l) => String(l || "").trim()).join("\n");
      const trimmedBlock = joinedBlock.trim();
      if (!seen.has(trimmedBlock)) { seen.add(trimmedBlock); merged.push(joinedBlock); }
      return;
    }
    const line = unit.lines[0];
    const key = unit.key;
    if (key && !isMultiInstanceManagedEffectKey(key)) {
      if (key === "set_cosmetic_tag") {
        merged = removeAllSetCosmeticTagFromManagedLines(merged);
        seen.clear();
        merged.forEach((ln) => seen.add(String(ln).trim()));
      } else {
        for (let i = merged.length - 1; i >= 0; i -= 1) {
          if (getEffectCommandKey(merged[i]) === key) {
            seen.delete(String(merged[i]).trim());
            merged.splice(i, 1);
          }
        }
      }
      if (nextRemovals.has(key)) nextRemovals.delete(key);
    }
    const trimmed = String(line || "").trim();
    if (seen.has(trimmed)) {
      return;
    }
    seen.add(trimmed);
    merged.push(line);
  });
  const currentSig = JSON.stringify(current);
  const mergedSig = JSON.stringify(merged);
  const priorRemovalsSig = JSON.stringify([...priorRemovals].sort());
  const nextRemovalsSig = JSON.stringify([...nextRemovals].sort());
  const priorBlockRemovalsSig = JSON.stringify(priorBlockRemovals);
  const nextBlockRemovalsSig = JSON.stringify(nextBlockRemovals);
  if (currentSig === mergedSig && priorRemovalsSig === nextRemovalsSig && priorBlockRemovalsSig === nextBlockRemovalsSig) return;
  pushUndoSnapshot();
  pendingEffectEdits.set(focusId, merged);
  if (nextRemovals.size > 0) pendingEffectRemovals.set(focusId, nextRemovals);
  else pendingEffectRemovals.delete(focusId);
  if (nextBlockRemovals.length > 0) pendingEffectBlockRemovals.set(focusId, nextBlockRemovals);
  else pendingEffectBlockRemovals.delete(focusId);
  markDirty(true);

  // Refresh sidebar if this focus is currently being edited
  if (selectedIds.has(focusId)) {
    const focus = getFocusById(focusId);
    if (focus) updateSidebarContent(focus);
  }
}

function queueEffectRemovalByKey(focusId, commandKey) {
  if (!focusId || !commandKey) return;
  if (!getFocusById(focusId)) return;
  const current = pendingEffectEdits.get(focusId) || [];
  const next = EFFECT_BLOCK_KEYS.has(commandKey)
    ? removeEffectBlocksByKeyFromTrimmedLines(current, commandKey)
    : current.filter((line) => getEffectCommandKey(line) !== commandKey);
  const removeSet = new Set(pendingEffectRemovals.get(focusId) || []);
  const hadQueuedEffect = next.length !== current.length;
  const hadRemovalAlready = removeSet.has(commandKey);
  if (!hadQueuedEffect && hadRemovalAlready) return;
  pushUndoSnapshot();
  if (next.length > 0) pendingEffectEdits.set(focusId, next);
  else pendingEffectEdits.delete(focusId);
  removeSet.add(commandKey);
  pendingEffectRemovals.set(focusId, removeSet);
  markDirty(true);

  // Refresh sidebar if this focus is currently being edited
  if (selectedIds.has(focusId)) {
    const focus = getFocusById(focusId);
    if (focus) updateSidebarContent(focus);
  }
}

function stripQueuedIdeaEntriesById(focusId, ideaId, removeCommand = "") {
  if (!focusId || !ideaId) return false;
  const current = pendingEffectEdits.get(focusId) || [];
  if (!current.length) return false;
  const target = String(ideaId || "").trim();
  const mode = String(removeCommand || "").trim();
  const stripNormal = !mode || mode === "remove_ideas";
  const stripTimed = !mode || mode === "remove_timed_idea";
  const next = [];
  let changed = false;
  for (let i = 0; i < current.length; i += 1) {
    const raw = String(current[i] || "");
    const t = raw.trim();
    if (!t) continue;
    let m = t.match(/^add_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (stripNormal && m && m[1] === target) {
      changed = true;
      continue;
    }
    m = t.match(/^remove_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (stripNormal && m && m[1] === target) {
      changed = true;
      continue;
    }
    m = t.match(/^remove_timed_idea\s*=\s*([A-Za-z0-9_]+)/);
    if (stripTimed && m && m[1] === target) {
      changed = true;
      continue;
    }
    if (stripTimed && /^add_timed_idea\s*=\s*\{/.test(t)) {
      const block = [raw];
      let bal = effectLineBraceBalanceDelta(raw);
      let j = i + 1;
      while (j < current.length && bal > 0) {
        const innerRaw = String(current[j] || "");
        block.push(innerRaw);
        bal += effectLineBraceBalanceDelta(innerRaw);
        j += 1;
      }
      const timedIdeaId = extractTimedIdeaIdFromBlockLines(block);
      if (timedIdeaId === target) {
        changed = true;
        i = j - 1;
        continue;
      }
      next.push(...block);
      i = j - 1;
      continue;
    }
    next.push(raw);
  }
  if (!changed) return false;
  pushUndoSnapshot();
  if (next.length > 0) pendingEffectEdits.set(focusId, next);
  else pendingEffectEdits.delete(focusId);
  markDirty(true);
  return true;
}

function pruneOrphanQueuedIdeaRemovals(focusId) {
  if (!focusId) return false;
  const queued = pendingEffectEdits.get(focusId) || [];
  if (!queued.length) return false;
  const effectiveAdds = new Set();
  const effectiveTimedAdds = new Set();
  const effective = getMergedManagedEffectLinesBeforeNationalSanitize(focusId);
  const arr = Array.isArray(effective) ? effective : [];
  for (let i = 0; i < arr.length; i += 1) {
    const t = String(arr[i] || "").trim();
    if (!t) continue;
    let m = t.match(/^add_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      effectiveAdds.add(m[1]);
      continue;
    }
    if (/^add_timed_idea\s*=\s*\{/.test(t)) {
      let bal = effectLineBraceBalanceDelta(t);
      const block = [t];
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        const inner = String(arr[j] || "").trim();
        block.push(inner);
        bal += effectLineBraceBalanceDelta(inner);
        j += 1;
      }
      const ideaId = extractTimedIdeaIdFromBlockLines(block);
      if (ideaId) effectiveTimedAdds.add(ideaId);
      i = Math.max(i, j - 1);
    }
  }
  const next = [];
  let changed = false;
  for (let i = 0; i < queued.length; i += 1) {
    const raw = String(queued[i] || "");
    const t = raw.trim();
    const mIdea = t.match(/^remove_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (mIdea && !effectiveAdds.has(mIdea[1])) {
      changed = true;
      continue;
    }
    const mTimed = t.match(/^remove_timed_idea\s*=\s*([A-Za-z0-9_]+)/);
    if (mTimed && !effectiveTimedAdds.has(mTimed[1])) {
      changed = true;
      continue;
    }
    next.push(queued[i]);
  }
  if (!changed) return false;
  pushUndoSnapshot();
  if (next.length > 0) pendingEffectEdits.set(focusId, next);
  else pendingEffectEdits.delete(focusId);
  markDirty(true);
  return true;
}

function extractValueFromEffectLine(line, command) {
  const t = String(line || "").split("#")[0].trim();
  if (!t) return "";
  // Simple case: command = value
  const eqIdx = t.indexOf("=");
  if (eqIdx !== -1) {
    const after = t.slice(eqIdx + 1).trim();
    if (!after.startsWith("{")) {
      return after.replace(/"/g, "").split(/\s/)[0];
    }
    // Block case: command = { ... value = X ... }
    const valMatch = t.match(/\bvalue\s*=\s*([^\s#{}]+)/) ||
                    t.match(/\bthreat\s*=\s*([^\s#{}]+)/) ||
                    t.match(/\bpopularity\s*=\s*([^\s#{}]+)/) ||
                    t.match(/\bidea\s*=\s*([^\s#{}]+)/);
    if (valMatch) return valMatch[1].replace(/"/g, "");
  }
  return "";
}

function togglePresetEffectLine(focusId, preset, value) {
  if (!focusId || !preset) return { action: "noop", line: "" };
  const rawValue = String(value || "").trim();
  let lines;
  let lineForStatus;
  if (preset.command === "add_named_threat") {
    const n = Number.parseFloat(rawValue);
    if (!Number.isFinite(n)) return { action: "noop", line: "" };
    const nameToken = n >= 0 ? "focus_editor_world_tension_up" : "focus_editor_world_tension_down";
    lines = [
      "add_named_threat = {",
      `\tthreat = ${n}`,
      `\tname = ${nameToken}`,
      "}",
    ];
    lineForStatus = `add_named_threat ${n >= 0 ? "+" : ""}${n}`;
  } else {
    const line = normalizeLegacyEffectCommand(`${preset.command} = ${rawValue}`);
    lines = [line];
    lineForStatus = line;
    if (preset.command === "add_autonomy_ratio") {
      const n = Number.parseFloat(rawValue);
      if (!Number.isFinite(n)) return { action: "noop", line: "" };
      lines = [
        "add_autonomy_ratio = {",
        `\tvalue = ${n}`,
        "\tlocalization = focus_editor_autonomy_ratio_change",
        "}",
      ];
      lineForStatus = `add_autonomy_ratio ${n >= 0 ? "+" : ""}${n}`;
    }
    if (preset.command === "add_autonomy_score") {
      const n = Number.parseFloat(rawValue);
      if (!Number.isFinite(n)) return { action: "noop", line: "" };
      lines = [
        "add_autonomy_score = {",
        `\tvalue = ${n}`,
        "\tlocalization = focus_editor_autonomy_score_change",
        "}"
      ];
      lineForStatus = `add_autonomy_score ${n >= 0 ? "+" : ""}${n}`;
    }
    if (preset.command === "add_state_core_manual") {
      const stateId = parseInt(rawValue, 10);
      if (isNaN(stateId)) return { action: "noop", line: "" };
      lines = [
        `${stateId} = {`,
        `\tadd_core_of = ROOT`,
        `}`
      ];
      lineForStatus = `Core state ${stateId}`;
    }
    if (preset.command === "add_state_claim_manual") {
      const stateId = parseInt(rawValue, 10);
      if (isNaN(stateId)) return { action: "noop", line: "" };
      lines = [
        `${stateId} = {`,
        `\tadd_claim_by = ROOT`,
        `}`
      ];
      lineForStatus = `Claim state ${stateId}`;
    }
  }
  // Only keys for *this* effect line — do not include dialogPairMode inverse siblings here.
  const toggleKeys = new Set();
  const qk = getPresetQueueCommandKey(preset);
  const cmd = String(preset.command || "");
  if (qk) toggleKeys.add(qk);
  if (cmd) toggleKeys.add(cmd);
  const effective = getEffectiveManagedEffectLines(focusId);
  const keys = collectTopManagedEffectKeys(effective);
  let matchedKey = "";
  toggleKeys.forEach((k) => {
    if (!matchedKey && keys.has(k)) matchedKey = k;
  });

  const hasKey = Boolean(matchedKey);
  const isZero = rawValue === "0" || rawValue === "0.0" || rawValue === "0.00" || rawValue === "0.000";

  if (hasKey) {
    queueEffectRemovalByKey(focusId, matchedKey);
    if (isZero) {
      return { action: "removed", line: lineForStatus };
    }
  }

  if (isZero) {
    // If not in focus and user puts 0, just do nothing
    return { action: "noop", line: "" };
  }

  queueEffectLines(focusId, lines);
  return { action: "added", line: lineForStatus };
}

function collectRemovableIdeasFromEffectiveLines(lines) {
  const adds = new Map();
  const removes = new Set();
  const ideaKey = (id, timed) => `${timed ? "timed" : "normal"}::${id}`;
  const arr = Array.isArray(lines) ? lines : [];
  for (let i = 0; i < arr.length; i += 1) {
    const t = String(arr[i] || "").trim();
    if (!t) continue;
    let m = t.match(/^add_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      adds.set(ideaKey(m[1], false), { id: m[1], removeCommand: "remove_ideas", isTimed: false });
      continue;
    }
    m = t.match(/^remove_ideas\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      removes.add(ideaKey(m[1], false));
      continue;
    }
    if (/^add_timed_idea\s*=\s*\{/.test(t)) {
      let bal = effectLineBraceBalanceDelta(t);
      const block = [t];
      let j = i + 1;
      while (j < arr.length && bal > 0) {
        const inner = String(arr[j] || "").trim();
        block.push(inner);
        bal += effectLineBraceBalanceDelta(inner);
        j += 1;
      }
      const ideaId = extractTimedIdeaIdFromBlockLines(block);
      if (ideaId) adds.set(ideaKey(ideaId, true), { id: ideaId, removeCommand: "remove_timed_idea", isTimed: true });
      i = Math.max(i, j - 1);
      continue;
    }
    m = t.match(/^remove_timed_idea\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      removes.add(ideaKey(m[1], true));
    }
  }
  const out = [];
  adds.forEach((meta, key) => {
    if (removes.has(key)) return;
    out.push({
      ideaId: meta.id,
      removeCommand: meta.removeCommand,
      isTimed: meta.isTimed,
      displayName: localizationMap[meta.id] || meta.id,
    });
  });
  out.sort((a, b) => String(a.displayName).localeCompare(String(b.displayName)));
  return out;
}

function renderIdeaRemoveMenuEntries(focusId) {
  if (!menuIdeaRemoveListEl) return;
  const effective = getEffectiveManagedEffectLines(focusId);
  const entries = collectRemovableIdeasFromEffectiveLines(effective);
  menuIdeaRemoveListEl.innerHTML = "";
  if (!entries.length) {
    const p = document.createElement("p");
    p.className = "effects-menu-title";
    p.textContent = "No detectable national spirits on this focus yet.";
    menuIdeaRemoveListEl.appendChild(p);
    return;
  }
  entries.forEach((entry) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "effects-menu-btn";
    btn.dataset.ideaRemoveId = entry.ideaId;
    btn.dataset.ideaRemoveCommand = entry.removeCommand;
    btn.textContent = entry.isTimed
      ? `Remove Timed National Spirit ${entry.displayName}`
      : `Remove National Spirit ${entry.displayName}`;
    btn.title = `Queue ${entry.removeCommand} = ${entry.ideaId} and remove this spirit from the focus effects.`;
    menuIdeaRemoveListEl.appendChild(btn);
  });
}

function formatEffectStateLabel(stateId) {
  if (!stateId) return "";
  if (/^\d+$/.test(stateId)) return `state ${stateId}`;
  return stateId.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());
}

function collectRemovableBuildingEntriesFromEffectiveLines(lines) {
  const out = [];
  const units = splitIncomingEffectPayload(lines || []);
  units.forEach((unit) => {
    const sig = parseBuildingBlockSignatureFromUnit(unit);
    if (!sig) return;
    const stateLabel = formatEffectStateLabel(sig.stateId);
    const label =
      sig.command === "add_building_construction"
        ? `Remove Building ${sig.type} x${sig.level}${stateLabel ? ` (${stateLabel})` : ""}`
        : sig.command === "add_extra_state_shared_building_slots"
          ? `Remove State Building Slots +${sig.level}${stateLabel ? ` (${stateLabel})` : ""}`
          : `Remove Off-map Building ${sig.type} x${sig.level}`;
    out.push({
      ...sig,
      label,
    });
  });
  out.sort((a, b) => a.label.localeCompare(b.label));
  return out;
}

function renderBuildingRemoveMenuEntries(focusId) {
  if (!menuBuildingRemoveListEl) return;
  const effective = getEffectiveManagedEffectLines(focusId);
  const entries = collectRemovableBuildingEntriesFromEffectiveLines(effective);
  menuBuildingRemoveListEl.innerHTML = "";
  if (!entries.length) {
    const p = document.createElement("p");
    p.className = "effects-menu-title";
    p.textContent = "No detectable building effects on this focus yet.";
    menuBuildingRemoveListEl.appendChild(p);
    return;
  }
  entries.forEach((entry) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "effects-menu-btn";
    btn.dataset.buildingRemoveCommand = entry.command;
    btn.dataset.buildingRemoveType = entry.type;
    btn.dataset.buildingRemoveLevel = String(entry.level || 1);
    btn.dataset.buildingRemoveState = String(entry.stateId || "");
    btn.dataset.buildingRemoveLevelToken = String(entry.levelToken || entry.level || 1);
    btn.dataset.buildingRemoveStateToken = String(entry.stateToken || entry.stateId || "");
    btn.textContent = entry.label;
    btn.title = "Queue removal of this specific building effect block.";
    menuBuildingRemoveListEl.appendChild(btn);
  });
}

function collectRemovableDiplomacyEntriesFromEffectiveLines(lines) {
  const out = [];
  const units = splitIncomingEffectPayload(lines || []);
  const DIP_KEYS = new Set([
    "add_state_claim", "add_state_core", "create_wargoal", "add_to_faction",
    "white_peace", "puppet", "annex_country", "transfer_state", "set_capital", "add_core_of"
  ]);

  units.forEach((unit) => {
    const key = unit.key;
    if (!key || !DIP_KEYS.has(key)) return;

    const preset = EFFECT_PRESETS[key];
    let label = "";
    let target = "";

    if (unit.kind === "block") {
      const targetLine = unit.lines.find(l => l.includes("target ="));
      if (targetLine) {
        target = targetLine.split("=")[1].trim();
      }
    } else {
      const firstLine = String(unit.lines[0] || "");
      const eqIdx = firstLine.indexOf("=");
      if (eqIdx !== -1) {
        target = firstLine.slice(eqIdx + 1).trim();
      }
    }

    // Clean up potential comments or braces
    target = target.replace(/#.*$/, "").replace(/\{.*$/, "").trim();

    const displayTarget = getLocalization(target) || target;
    const actionLabel = preset ? preset.removeLabel || preset.label : key;
    label = `${actionLabel} (${displayTarget})`;

    out.push({
      key,
      target,
      label,
      fullSignature: getCanonicalSignature(unit.lines),
    });
  });
  return out;
}

function renderDiplomacyRemoveMenuEntries(focusId) {
  if (!menuDiplomacyRemoveListEl) return;
  const effective = getEffectiveManagedEffectLines(focusId);
  const entries = collectRemovableDiplomacyEntriesFromEffectiveLines(effective);
  const queuedBlockSigs = pendingEffectBlockRemovals.get(focusId) || [];

  menuDiplomacyRemoveListEl.innerHTML = "";

  const filtered = entries.filter((e) => {
    return !queuedBlockSigs.some((q) => q.kind === "diplomacy" && q.sig === e.fullSignature);
  });

  if (!filtered.length) return;

  const title = document.createElement("p");
  title.className = "effects-menu-title";
  title.textContent = "Current Diplomacy Effects";
  menuDiplomacyRemoveListEl.appendChild(title);

  filtered.forEach((entry) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "effects-menu-btn";
    btn.dataset.diplomacyRemoveKey = entry.key;
    btn.dataset.diplomacyRemoveTarget = entry.target;
    btn.dataset.diplomacyRemoveSig = entry.fullSignature;
    btn.textContent = `Remove ${entry.label}`;
    menuDiplomacyRemoveListEl.appendChild(btn);
  });
}

function collectRemovableResearchBonusEntriesFromEffectiveLines(lines, focusId) {
  const out = [];
  const units = splitIncomingEffectPayload(lines || []);
  units.forEach((unit) => {
    if (unit.kind !== "block" || unit.key !== "add_tech_bonus") return;
    const sig = parseTechBonusSignatureFromUnit(unit);
    if (!sig || !sig.nameToken) return;
    const cat = parseTechBonusCategoryFromUnit(unit);
    let friendly = humanizeResearchBonusCategoryDisplay(cat);
    if (!friendly) friendly = simplifyResearchBonusNameTokenForRemove(focusId, sig.nameToken);
    out.push({
      nameToken: sig.nameToken,
      label: formatResearchBonusRemoveLabel(friendly),
    });
  });
  out.sort((a, b) => String(a.label).localeCompare(String(b.label)));
  return out;
}

