function isPointerStillOnSubmenuAnchorOrPanel(clientX, clientY, anchorEl, panelEl) {
  if (!Number.isFinite(clientX) || !Number.isFinite(clientY)) return false;
  if (!anchorEl || !panelEl) return false;
  const hovered = document.elementFromPoint(clientX, clientY);
  if (!(hovered instanceof Element)) return false;
  return anchorEl.contains(hovered) || panelEl.contains(hovered);
}

function hideIdeaSubmenuOnPointerLeave(ev) {
  if (!ideaEffectsSubmenuEl || !menuAddIdeaBtn) return;
  if (ideaEffectsSubmenuEl.classList.contains("effects-submenu--hidden")) return;
  const next = ev && ev.relatedTarget ? ev.relatedTarget : null;
  if (next && (ideaEffectsSubmenuEl.contains(next) || menuAddIdeaBtn.contains(next))) return;
  const leaveX = ev && Number.isFinite(ev.clientX) ? ev.clientX : NaN;
  const leaveY = ev && Number.isFinite(ev.clientY) ? ev.clientY : NaN;
  clearIdeaSubmenuHideTimer();
  ideaSubmenuHideTimer = window.setTimeout(() => {
    ideaSubmenuHideTimer = 0;
    if (isPointerStillOnSubmenuAnchorOrPanel(leaveX, leaveY, menuAddIdeaBtn, ideaEffectsSubmenuEl)) return;
    showEffectsSubmenu("effects");
  }, IDEA_SUBMENU_HIDE_DELAY_MS);
}

