function openEffectAmountDialog(focusId, presetKey) {
  if (!effectAmountDialogEl || !effectAmountInputEl) return;
  const focus = getFocusById(focusId);
  const preset = EFFECT_PRESETS[presetKey];
  if (!focus || !preset) return;
  setEffectAmountVerifyUiBusy(false);
  effectAmountState = { focusId, presetKey, pairMode: "primary" };
  if (effectAmountTitleEl) effectAmountTitleEl.textContent = preset.label;
  if (effectAmountFocusLabelEl) effectAmountFocusLabelEl.textContent = `Focus: ${focus.id}`;
  if (effectAmountValueLabelEl) {
    effectAmountValueLabelEl.textContent =
      preset.valueLabel || (preset.inputMode === "text" ? "ID" : "Amount");
  }
  if (effectAmountModRootLabelEl) {
    effectAmountModRootLabelEl.textContent =
      preset.secondaryLabel || "Source mod folder (absolute path)";
  }
  const showModRow = Boolean(preset.requiresIdeaModFolder);
  if (effectAmountDialogEl) {
    effectAmountDialogEl.classList.toggle("effect-amount-dialog--idea-verify", showModRow);
  }
  const presetDescRaw =
    typeof preset.dialogDescription === "string" ? String(preset.dialogDescription).trim() : "";
  if (effectAmountPresetDescBlockEl) {
    effectAmountPresetDescBlockEl.classList.toggle("effect-amount-row--hidden", !presetDescRaw);
  }
  if (effectAmountPresetDescEl) {
    effectAmountPresetDescEl.textContent = presetDescRaw;
  }
  if (effectAmountIdeaHintBlockEl) {
    effectAmountIdeaHintBlockEl.classList.toggle("effect-amount-row--hidden", !showModRow);
  }
  if (effectAmountIdeaHintEl) {
    effectAmountIdeaHintEl.textContent = showModRow ? IDEA_EFFECT_DIALOG_HINT : "";
  }
  if (effectAmountIdeaAddWarnEl) {
    effectAmountIdeaAddWarnEl.textContent = showModRow ? IDEA_EFFECT_ADD_NOT_CREATE_WARN : "";
  }
  if (effectAmountFormEl) {
    const describedBy = [];
    if (showModRow && (effectAmountIdeaHintEl || effectAmountIdeaAddWarnEl)) {
      describedBy.push("effectAmountIdeaHint", "effectAmountIdeaAddWarn");
    }
    if (presetDescRaw && effectAmountPresetDescEl) describedBy.push("effectAmountPresetDesc");
    if (describedBy.length) effectAmountFormEl.setAttribute("aria-describedby", describedBy.join(" "));
    else effectAmountFormEl.removeAttribute("aria-describedby");
  }
  if (effectAmountModRootRowEl) {
    effectAmountModRootRowEl.classList.toggle("effect-amount-row--hidden", !showModRow);
  }
  if (effectAmountModRootInputEl) {
    effectAmountModRootInputEl.value = "";
  }
  effectAmountInputEl.type = preset.inputMode === "text" ? "text" : "number";
  if (preset.inputMode === "numeric") {
    effectAmountInputEl.setAttribute("required", "");
  } else {
    effectAmountInputEl.removeAttribute("required");
  }
  let currentVal = "";
  const effective = getEffectiveManagedEffectLines(focusId);
  const qk = getPresetQueueCommandKey(preset);
  const existingLine = effective.find((ln) => {
    const k = getEffectCommandKey(ln);
    return k === qk || k === preset.command;
  });
  if (existingLine) {
    currentVal = extractValueFromEffectLine(existingLine, preset.command);
  }
  effectAmountInputEl.value = (currentVal !== "" && currentVal !== undefined) ? currentVal : (preset.openEmptyDialogInput ? "" : String(preset.defaultValue ?? ""));
  if (preset.requiresIdeaModFolder) {
    effectAmountInputEl.placeholder = IDEA_ID_INPUT_PLACEHOLDER;
    effectAmountInputEl.removeAttribute("min");
    effectAmountInputEl.removeAttribute("max");
    effectAmountInputEl.setAttribute("spellcheck", "false");
    effectAmountInputEl.setAttribute("autocapitalize", "off");
    effectAmountInputEl.setAttribute("dir", "ltr");
  } else {
    effectAmountInputEl.removeAttribute("placeholder");
    effectAmountInputEl.removeAttribute("spellcheck");
    effectAmountInputEl.removeAttribute("autocapitalize");
    effectAmountInputEl.removeAttribute("dir");
    if (preset.inputPlaceholder) {
      effectAmountInputEl.placeholder = String(preset.inputPlaceholder);
      effectAmountInputEl.setAttribute("spellcheck", "false");
      effectAmountInputEl.setAttribute("autocapitalize", "off");
      effectAmountInputEl.setAttribute("dir", "ltr");
    }
  }
  if (preset.inputMode === "text") {
    effectAmountInputEl.removeAttribute("step");
  } else {
    effectAmountInputEl.step = preset.step;
  }
  if (preset.requiresIdeaModFolder) {
    effectAmountInputEl.title =
      preset.inputHint ||
      "Enter the spirit key as it appears in the mod's common/ideas .txt files (before = { ).";
    if (effectAmountModRootInputEl) {
      effectAmountModRootInputEl.title =
        "Absolute path to the mod folder that contains common/ideas (under workspace, workshop, or game install).";
    }
  } else {
    const valueLabel = getPresetValueLabelForPrompt(preset);
    effectAmountInputEl.title =
      preset.inputHint ||
      (preset.inputMode === "text"
        ? `Enter ${valueLabel} for this effect.`
        : "Enter a numeric value for this effect.");
    if (effectAmountModRootInputEl) {
      effectAmountModRootInputEl.removeAttribute("title");
    }
  }
  if (effectAmountApplyBtn) {
    effectAmountApplyBtn.title = preset.requiresIdeaModFolder
      ? "Verify the national spirit in that mod folder, then queue one effect line (Enter also submits)."
      : "Add or update this effect line (Enter also submits).";
  }
  syncEffectAmountPairModeUi();
  try {
    effectAmountDialogEl.showModal();
    requestAnimationFrame(() => {
      if (effectAmountInputEl.hasAttribute("disabled")) {
        if (
          effectAmountPairModeBtn &&
          effectAmountPairModeRowEl &&
          !effectAmountPairModeRowEl.classList.contains("effect-amount-row--hidden")
        ) {
          effectAmountPairModeBtn.focus();
        } else if (effectAmountApplyBtn) {
          effectAmountApplyBtn.focus();
        }
      } else {
        effectAmountInputEl.focus();
        if (String(effectAmountInputEl.value || "").length > 0) {
          effectAmountInputEl.select();
        }
      }
    });
  } catch (_e) {
    console.error("[DEBUG] showModal failed:", _e);
  }
}

