function closeTechBonusWizard() {
  techBonusWizardState = null;
  if (techBonusWizardDialogEl && techBonusWizardDialogEl.open) {
    techBonusWizardDialogEl.close();
  }
}

function parseTechBonusAmount(raw) {
  const s = String(raw || "").trim();
  if (!s) return { ok: false, error: "Enter a research speed bonus (e.g. 0.15 or 15%)." };
  const hadPct = /%\s*$/.test(s);
  const n = parseFloat(s.replace(/%\s*$/, ""));
  if (Number.isNaN(n)) return { ok: false, error: "Bonus must be a number." };
  let v = n;
  // #tech-bonus-percent-under-one — A PERCENT SIGN IS NOT AMBIGUOUS.
  //
  // This used to divide only when v > 1, so "15%" became 0.15 but "1%" stayed 1 — which HOI4 reads as
  // +100% research speed — and "0.5%" stayed 0.5, or +50%. Every percentage at or below 1 went into the
  // mod a hundred times too large, with nothing to notice it by.
  //
  // The input's own placeholder is "0.15 or 15%": a bare number is a factor, a %-suffixed one is a
  // percentage. A bare 0.15 is still left alone, because hadPct is false for it.
  if (hadPct) v /= 100;
  return { ok: true, value: v };
}

function buildTechBonusEffectLines(focusId, categoryToken, bonusValue) {
  const rawCat = String(categoryToken || "").trim();
  const safeCat = rawCat;
  const nameTok = `${focusId}_${safeCat}_bonus`.replace(/[^A-Za-z0-9_]/g, "_").replace(/_+/g, "_");
  const bonusStr = String(Number.isFinite(bonusValue) ? bonusValue : 0);
  return [
    "add_tech_bonus = {",
    `\tname = ${nameTok}`,
    `\tbonus = ${bonusStr}`,
    "\tuses = 1",
    `\tcategory = ${safeCat}`,
    "}",
  ];
}

function normalizeDoctrineCategoryToken(raw) {
  let t = String(raw || "").trim().replace(/[^\w]/g, "_").replace(/_+/g, "_");
  if (!t) return "land_doctrine";
  // Older editor output used CAT_land_doctrine; vanilla uses land_doctrine, air_doctrine, naval_doctrine, etc.
  if (/^CAT_/i.test(t)) {
    const stripped = t.replace(/^CAT_/i, "");
    if (stripped) return stripped;
  }
  return t;
}

function buildDoctrineCostReductionEffectLines(focusId, categoryToken, reductionValue) {
  const safeCat = normalizeDoctrineCategoryToken(categoryToken);
  const nameTok = `${focusId}_${safeCat}_doctrine_cost`.replace(/[^A-Za-z0-9_]/g, "_").replace(/_+/g, "_");
  const reductionStr = String(Number.isFinite(reductionValue) ? reductionValue : 0);
  return [
    "add_doctrine_cost_reduction = {",
    `\tname = ${nameTok}`,
    `\tcost_reduction = ${reductionStr}`,
    "\tuses = 1",
    `\tcategory = ${safeCat}`,
    "}",
  ];
}

function parsePositiveIntAmount(raw, labelText) {
  const s = String(raw || "").trim();
  if (!s) return { ok: false, error: `Enter ${labelText.toLowerCase()}.` };
  const n = Number.parseInt(s, 10);
  if (!Number.isFinite(n) || n <= 0) {
    return { ok: false, error: `${labelText} must be a whole number greater than 0.` };
  }
  return { ok: true, value: n };
}

function buildBuildingConstructionEffectLines(buildingType, amount, stateId) {
  const safeType = String(buildingType || "").trim();
  const level = Number.isFinite(amount) ? amount : 1;
  const state = String(stateId || "").trim();
  const inner = [
    `add_building_construction = {`,
    `	type = ${safeType}`,
    `	level = ${level}`,
    `	instant_build = yes`,
    `}`
  ];
  // #keyless-state-wrapper — WITH NO STATE, DO NOT WRITE A WRAPPER. `${state} = {` with an empty state emits
  // ` = {` — a block with no key. The braces balance, so every guard passes and the file is written, and HOI4
  // cannot parse it. The legacy converter in sanitizeLegacyManagedEffectLines calls this with two arguments.
  //
  // The stateless form is not a compromise: vanilla writes `add_building_construction = { … }` straight into a
  // focus's completion_reward, at country scope, 4,214 times across its own trees.
  //
  // (buildStateBuildingSlotsEffectLines below is deliberately left alone — add_extra_state_shared_building_slots
  // has no country-scope form, so there is nothing valid to write without a state, and its only caller takes
  // one from the wizard's state list.)
  if (!state) return inner;
  return [`${state} = {`, ...inner.map((l) => `	${l}`), `}`];
}

function buildStateBuildingSlotsEffectLines(amount, stateId) {
  const level = Number.isFinite(amount) ? amount : 1;
  const state = String(stateId || "").trim();
  return [
    `${state} = {`,
    `	add_extra_state_shared_building_slots = ${level}`,
    `}`
  ];
}

function buildOffsiteBuildingEffectLines(buildingType, amount) {
  const safeType = String(buildingType || "").trim();
  const level = Number.isFinite(amount) ? amount : 1;
  return [
    "add_offsite_building = {",
    `\ttype = ${safeType}`,
    `\tlevel = ${level}`,
    "}",
  ];
}

function parseTimedIdeaInput(raw) {
  const s = String(raw || "").trim();
  if (!s) return { ok: false, error: "Enter timed idea as: idea_id, days (example: civilian_economy, 180)." };
  const comma = s.match(/^([A-Za-z0-9_]+)\s*,\s*(\d+)$/);
  if (comma) {
    const days = Number.parseInt(comma[2], 10);
    if (days <= 0) return { ok: false, error: "Days must be a positive integer (1 or higher)." };
    return { ok: true, ideaId: comma[1], days };
  }
  const space = s.match(/^([A-Za-z0-9_]+)\s+(\d+)$/);
  if (space) {
    const days = Number.parseInt(space[2], 10);
    if (days <= 0) return { ok: false, error: "Days must be a positive integer (1 or higher)." };
    return { ok: true, ideaId: space[1], days };
  }
  return { ok: false, error: "Use format: idea_id, days (or idea_id days)." };
}

function sanitizeLegacyManagedEffectLines(lines, focusId) {
  const out = [];
  const safeFocusId = String(focusId || "focus").replace(/[^A-Za-z0-9_]/g, "_");
  // Normalise ONE statement. Every branch below rewrites the line it matched, which is why a closing brace
  // sharing that line has to be taken off first and put back after — see the forEach at the end.
  const emitOne = (t) => {
    if (!t) return;
    // This one often renders as broken "Add." tooltip text in focus rewards.
    if (/^add_to_faction_tension\s*=/.test(t)) {
      return;
    }
    let m = t.match(/^add_building_construction\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      out.push(...buildBuildingConstructionEffectLines(m[1], 1));
      return;
    }
    m = t.match(/^add_offsite_building\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      out.push(...buildOffsiteBuildingEffectLines(m[1], 1));
      return;
    }
    m = t.match(/^add_research_bonus\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      out.push(
        "add_tech_bonus = {",
        `\tname = ${safeFocusId}_${m[1]}_bonus`,
        "\tbonus = 0.15",
        "\tuses = 1",
        `\tcategory = ${m[1]}`,
        "}"
      );
      return;
    }
    m = t.match(/^add_doctrine_cost_reduction\s*=\s*([0-9]*\.?[0-9]+)/);
    if (m) {
      const n = Number.parseFloat(m[1]);
      const reduction = Number.isFinite(n) ? n : 0.1;
      out.push(...buildDoctrineCostReductionEffectLines(safeFocusId, "land_doctrine", reduction));
      return;
    }
    m = t.match(/^category\s*=\s*([A-Za-z0-9_]+)/);
    if (m) {
      // `cat_` IS PART OF THE NAME for many real categories — do not strip it.
      //
      // HOI4's declared list (common/technology_tags/00_technology.txt) contains BOTH shapes: `land_doctrine`,
      // `armor` and `artillery` bare, but `cat_light_armor`, `cat_heavy_armor`, `cat_anti_tank`,
      // `cat_heavy_fighter`, `cat_strategic_bomber` and more WITH the prefix. Stripping unconditionally
      // rewrote `category = cat_heavy_armor` to `category = heavy_armor`, which is not a declared category at
      // all — so the add_tech_bonus granted nothing and HOI4 logged an invalid category. Measured: 89
      // occurrences across 22 vanilla focus trees went to zero on a single save, and vanilla's own trees use
      // `category = cat_*` 217 times.
      //
      // …and the UPPERCASE form is not a legacy artifact either. Making the strip case-sensitive assumed
      // `CAT_` could only be older editor output for vanilla's `land_doctrine`. Millennium Dawn declares 157
      // categories whose names begin with a capitalised `CAT_` (in a block it spells `technology_Categories`,
      // which is also why a case-sensitive read of the declarations missed them).
      //
      // Classified against what each mod actually declares: MD has 1,818 uppercase CAT_ values that ARE
      // declared exactly as written and 0 whose stripped form is; vanilla, Road to 56, Old World Blues and
      // Rise of Nations have none at all. There is no case in the corpus where stripping is right, and 1,818
      // where it turns a real category into one that does not exist, so the bonus grants nothing.
      //
      // The value goes back exactly as it came in. Rewriting values on the way past is what caused this
      // twice. #focus-category-cat-prefix-stripped
      out.push(`category = ${m[1]}`);
      return;
    }
    // #flag-block-form-truncated — THE VALUE MAY NOT START A BLOCK. `(\S+)` captured a bare `{` from
    // HOI4's timed form `set_country_flag = { flag = X days = 90 value = 1 }`, which then failed the
    // legal-token test, was rewritten to `_`, collapsed to "" and emitted as `set_country_flag = {` —
    // one open brace, no close, and the whole tree became unsaveable. Millennium Dawn's
    // czech_republic.txt (665 focuses) uses that form 12 times. A block is not a token; it belongs to
    // normalizeLegacyEffectCommand below, like every other block effect.
    m = t.match(/^(set_country_flag|clr_country_flag|set_global_flag|clr_global_flag)\s*=\s*([^\s{]\S*)/);
    if (m) {
      const cmd = m[1];
      const rawTok = m[2];
      // #flag-token-mangled — LEAVE A TOKEN THE GAME ITSELF WRITES ALONE.
      //
      // This chain exists to turn a flag name the GFX-flag wizard imported from a FILENAME into a legal
      // token — hence the image-extension strip on the first line. But it ran on every flag line, and
      // `[^A-Za-z0-9_] -> _` is far narrower than what HOI4 actually accepts: it rewrote
      // `set_country_flag = embargo@PREV` to `embargo_PREV`, which is a different flag, so the matching
      // `has_country_flag` never fires again.
      //
      // `@` is dynamic-scope syntax and the corpora lean on it: 100 of vanilla's 8,393 scalar flag
      // assignments carry one (`warlord_supports_@ROOT`, `NOR_already_asked_a_fascist@PREV`) and 258 of
      // Millennium Dawn's 14,122 (`FC_with_@FROM`, `integrated_@ROOT`). Vanilla also uses `.` (11), and MD
      // additionally uses `[`/`]` variable interpolation (50 each), `-` (14) and `.` (40).
      //
      // This was invisible until the adopted-twice fix landed: the duplicate the old code left in the body
      // still carried the un-mangled form, so the game saw a correct copy. Removing the duplicate exposed it.
      //
      // So sanitise only a token that is NOT already something the game would accept — which is exactly the
      // filename case this was written for.
      const alreadyLegal = /^[A-Za-z0-9_@.\-\[\]]+$/.test(rawTok) && !/\.(tga|dds|png|jpg|jpeg)$/i.test(rawTok);
      const cleaned = alreadyLegal
        ? rawTok
        : rawTok
          .replace(/\.(tga|dds|png|jpg|jpeg)$/i, "")
          .replace(/[^A-Za-z0-9_@.\-\[\]]/g, "_")
          .replace(/_+/g, "_")
          .replace(/^_+|_+$/g, "");
      out.push(`${cmd} = ${cleaned || rawTok}`);
      return;
    }
    out.push(normalizeLegacyEffectCommand(t));
  };
  (Array.isArray(lines) ? lines : []).forEach((raw) => {
    const t0 = String(raw || "").trim();
    if (!t0) return;
    // #legacy-sanitize-eats-a-shared-closing-brace — Clausewitz lets the closing brace share the last
    // statement's line, and Rise of Nations writes it that way:
    //
    //     add_tech_bonus = {
    //         …
    //         category = electronics }
    //
    // Every branch of emitOne normalises by MATCHING a prefix and re-emitting the statement, so the ` }` was
    // simply not carried over. The segment then held one more `{` than `}` and the brace guard refused the
    // save — 20 focuses across four Rise of Nations trees, which could not be saved at all and were given no
    // reason why. Measured over all five installed corpora: vanilla, Millennium Dawn, Road to 56 and Old
    // World Blues have none.
    //
    // Peeled ONLY when the line closes more braces than it opens. `set_country_flag = { flag = X days = 90
    // value = 1 }` is balanced on one line and must reach its own branch whole.
    // …and ONLY when a statement precedes them. A line that is nothing but closing braces has nothing for
    // the branches below to normalise, so peeling it only changed how many lines the unit has — which is what
    // effectUnitCompareLines compares, so the adoption stopped recognising the body copy and wrote the reward
    // twice. RON_Ethiopia.txt's `} } } }` is the shape.
    const _peel = effectLineBraceBalanceDelta(t0) < 0 ? (t0.match(/\}+$/) || [""])[0] : "";
    const closeTail = (_peel && /=/.test(t0.slice(0, t0.length - _peel.length))) ? _peel : "";
    emitOne(closeTail ? t0.slice(0, t0.length - closeTail.length).trim() : t0);
    if (closeTail) out.push(closeTail);
  });
  return out;
}

