    " border:1px solid rgba(88,166,255,0.5); border-radius:6px; cursor:pointer;";
  bar.innerHTML =
    (count > 0 ? `<button type="button" data-sf-eye style="${chipCss}" title="Show/hide the inherited shared-focus ghosts">${sharedFocusesVisible ? "👁" : "🚫"} Shared focuses (${count})</button>` : "") +
    `<button type="button" data-sf-manage style="${chipCss}" title="Enable/disable inherited shared-focus groups, or link your own">⚙ Manage${count === 0 && sharedRefs.length === 0 ? " shared focuses" : ""}</button>`;
  const eye = bar.querySelector("[data-sf-eye]");
