  const hasLegacyManagedSanitizeKeys =
    /(^|\n)[ \t]*add_offsite_building\s*=\s*[A-Za-z0-9_]+/.test(blockText || "") ||
    /(^|\n)[ \t]*add_research_bonus\s*=/.test(blockText || "");
