    const effectUnits = splitIncomingEffectPayload(unitsToUse);
    let normalizedCommandLines = unitsToUse.flatMap(ln => String(ln).split('\n')).map((line) => `${bodyIndent}${normalizeLegacyEffectCommand(line)}`);

    let beginIdx = bodyLines.findIndex((line) => line.trimStart() === FOCUS_EFFECTS_BEGIN_MARK);
    let endIdx = bodyLines.findIndex((line) => line.trimStart() === FOCUS_EFFECTS_END_MARK);
    if (beginIdx >= 0 && lineDepths[beginIdx] !== 0) beginIdx = -1;
    if (endIdx >= 0 && lineDepths[endIdx] !== 0) endIdx = -1;
