window.addEventListener(
  "pointermove",
  (ev) => {
    updateLastZoomAnchorFromClient(ev.clientX, ev.clientY);
    if (prereqLinkState) {
      const pos = clientToCanvasContent(ev.clientX, ev.clientY);
      prereqLinkState.cursorX = pos.x;
      prereqLinkState.cursorY = pos.y;
      renderConnectionLines();
    }
    if (mutexLinkState) {
      const pos = clientToCanvasContent(ev.clientX, ev.clientY);
      mutexLinkState.cursorX = pos.x;
      mutexLinkState.cursorY = pos.y;
      renderConnectionLines();
    }
  },
  { passive: true }
);

if (canvasEl) {
  canvasEl.addEventListener("pointerdown", onCanvasPointerDownCapture, true);
  canvasEl.addEventListener("dblclick", (ev) => {
    if (!parsed) return;
    if (document.querySelector("dialog[open]")) return;
    if (!(ev.target instanceof Element)) return;
    if (ev.target.closest(".node")) return;
    ev.preventDefault();
    const pos = clientToCanvasContent(ev.clientX, ev.clientY);
    const gridX = toGridX(pos.x);
    const gridY = toGridY(pos.y);
    openCreateFocusDialog(gridX, gridY);
  });
  canvasEl.addEventListener("pointerdown", (ev) => {
    if (!(ev.target instanceof Element)) return;
    const node = ev.target.closest(".node");
    if (!node) return;
    const focusId = String(node.getAttribute("data-focus-id") || "").trim();
    if (!focusId) return;
    const focus = getFocusById(focusId);
    if (!focus) return;
    onNodeMouseDown(ev, focus, node);
  });
  canvasEl.addEventListener("contextmenu", (ev) => {
    if (!(ev.target instanceof Element)) return;
    const node = ev.target.closest(".node");
    if (node) {
      ev.preventDefault();
      ev.stopPropagation();
      const id = String(node.getAttribute("data-focus-id") || "").trim();
      if (id) {
        const focus = getFocusById(id);
        if (focus) {
          openEffectsMenu(ev, focus);
        }
      }
    } else {
      ev.preventDefault();
      closeEffectsMenu();
    }
  });
  ensureMarqueeEl();
}

/** Wire up Search and Smooth Zoom logic */
function wireNavigationUi() {
  if (globalFocusSearchEl) {
    globalFocusSearchEl.addEventListener("input", () => {
      const q = globalFocusSearchEl.value.trim().toLowerCase();
      if (!q || !parsed || !focusSearchListEl) {
        if (focusSearchListEl) focusSearchListEl.classList.add("search-results-list--hidden");
        return;
      }
      
      const hits = parsed.focuses.filter(f => {
        const idHit = f.id.toLowerCase().includes(q);
        const locHit = (localizationMap[f.id] && localizationMap[f.id].toLowerCase().includes(q));
        let rewardHit = false;
        if (window.genesisEnabled) {
          const rew = (pendingEffectEdits.get(f.id) || f.reward || []);
          const rewStr = Array.isArray(rew) ? rew.join(" ") : String(rew);
          rewardHit = rewStr.toLowerCase().includes(q);
        }
        return idHit || locHit || rewardHit;
      }).slice(0, 30);
      
      if (hits.length === 0) {
        focusSearchListEl.classList.add("search-results-list--hidden");
        return;
      }

      focusSearchListEl.innerHTML = hits.map(f => {
        const name = getLocalization(f.id) || f.displayName || f.id;
        let rewardHtml = "";
        if (window.genesisEnabled) {
          const rew = (pendingEffectEdits.get(f.id) || f.reward || []);
          const firstEff = Array.isArray(rew) ? rew[0] : rew;
          if (firstEff) {
            const translated = translateHoi4ToEnglish(typeof firstEff === "string" ? firstEff : JSON.stringify(firstEff));
            rewardHtml = `<div class=\"search-result-reward\" style=\"font-size: 10px; color: #8b949e; margin-top: 2px; font-style: italic; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\">${translated}</div>`;
          }
        }
        return `
          <div class="search-result-item" data-focus-id="${f.id}">
            <div class="search-result-name">${name}</div>
            <div class="search-result-id">${f.id}</div>
            ${rewardHtml}
          </div>
        `;
      }).join("");
      
      focusSearchListEl.classList.remove("search-results-list--hidden");
    });

    focusSearchListEl.addEventListener("click", (ev) => {
      const item = ev.target.closest(".search-result-item");
      if (item) {
        const id = item.dataset.focusId;
        if (id) {
          jumpToFocus(id);
          focusSearchListEl.classList.add("search-results-list--hidden");
          globalFocusSearchEl.value = "";
        }
      }
    });

    globalFocusSearchEl.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter") {
        const q = globalFocusSearchEl.value.trim().toLowerCase();
        if (!q || !parsed) return;
        const hit = parsed.focuses.find(f => 
          f.id.toLowerCase() === q || 
          f.id.toLowerCase().includes(q) || 
          (localizationMap[f.id] && localizationMap[f.id].toLowerCase().includes(q))
        );
        if (hit) {
          jumpToFocus(hit.id);
          focusSearchListEl.classList.add("search-results-list--hidden");
          globalFocusSearchEl.value = "";
        }
      } else if (ev.key === "Escape") {
        focusSearchListEl.classList.add("search-results-list--hidden");
      }
    });

    // Close results when clicking outside
    document.addEventListener("click", (ev) => {
      if (!globalFocusSearchEl.contains(ev.target) && !focusSearchListEl.contains(ev.target)) {
        focusSearchListEl.classList.add("search-results-list--hidden");
      }
    });
  }

  // Ctrl+F global listener
  window.addEventListener("keydown", (ev) => {
    if ((ev.ctrlKey || ev.metaKey) && ev.key === "f") {
      if (globalFocusSearchEl) {
        ev.preventDefault();
        globalFocusSearchEl.focus();
        globalFocusSearchEl.select();
      }
    }
  });

  if (canvasScrollEl) {
    // Smooth Zoom-to-Cursor
    canvasScrollEl.addEventListener("wheel", (ev) => {
      if (ev.ctrlKey || ev.metaKey) {
        ev.preventDefault();
        updateLastZoomAnchorFromClient(ev.clientX, ev.clientY);
        const delta = ev.deltaY > 0 ? -ZOOM_STEP : ZOOM_STEP;
        setZoom(viewScale + delta);
      }
    }, { passive: false });
  }
}

function jumpToFocus(id) {
  const focus = getFocusById(id);
  if (!focus || !canvasScrollEl) return;
  
  selectedIds.clear();
  selectedIds.add(id);
  applySelectionClass();
  openSidebarForSelection();

  // Scroll center
  const x = (BASE_OFFSET + viewportShiftX + focus.displayX * GRID_X) * viewScale;
  const y = (BASE_OFFSET + viewportShiftY + focus.displayY * GRID_Y) * viewScale;
  
  const targetL = x - canvasScrollEl.clientWidth / 2 + (64 * viewScale);
  const targetT = y - canvasScrollEl.clientHeight / 2 + (64 * viewScale);
  
  canvasScrollEl.scrollTo({
    left: Math.max(0, targetL),
    top: Math.max(0, targetT),
    behavior: "smooth"
  });
  
  setStatus(`Jumped to ${id}`);
}



