/**
 * What Cancel on a startup wizard should actually do.
 *
 * #wizard-cancel-leaves-the-editor — these Cancel buttons called openStartupChoiceDialog(), whose entire body
 * outside e2e is `window.location.href = "home.html"`. So a button labelled Cancel did not return you to the
 * editor: it navigated the whole page away. And the wizard is reachable ON TOP of a loaded, edited tree —
 * selecting the placeholder row in "Open a country's tree…" calls checkEmptyFocusTreeOverlay(true) — while
 * app.js deliberately skips the beforeunload guard in Electron, which is how Nova ships. So unsaved focus-tree
 * work was thrown away with no prompt.
 *
 * If there is a tree to go back to, Cancel goes back to it. Only when there is genuinely nothing loaded does
 * it fall through to the start choices, which is what that button means on a blank editor.
 */
function cancelWizardBackToEditor() {
  const hasTree = !!(typeof loadedPath !== "undefined" && loadedPath
    && typeof parsed !== "undefined" && parsed && parsed.focuses && parsed.focuses.length > 0);
  if (hasTree) {
    // Drop the forced empty-tree overlay too, or the editor stays hidden behind it.
    const overlay = document.getElementById("emptyTreeOverlay");
    if (overlay) overlay.remove();
    const container = document.querySelector(".canvas-scroll");
    if (container) container.style.overflow = "";
    return;
  }
  openStartupChoiceDialog();
}

