window.addEventListener("keydown", (ev) => {
  if (ev.key === "Escape") {
    closeEffectsMenu();
    dismissTransientDialogsOnEscape();
    cancelPrereqLinkMode(true);
    cancelMutexLinkMode(true);
  }
  const modalDialogOpen = Boolean(document.querySelector("dialog[open]"));
  if (modalDialogOpen) return;
  if (isTypingTarget(document.activeElement)) return;
  if (ev.key === "Delete" || ev.key === "Backspace") {
    if (selectedIds.size > 0) {
      ev.preventDefault();
      openDeleteFocusDialog();
      return;
    }
  }
  if (saveInFlight || loadInFlight) {
    // Prevent history/zoom mutations while critical I/O is active.
    if (
      (ev.ctrlKey && !ev.altKey && !ev.metaKey) ||
      (!ev.ctrlKey && !ev.metaKey && !ev.altKey && (String(ev.key || "").toLowerCase() === "z" || String(ev.key || "").toLowerCase() === "x"))
    ) {
      ev.preventDefault();
    }
    return;
  }
  if (HISTORY_ENABLED && ev.ctrlKey && !ev.altKey && !ev.metaKey) {
    const k = String(ev.key || "").toLowerCase();
    if (k === "z" && ev.shiftKey) {
      ev.preventDefault();
      redoLastChange().catch((err) => setStatus(`Redo failed: ${err.message || err}`, true));
      return;
    }
    if (k === "z") {
      ev.preventDefault();
      undoLastChange().catch((err) => setStatus(`Undo failed: ${err.message || err}`, true));
      return;
    }
    if (k === "y") {
      ev.preventDefault();
      redoLastChange().catch((err) => setStatus(`Redo failed: ${err.message || err}`, true));
      return;
    }
    if (k === "x") {
      // Some users expect Ctrl+X as redo in this editor workflow.
      ev.preventDefault();
      redoLastChange().catch((err) => setStatus(`Redo failed: ${err.message || err}`, true));
      return;
    }
  }
  if (ev.ctrlKey && !ev.altKey && !ev.metaKey) {
    const k = ev.key;
    if (k === "-" || k === "_" || k === "Subtract") {
      ev.preventDefault();
      setZoom(viewScale - ZOOM_STEP);
      return;
    }
    if (k === "+" || k === "=" || k === "Add") {
      ev.preventDefault();
      setZoom(viewScale + ZOOM_STEP);
      return;
    }
    if (k === "0" || k === "Digit0" || ev.code === "Numpad0") {
      ev.preventDefault();
      setZoom(1);
      return;
    }
  }
  const key = String(ev.key || "").toLowerCase();
  if (!ev.ctrlKey && !ev.metaKey && !ev.altKey && key === "z") {
    ev.preventDefault();
    setZoom(viewScale - ZOOM_STEP);
  } else if (!ev.ctrlKey && !ev.metaKey && !ev.altKey && key === "x") {
    ev.preventDefault();
    setZoom(viewScale + ZOOM_STEP);
  }
});

