function sanitizeLocalization(text) {
  if (typeof text !== "string") return text;
  // Remove Paradox color codes (e.g. §Y, §!) and tokens like [ROOT.GetNonIdeologyName].
  // NOTE: this is also used for the EDITABLE sidebar focus name/desc, whose value flows back into
  // the saved localization on edit — so it deliberately does NOT strip digit color codes (§7/§4),
  // to avoid silently dropping them from a re-saved MD focus. For pure DISPLAY labels that must not
  // leak any code, use stripLocDisplayCodes() instead.
  return text
    .replace(/§[A-Za-z!]/g, "")
    .replace(/\[[A-Za-z0-9_\.]+(\s+[A-Za-z0-9_\.]+)*\]/g, "")
    .trim();
}

// DISPLAY-ONLY loc sanitizer: like sanitizeLocalization but also strips digit color codes (§7/§4),
// for read-only labels (focus node titles) where leaking any § is wrong and nothing flows back to a
// saved value. Kept separate from sanitizeLocalization precisely because that one feeds editable fields.
// Delegates to the one canonical implementation (#loc-display-strip in loading-overlay.js). Five
// makers had grown their own near-copy and they disagreed — none stripped $KEY$ references or the
// [?var|%fmt] print form, and the leading punctuation a removed token exposed was left behind.
// DISPLAY ONLY: the editable field and the saved .yml keep the raw value.
function stripLocDisplayCodes(s) {
  if (typeof window !== "undefined" && window.novaStripLocCodes) return window.novaStripLocCodes(s);
  return typeof s === "string" ? s.replace(/§[A-Za-z0-9!]/g, "").trim() : s;
}

function renderSidebarEffectPickerList() {
  const container = document.getElementById("sb-effect-picker-list");
  if (!container) return;
  container.innerHTML = "";

  // Top entry: browse the FULL authoritative effect set (CWTools-derived, ~500+) — the curated
  // presets below are the common ones with wizards, but this opens the complete searchable list
  // so no real effect is out of reach. Scoped to effects (completion_reward holds effects).
  if (window.showNovaTokenPicker) {
    const browse = document.createElement("div");
    browse.className = "sb-effect-picker-item";
    browse.style.cssText = "color:#9fe0ff; font-weight:700;";
    browse.textContent = "📋 Browse all HOI4 commands…";
    browse.title = "Search the full official effect list (not just the presets)";
    browse.addEventListener("click", () => {
      const picker = document.getElementById("sb-effect-picker");
      if (picker) picker.classList.add("sb-hidden");
      window.showNovaTokenPicker({
        allowTabs: ["effects"],
        defaultTab: "effects",
        onPick: (name, block) => addEffectToSelectedFocus(name, block),
      });
    });
    container.appendChild(browse);

    // AI entry: describe the effect in plain English → the AI writes valid HOI4 effects and applies
    // them to the selected focus's completion_reward (so the focus popup has AI, like the CF popup).
    const aiEntry = document.createElement("div");
    aiEntry.className = "sb-effect-picker-item";
    aiEntry.style.cssText = "color:#8ad0ff; font-weight:700;";
    aiEntry.textContent = "✨ Ask the AI to write an effect…";
    aiEntry.title = "Describe what should happen; the AI writes the HOI4 effects";
    aiEntry.addEventListener("click", async () => {
      const picker = document.getElementById("sb-effect-picker");
      if (picker) picker.classList.add("sb-hidden");
      const desc = window.novaPrompt
        ? await window.novaPrompt("Ask the AI to write an effect", "e.g. 'Gives 50 political power and adds 5% stability'")
        : window.prompt("Describe the effect:");
      if (!desc || !desc.trim()) return;
      try {
        const apiKey = localStorage.getItem(GEMINI_API_KEY_STORAGE_KEY) || "";
        let dictionary = {};
        try { dictionary = await (await fetch("./hoi4_dictionary.json")).json(); } catch (_) {}
        const resp = await fetch("/api/ai/logic", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ prompt: desc, dictionary, apiKey, needsScript: true, modPath: localStorage.getItem("activeModPath") || "" }),
        });
        const data = await resp.json();
        if (data.error) throw new Error(data.error);
        if (data.script) await applyAiGeneratedEffects(data.script);
      } catch (err) {
        (window.nbAlert || alert)("AI failed: " + (err && err.message ? err.message : err));
      }
    });
    container.appendChild(aiEntry);
  }

  const query = (sbEffectSearchEl?.value || "").toLowerCase().trim();

  // Categorization mapping - logically grouping for easier search
  const categories = {
    "Politics & Stability": ["add_political_power", "add_stability", "add_war_support", "set_stability", "set_war_support", "add_command_power", "add_legitimacy"],
    "Ideology & National Spirits": ["set_politics", "add_popularity", "add_ideas", "remove_ideas", "add_timed_idea", "activate_decision"],
    "Resources & Industry": ["add_resource", "add_building_construction", "add_offsite_building", "add_extra_state_shared_building_slots", "add_fuel"],
    "Military & Manpower": ["add_manpower", "add_army_experience", "add_navy_experience", "add_air_experience", "add_autonomy_ratio", "add_autonomy_score"],
    "Research & Technology": ["add_research_slot", "add_research_bonus", "add_tech_bonus", "add_doctrine_cost_reduction", "add_to_tech_sharing_group", "set_technology"],
    "Diplomacy & States": ["add_state_claim", "add_state_core", "add_state_core_manual", "add_state_claim_manual", "create_wargoal", "annex_country", "puppet", "transfer_state", "set_capital", "white_peace", "declare_war_on", "guarantee", "give_military_access", "remove_from_faction"],
    "Cosmetic & Events": ["set_cosmetic_tag", "drop_cosmetic_tag", "add_named_threat", "country_event"],
    "Other": []
  };

  // Build items from EFFECT_PRESETS
  const library = [];
  for (const key in EFFECT_PRESETS) {
    const p = EFFECT_PRESETS[key];
    let cat = "Other";
    for (const c in categories) {
      if (categories[c].includes(key)) {
        cat = c;
        break;
      }
    }
    library.push({ key, label: p.label || key, category: cat });
  }

  const filtered = library.filter(item => {
    if (item.key.startsWith("remove_")) return false;
    return item.label.toLowerCase().includes(query) || item.key.toLowerCase().includes(query);
  });

  // Group by category
  const groups = {};
  filtered.forEach(item => {
    if (!groups[item.category]) groups[item.category] = [];
    groups[item.category].push(item);
  });

  for (const cat in groups) {
    const header = document.createElement("div");
    header.className = "sb-picker-header";
    header.textContent = cat;
    container.appendChild(header);

    groups[cat].forEach(item => {
      const div = document.createElement("div");
      div.className = "sb-effect-picker-item";
      div.textContent = sanitizeLocalization(item.label);
      div.title = item.key;
      div.addEventListener("click", () => {
        addEffectToSelectedFocus(item.key);
        const picker = document.getElementById("sb-effect-picker");
        if (picker) picker.classList.add("sb-hidden");
      });
      container.appendChild(div);
    });
  }
}

function addEffectToSelectedFocus(effectKey, isBlock) {
  const [id] = [...selectedIds];
  const focus = (parsed?.focuses || []).find(f => f.id === id);
  if (!focus) return;

  const preset = EFFECT_PRESETS[effectKey];
  if (preset) {
    // If this effect uses a specialized wizard (State Picker, Idea Picker, etc), open it
    if (preset.wizardMode === "idea_picker") {
      const ideaMode = preset.command === "add_timed_idea" ? "timed" : "idea";
      openIdeaPicker(focus.id, ideaMode).catch((err) => {
        const msg = err && err.message ? err.message : String(err);
        setStatus(`National Spirit picker failed: ${msg}`, true);
        dbgError("openIdeaPicker", msg);
      });
      return;
    }
    if (preset.wizardMode) {
      openEffectListWizard(focus.id, preset);
      return;
    }
    // If it requires a simple numeric or text value, open the amount dialog
    if (preset.inputMode === "numeric" || preset.inputMode === "text") {
      openEffectAmountDialog(focus.id, effectKey);
      return;
    }
  }

  // Browse-all can hand us an arbitrary command. A BLOCK command (set_capital, country_event, …) must
  // scaffold braces — `set_capital = yes` is invalid script. Scalars keep the `= yes` placeholder.
  const line = preset
    ? `${preset.command || effectKey} = yes`
    : (isBlock ? `${effectKey} = { }` : `${effectKey} = yes`);

  const current = pendingEffectEdits.get(focus.id) || [];
  const next = [...current, line];
  pendingEffectEdits.set(focus.id, next);

  markDirty(true);
  renderFocuses();
  renderSidebarLists(focus);
  setStatus(`Added ${effectKey} to ${focus.id}.`);
}

function updateDebugStateUI() {
  const snap = collectEditorStateSnapshot();
  if (debugStateJsonEl) debugStateJsonEl.textContent = JSON.stringify(snap, null, 2);

  if (debugStatePendingEl) {
    const lines = [];
    lines.push(`New Focuses: ${snap.pendingNewFocuses}`);
    [...pendingNewFocuses.keys()].forEach(k => lines.push(`  + ${k}`));
    lines.push(`Deleted Blocks: ${snap.pendingDeletedBlocks}`);
    [...pendingDeletedBlocks.keys()].forEach(k => lines.push(`  - ${k}`));
    lines.push(`Effect Edits: ${snap.pendingEffectEditFocuses}`);
    [...pendingEffectEdits.keys()].forEach(k => lines.push(`  * ${k}`));
    debugStatePendingEl.textContent = lines.join("\n");
  }

  if (debugStateActiveEl) {
    const lines = [];
    lines.push(`Total Focuses: ${snap.focusCount}`);
    lines.push(`Selected: ${snap.selectedFocusIds.join(", ")}`);
    lines.push(`Dirty: ${snap.dirty}`);
    lines.push(`Last Action: ${undoHistory.length > 0 ? "Undo available" : "No history"}`);
    debugStateActiveEl.textContent = lines.join("\n");
  }
}

function updateDebugDiagnosticsUI() {
  if (!debugDiagnosticsListEl || !parsed) return;
  const issues = collectValidationIssues(parsed);
  debugDiagnosticsListEl.innerHTML = issues.map(issue => `
    <div class="debug-diag-item debug-diag-item--${issue.level}">
      <strong>${issue.level.toUpperCase()}</strong>: ${issue.message}
    </div>
  `).join("");
}

window.focusEditorDebug.quickFix = () => {
  dbgInfo("Running QuickFix...");
  let healed = 0;
  if (!parsed) return;
  parsed.focuses.forEach(f => {
    const text = sourceText.slice(f.blockStart, f.blockEnd);
    if (text.includes("completion_reward") && !text.includes(FOCUS_EFFECTS_BEGIN_MARK)) {
      dbgWarn(`Focus ${f.id} missing managed markers. Marking for re-emit.`);
      // #force-rewrite-is-internal — forceRewrite here was wiped before the save read it, so "Save to apply"
      // applied nothing.
      f.positionDirty = true;
      healed++;
    }
  });
  if (healed > 0) {
    markDirty(true);
    setStatus(`QuickFix: Healed ${healed} focuses (force-rewrite queued). Save to apply.`);
  } else {
    setStatus("QuickFix: No obvious issues found to auto-fix.");
  }
};

// --- MINIMAP LOGIC ---


function wireMinimap() {

  // Initialize Minimap from storage
  try {
    const savedMinimap = localStorage.getItem("focusEditorMinimapVisible");
    if (savedMinimap !== null) {
      isMinimapVisible = savedMinimap === "1";
      if (minimapContainerEl) {
        minimapContainerEl.style.display = isMinimapVisible ? "flex" : "none";
      }
    }
  } catch (_e) {}

  if (!minimapContainerEl || !minimapCanvasEl) {
    console.warn("[minimap] Elements missing");
    return;
  }
  console.log("[minimap] wireMinimap initialized");

  function initCtx() {
    minimapCanvasEl.width = minimapCanvasEl.clientWidth || 200;
    minimapCanvasEl.height = minimapCanvasEl.clientHeight || 138;
    minimapCtx = minimapCanvasEl.getContext("2d");
  }
  initCtx();

  

  if (minimapCloseBtn) {
    minimapCloseBtn.onclick = function(e) {
      console.log("[minimap] Close clicked");
      e.stopPropagation();
      isMinimapVisible = false;
      minimapContainerEl.classList.add("hidden");
    };
  }

  if (minimapHeaderEl) {
    var mx = 0, my = 0, ix = 0, iy = 0;
    minimapHeaderEl.onpointerdown = function(e) {
      if (e.target === minimapCloseBtn) return;
      console.log("[minimap] Drag start");
      isDraggingMinimap = true;
      mx = e.clientX; my = e.clientY;
      var r = minimapContainerEl.getBoundingClientRect();
      ix = r.left; iy = r.top;
      minimapHeaderEl.setPointerCapture(e.pointerId);
      e.preventDefault();
    };
        minimapHeaderEl.onpointermove = function(e) {
      if (!isDraggingMinimap) return;
      var left = ix + (e.clientX - mx);
      var top = iy + (e.clientY - my);
      
      // Clamp to screen boundaries
      var winW = window.innerWidth;
      var winH = window.innerHeight;
      var rect = minimapContainerEl.getBoundingClientRect();
      left = Math.max(0, Math.min(left, winW - rect.width));
      top = Math.max(0, Math.min(top, winH - rect.height));

      minimapContainerEl.style.left = left + "px";
      minimapContainerEl.style.top = top + "px";
      minimapContainerEl.style.bottom = "auto";
      minimapContainerEl.style.right = "auto";
    };
    minimapHeaderEl.onpointerup = function(e) {
      isDraggingMinimap = false;
      minimapHeaderEl.releasePointerCapture(e.pointerId);
    };
  }

  if (minimapContentEl) {
    minimapContentEl.onpointerdown = function(e) {
      console.log("[minimap] Content clicked/pan");
      isPanningMinimap = true;
      minimapContentEl.setPointerCapture(e.pointerId);
      panFromMinimap(e);
      e.preventDefault();
    };
    minimapContentEl.onpointermove = function(e) {
      if (isPanningMinimap) panFromMinimap(e);
    };
    minimapContentEl.onpointerup = function(e) {
      isPanningMinimap = false;
      minimapContentEl.releasePointerCapture(e.pointerId);
    };
  }

  if (canvasScrollEl) {
    canvasScrollEl.addEventListener("scroll", function() {
      if (isMinimapVisible) updateMinimapViewport();
    }, { passive: true });
  }
}


function toggleMinimap() {
  isMinimapVisible = !isMinimapVisible;
  if (minimapContainerEl) {
    // The close (×) button hides via the `.hidden` class; the toggle used only style.display, so it could
    // never re-show after ×. Keep BOTH in sync so the toolbar button always reopens it.
    minimapContainerEl.classList.toggle("hidden", !isMinimapVisible);
    minimapContainerEl.style.display = isMinimapVisible ? "flex" : "none";
  }
  if (isMinimapVisible) drawMinimap();
  try {
    localStorage.setItem("focusEditorMinimapVisible", isMinimapVisible ? "1" : "0");
  } catch (_e) {}
}

// ── Canvas-size helpers (Settings → Manual Workspace Sizing): current-size display, tight Fit, % scale ──
// The "auto" size is the natural canvas with no override (the 100% baseline). The tree EXTENT is the
// right/bottom pixel edge of the furthest node — the tightest the canvas may be without clipping a focus.
function autoCanvasLogical() {
  if (!parsed || !parsed.stats) return { w: 0, h: 0 };
  return {
    w: Math.round(Math.max(3000, parsed.stats.spanX * GRID_X + BASE_OFFSET * 12)),
    h: Math.round(Math.max(2000, parsed.stats.spanY * GRID_Y + BASE_OFFSET * 12)),
  };
}
function currentCanvasLogical() {
  const a = autoCanvasLogical();
  return { w: Math.round(canvasWidthOverride || a.w), h: Math.round(canvasHeightOverride || a.h) };
}
function focusTreeExtentLogical() {
  if (!parsed || !parsed.stats) return null;
  let right = 0, bottom = 0;
  if (canvasEl) {
    canvasEl.querySelectorAll(".node").forEach((n) => {
      const l = parseFloat(n.style.left) || 0, t = parseFloat(n.style.top) || 0;
      right = Math.max(right, l + n.offsetWidth);
      bottom = Math.max(bottom, t + n.offsetHeight);
    });
  }
  const vs = viewScale || 1;
  // Fallback if no nodes are in the DOM yet (mid-render): parsed bounds + a node footprint (~165×128).
  const fRight = BASE_OFFSET + parsed.stats.spanX * GRID_X + 170;
  const fBottom = BASE_OFFSET + parsed.stats.spanY * GRID_Y + 135;
  return { right: Math.ceil(right > 0 ? right / vs : fRight), bottom: Math.ceil(bottom > 0 ? bottom / vs : fBottom) };
}
function updateCanvasSizeUi() {
  const wIn = document.getElementById("canvasWidthInput");
  const hIn = document.getElementById("canvasHeightInput");
  const scaleIn = document.getElementById("canvasScaleInput");
  const hint = document.getElementById("canvasSizeCurrentHint");
  const cur = currentCanvasLogical();
  const base = autoCanvasLogical();
  const manual = !!(canvasWidthOverride || canvasHeightOverride);
  if (wIn && !canvasWidthOverride && document.activeElement !== wIn) wIn.placeholder = cur.w ? String(cur.w) : "Auto";
  if (hIn && !canvasHeightOverride && document.activeElement !== hIn) hIn.placeholder = cur.h ? String(cur.h) : "Auto";
  if (scaleIn && document.activeElement !== scaleIn) {
    scaleIn.value = (base.w && manual) ? String(Math.round((cur.w / base.w) * 100)) : "";
  }
  if (hint) {
    if (!cur.w) hint.textContent = "Load a focus tree to see its canvas size.";
    else {
      const pct = base.w ? Math.round((cur.w / base.w) * 100) : 100;
      hint.textContent = "Current canvas: " + cur.w + " × " + cur.h + " px" + (manual ? (" — " + pct + "% of the opened size") : " (auto-fit)");
    }
  }
}

function drawMinimap() {
  if (!isMinimapVisible || !minimapCtx || !parsed) return;
  if (!parsed.focuses || parsed.focuses.length === 0) {
    // If empty tree, show a default empty area
    var targetW = 240;
    var targetH = 160;
    minimapContainerEl.style.width = targetW + "px";
    minimapContainerEl.style.height = (targetH + 22) + "px";
    minimapCanvasEl.width = targetW;
    minimapCanvasEl.height = targetH;
    minimapCtx.fillStyle = "#0d1117";
    minimapCtx.fillRect(0, 0, targetW, targetH);
    return;
  }
  
  // ⚠ MINIMAP = a FAITHFUL, scaled-down copy of the REAL canvas (the same element the editor renders into:
  // its size formula is in renderFocusesChunked ~L10670, its node placement in ~L12467). Deriving the
  // minimap from the real canvas element — NOT a separate estimate (the old code used BASE_OFFSET*4 /
  // max(1600,1200) while the real canvas uses BASE_OFFSET*12 / max(3000,2000)) — is what makes the blue
  // viewport box hit every corner, never bleed, and resize when the canvas size (Settings) changes.
  // Aspect-preserving & capped so the minimap never grows to cover the screen.
  var realW = (canvasEl && canvasEl.offsetWidth ? canvasEl.offsetWidth : 3000) / viewScale;
  var realH = (canvasEl && canvasEl.offsetHeight ? canvasEl.offsetHeight : 2000) / viewScale;
  var MM_MAX_W = 240, MM_MAX_H = 320;
  minimapScale = Math.min(MM_MAX_W / realW, MM_MAX_H / realH);
  var targetW = Math.max(1, Math.round(realW * minimapScale));
  var targetH = Math.max(1, Math.round(realH * minimapScale));

  minimapContainerEl.style.width = targetW + "px";
  minimapContainerEl.style.height = (targetH + 22) + "px";

  var canvas = minimapCanvasEl;
  canvas.width = targetW;
  canvas.height = targetH;
  
  minimapCtx.fillStyle = "#0d1117";
  minimapCtx.fillRect(0, 0, canvas.width, canvas.height);

  var minFX = parsed.stats.minX * GRID_X;
  var minFY = parsed.stats.minY * GRID_Y;
  
  // Match the editor's REAL node placement (BASE_OFFSET + viewportShift + grid*GRID, see L12467), scaled —
  // so a node drawn on the minimap sits exactly where the viewport box reports it. (minFX/minFY above are
  // no longer used for the offset, but harmless.)
  minimapOffsetX = (BASE_OFFSET + viewportShiftX) * minimapScale;
  minimapOffsetY = (BASE_OFFSET + viewportShiftY) * minimapScale;

  if (parsed.edges) {
    minimapCtx.lineWidth = 0.5;
    minimapCtx.strokeStyle = "rgba(255, 255, 255, 0.15)";
    for (var i = 0; i < parsed.edges.length; i++) {
      var e = parsed.edges[i];
      var ef = parsed.focuses.find(x => x.id === e.from);
      var et = parsed.focuses.find(x => x.id === e.to);
      if (!ef || !et) continue;
      var x1 = ((ef.displayX !== undefined ? ef.displayX : (ef.x || 0)) * GRID_X) * minimapScale + minimapOffsetX;
      var y1 = ((ef.displayY !== undefined ? ef.displayY : (ef.y || 0)) * GRID_Y) * minimapScale + minimapOffsetY;
      var x2 = ((et.displayX !== undefined ? et.displayX : (et.x || 0)) * GRID_X) * minimapScale + minimapOffsetX;
      var y2 = ((et.displayY !== undefined ? et.displayY : (et.y || 0)) * GRID_Y) * minimapScale + minimapOffsetY;
      minimapCtx.beginPath();
      minimapCtx.moveTo(x1, y1);
      minimapCtx.lineTo(x2, y2);
      minimapCtx.stroke();
    }
  }

  var nw = Math.max(2, 60 * minimapScale);
  var nh = Math.max(2, 40 * minimapScale);
  for (var i = 0; i < parsed.focuses.length; i++) {
    var f = parsed.focuses[i];
    var fx = ((f.displayX !== undefined ? f.displayX : (f.x || 0)) * GRID_X) * minimapScale + minimapOffsetX;
    var fy = ((f.displayY !== undefined ? f.displayY : (f.y || 0)) * GRID_Y) * minimapScale + minimapOffsetY;
    minimapCtx.fillStyle = selectedIds.has(f.id) ? "#58a6ff" : "rgba(139, 148, 158, 0.5)";
    minimapCtx.fillRect(fx - nw / 2, fy - nh / 2, nw, nh);
  }
  // Shared (inherited) focus ghosts — draw them on the minimap too (cyan), so it matches the canvas
  // instead of leaving them off "like ghosts" (#3). Same placement math as the editor (absX/absY grid).
  if (sharedFocusesVisible && sharedFocuses && sharedFocuses.length) {
    minimapCtx.fillStyle = "rgba(88, 166, 255, 0.55)";
    for (var si = 0; si < sharedFocuses.length; si++) {
      var sf = sharedFocuses[si];
      if (sf.absX == null || sf.absY == null) continue;
      var sfx = (sf.absX * GRID_X) * minimapScale + minimapOffsetX;
      var sfy = (sf.absY * GRID_Y) * minimapScale + minimapOffsetY;
      minimapCtx.fillRect(sfx - nw / 2, sfy - nh / 2, nw, nh);
    }
  }
  // The Continuous Focuses panel — draw it on the minimap too (translucent purple, matching its border),
  // so the modder can see WHERE it sits relative to the tree (it was missing from the minimap). Same
  // placement math as the editor: its position is in HOI4 px (1 grid unit = GRID_X/Y px), so px/Y map 1:1
  // onto the grid axis like a focus does. Sized to the live box (collapsed → just the header band).
  if (cfState && cfState.position) {
    var cfp = cfEffectivePosition() || cfState.position; // the position the box is actually drawn at
    var cpx = (cfp.x || 0) * minimapScale + minimapOffsetX;
    var cpy = (cfp.y || 0) * minimapScale + minimapOffsetY;
    var cpw = Math.max(2, CF_BOX_W * minimapScale);
    var cph = Math.max(2, (cfPanelCollapsed ? CF_HEAD_H : CF_BOX_H) * minimapScale);
    minimapCtx.fillStyle = "rgba(192, 132, 252, 0.22)";
    minimapCtx.fillRect(cpx, cpy, cpw, cph);
    minimapCtx.strokeStyle = "rgba(192, 132, 252, 0.85)";
    minimapCtx.lineWidth = 0.75;
    minimapCtx.strokeRect(cpx, cpy, cpw, cph);
  }
  updateMinimapViewport();
}

function updateMinimapViewport() {
  if (!canvasScrollEl || !isMinimapVisible || !minimapViewportEl || !minimapCanvasEl) return;
  // ⚠ The box is the visible window expressed as a FRACTION of the real scrollable canvas, applied as a %
  // of the minimap content (which is a faithful scaled copy of that canvas — see drawMinimap). Driving it
  // straight from scrollWidth/scrollHeight (not a re-derived canvas estimate) is what makes it hit the
  // corners exactly and never bleed: at max scroll, left%+width% == 100%. It also auto-tracks any canvas
  // resize (Settings) because scrollWidth/Height reflect the live canvas. DO NOT reintroduce a separate
  // canvasWFocus estimate here.
  var sw = canvasScrollEl.scrollWidth, sh = canvasScrollEl.scrollHeight;
  if (sw <= 0 || sh <= 0) return;
  var leftFrac = Math.max(0, Math.min(canvasScrollEl.scrollLeft / sw, 1));
  var topFrac = Math.max(0, Math.min(canvasScrollEl.scrollTop / sh, 1));
  var widthFrac = Math.min(canvasScrollEl.clientWidth / sw, 1 - leftFrac);
  var heightFrac = Math.min(canvasScrollEl.clientHeight / sh, 1 - topFrac);

  minimapViewportEl.style.left = (leftFrac * 100) + "%";
  minimapViewportEl.style.top = (topFrac * 100) + "%";
  minimapViewportEl.style.width = (widthFrac * 100) + "%";
  minimapViewportEl.style.height = (heightFrac * 100) + "%";

  minimapViewportEl.style.display = (widthFrac > 0.001 && heightFrac > 0.001) ? "block" : "none";
}

function panFromMinimap(e) {
  if (!parsed || !minimapCanvasEl || !canvasScrollEl) return;
  var rect = minimapCanvasEl.getBoundingClientRect();
  var px = e.clientX - rect.left;
  var py = e.clientY - rect.top;
  var realCenterTargetX = (px - minimapOffsetX) / minimapScale;
  var realCenterTargetY = (py - minimapOffsetY) / minimapScale;
  var viewW = canvasScrollEl.clientWidth;
  var viewH = canvasScrollEl.clientHeight;
  var targetScrollX = (realCenterTargetX + BASE_OFFSET + viewportShiftX) * viewScale - viewW / 2;
  var targetScrollY = (realCenterTargetY + BASE_OFFSET + viewportShiftY) * viewScale - viewH / 2;
  canvasScrollEl.scrollLeft = Math.max(0, targetScrollX);
  canvasScrollEl.scrollTop = Math.max(0, targetScrollY);
}



function wireCanvasSizingUi() {
  const autoExpandSettings = document.getElementById("autoExpandSettingsToggle");
  const wIn = document.getElementById("canvasWidthInput");
  const hIn = document.getElementById("canvasHeightInput");
  const fitBtn = document.getElementById("fitCanvasBtn");

  function setAutoExpand(val) {
    isAutoExpandEnabled = !!val;
    const autoExpandToolbar = document.getElementById("autoExpandToggle");
    if (autoExpandToolbar) autoExpandToolbar.checked = isAutoExpandEnabled;
    if (autoExpandSettings) autoExpandSettings.checked = isAutoExpandEnabled;
    try { localStorage.setItem("focusEditorAutoExpand", isAutoExpandEnabled ? "1" : "0"); } catch(_e) {}
  }

  const persistCanvasOverride = () => {
    try {
      if (canvasWidthOverride) localStorage.setItem("focusEditorCanvasWidth", canvasWidthOverride);
      else localStorage.removeItem("focusEditorCanvasWidth");
      if (canvasHeightOverride) localStorage.setItem("focusEditorCanvasHeight", canvasHeightOverride);
      else localStorage.removeItem("focusEditorCanvasHeight");
    } catch (_e) {}
  };
  const scaleIn = document.getElementById("canvasScaleInput");

  const applyManualSize = (e) => {
    if (!parsed) return;
    const inputEl = e.target;
    // The canvas can't be smaller than the tree's actual pixel extent (else a focus gets clipped).
    const ext = focusTreeExtentLogical() || { right: parsed.stats.spanX * GRID_X + BASE_OFFSET * 4, bottom: parsed.stats.spanY * GRID_Y + BASE_OFFSET * 4 };
    const val = inputEl.value ? parseInt(inputEl.value, 10) : null;
    if (val !== null && isNaN(val)) return;
    if (inputEl === wIn) {
      if (val !== null && val < ext.right) {
        setStatus("Can't shrink width to " + val + "px — the focuses need at least " + ext.right + "px. Use Fit Canvas to Tree for the tightest size.", true);
        inputEl.value = canvasWidthOverride || ""; return;
      }
      canvasWidthOverride = val;
    } else {
      if (val !== null && val < ext.bottom) {
        setStatus("Can't shrink height to " + val + "px — the focuses need at least " + ext.bottom + "px. Use Fit Canvas to Tree for the tightest size.", true);
        inputEl.value = canvasHeightOverride || ""; return;
      }
      canvasHeightOverride = val;
    }
    persistCanvasOverride();
    scheduleRenderFocuses();
    if (typeof drawMinimap === "function") drawMinimap();
    updateCanvasSizeUi();
    setStatus("Canvas size: " + (canvasWidthOverride || "Auto") + " × " + (canvasHeightOverride || "Auto"));
  };

  if (wIn) {
    wIn.onchange = applyManualSize;
    wIn.onkeydown = (e) => { if (e.key === "Enter") { wIn.blur(); applyManualSize({ target: wIn }); } };
  }
  if (hIn) {
    hIn.onchange = applyManualSize;
    hIn.onkeydown = (e) => { if (e.key === "Enter") { hIn.blur(); applyManualSize({ target: hIn }); } };
  }

  // SCALE (%) — 100% = the auto canvas size when the tree was opened. Raising it enlarges the canvas
  // uniformly and persists (it stays at the chosen %, so the modder can see they enlarged it). Increase-only
  // (use Fit / the px boxes to tighten) so it can never shrink below what the focuses need.
  const applyScale = () => {
    if (!parsed) return;
    const base = autoCanvasLogical();
    if (!base.w) return;
    let pct = parseFloat(scaleIn.value);
    if (!pct || isNaN(pct)) {
      canvasWidthOverride = null; canvasHeightOverride = null;
    } else {
      pct = Math.max(100, Math.min(pct, 500));
      scaleIn.value = String(Math.round(pct));
      canvasWidthOverride = Math.round(base.w * pct / 100);
      canvasHeightOverride = Math.round(base.h * pct / 100);
    }
    if (wIn) wIn.value = canvasWidthOverride || "";
    if (hIn) hIn.value = canvasHeightOverride || "";
    persistCanvasOverride();
    scheduleRenderFocuses();
    if (typeof drawMinimap === "function") drawMinimap();
    updateCanvasSizeUi();
    setStatus(canvasWidthOverride ? ("Canvas scaled to " + Math.round(pct) + "% of the opened size.") : "Canvas reset to auto size.");
  };
  if (scaleIn) {
    scaleIn.onchange = applyScale;
    scaleIn.onkeydown = (e) => { if (e.key === "Enter") { scaleIn.blur(); applyScale(); } };
  }

  // Fit Canvas to Tree = shrink the canvas to wrap the tree TIGHTLY with equal margins on every side
  // (left/top are already BASE_OFFSET, so right/bottom = BASE_OFFSET too → no extra empty space).
  if (fitBtn) {
    fitBtn.onclick = () => {
      if (!parsed) { setStatus("Load a focus tree first."); return; }
      const ext = focusTreeExtentLogical();
      if (!ext) return;
      canvasWidthOverride = ext.right + BASE_OFFSET;
      canvasHeightOverride = ext.bottom + BASE_OFFSET;
      if (wIn) wIn.value = String(canvasWidthOverride);
      if (hIn) hIn.value = String(canvasHeightOverride);
      persistCanvasOverride();
      scheduleRenderFocuses();
      if (typeof drawMinimap === "function") drawMinimap();
      updateCanvasSizeUi();
      setStatus("Canvas fit tightly to the tree (" + canvasWidthOverride + " × " + canvasHeightOverride + " px).");
    };
  }

  if (autoExpandSettings) autoExpandSettings.onchange = () => setAutoExpand(autoExpandSettings.checked);

  // Initialize from storage
  try {
    const savedAuto = localStorage.getItem("focusEditorAutoExpand");
    if (savedAuto !== null) setAutoExpand(savedAuto === "1");

    const savedW = localStorage.getItem("focusEditorCanvasWidth");
    const savedH = localStorage.getItem("focusEditorCanvasHeight");
    if (savedW) {
      canvasWidthOverride = parseInt(savedW, 10);
      if (wIn) wIn.value = savedW;
    }
    if (savedH) {
      canvasHeightOverride = parseInt(savedH, 10);
      if (hIn) hIn.value = savedH;
    }
  } catch (_e) {}
  updateCanvasSizeUi();
}





