let hoi4Dictionary = null;
let activeSentence = [];

async function loadHoi4Dictionary() {
  try {
    const response = await fetch("./hoi4_dictionary.json");
    hoi4Dictionary = await response.json();
    console.log("HOI4 Dictionary Loaded:", Object.keys(hoi4Dictionary.commands).length, "commands");
  } catch (e) {
    console.error("Failed to load HOI4 dictionary:", e);
  }
}

function populateApiGrid(words) {
  const grid = document.getElementById("complexApiGrid");
  if (!grid) return;
  grid.innerHTML = "";
  if (words.length === 0) {
    grid.innerHTML = "<div style='color: #484f58; font-style: italic; text-align: center; margin-top: 20px;'>No matching words found.</div>";
    return;
  }
  words.forEach((wordKey) => {
    const cmd = hoi4Dictionary.commands[wordKey];
    if (!cmd) return;
    const btn = document.createElement("button");
    btn.className = "secondary-btn-premium";
    btn.style.textAlign = "left";
    btn.style.padding = "10px";
    btn.style.fontSize = "13px";
    btn.style.borderLeft = "4px solid " + hoi4Dictionary.categories[cmd.category].color;
    const cleanLabel = cmd.label.replace(/\[.*?\]/g, "...");
    btn.innerHTML = "<span style='opacity: 0.6; margin-right: 8px;'>" + hoi4Dictionary.categories[cmd.category].icon + "</span> " + cleanLabel;
    btn.onclick = () => addWordToSentence(wordKey);
    grid.appendChild(btn);
  });
}

function addWordToSentence(wordKey) {
  const cmd = hoi4Dictionary.commands[wordKey];
  activeSentence.push({ key: wordKey, params: {} });
  renderSentence();
  const grid = document.getElementById("complexApiGrid");
  grid.innerHTML = "<div style='color: #484f58; font-style: italic; text-align: center; margin-top: 20px;'>Pick next part of the sentence...</div>";
}

function renderSentence() {
  const workspace = document.getElementById("complexLogicWorkspace");
  if (!workspace) return;
  workspace.innerHTML = "";
  activeSentence.forEach((item, index) => {
    const cmd = hoi4Dictionary.commands[item.key];
    const chip = document.createElement("div");
    chip.style.background = "#1c232d";
    chip.style.border = "1px solid " + hoi4Dictionary.categories[cmd.category].color;
    chip.style.padding = "10px 20px";
    chip.style.borderRadius = "8px";
    chip.style.color = "#f1f5fb";
    chip.style.fontSize = "18px";
    chip.style.display = "flex";
    chip.style.alignItems = "center";
    chip.style.gap = "10px";
    let labelHtml = cmd.label;
    cmd.params.forEach((p) => {
      labelHtml = labelHtml.replace("[" + p.name.toUpperCase() + "]", "<span style='color:" + hoi4Dictionary.categories[cmd.category].color + "; font-weight:bold; border-bottom:1px dashed; cursor:pointer;'>" + p.default + "</span>");
    });
    chip.innerHTML = labelHtml;
    workspace.appendChild(chip);
    if (index < activeSentence.length - 1) {
      const arrow = document.createElement("div");
      arrow.innerHTML = "→";
      arrow.style.color = "#484f58";
      arrow.style.fontSize = "24px";
      workspace.appendChild(arrow);
    }
  });
  const nextBtn = document.createElement("button");
  nextBtn.className = "primary-btn-premium";
  nextBtn.style.padding = "10px 20px";
  nextBtn.style.borderRadius = "30px";
  nextBtn.style.background = "rgba(88, 166, 255, 0.05) !important";
  nextBtn.style.border = "1px dashed #58a6ff";
  nextBtn.style.color = "#58a6ff";
  nextBtn.innerHTML = "+ Next Word";
  nextBtn.onclick = () => showStarters();
  workspace.appendChild(nextBtn);
}

function showStarters() {
  if (!hoi4Dictionary) return;
  const starters = Object.keys(hoi4Dictionary.commands).filter((key) => true);
  populateApiGrid(starters);
}

function startup() {
  console.log("HOI4 Editor: Starting engines...");
  if (typeof wireDebugPanel === "function") wireDebugPanel();
  if (typeof wireCanvasSizingUi === "function") wireCanvasSizingUi();
  if (typeof wireHelpDialog === "function") wireHelpDialog();
  if (typeof wireEffectsUi === "function") wireEffectsUi();
  if (typeof wireCreationUi === "function") wireCreationUi();
  if (typeof wireDetailsUi === "function") wireDetailsUi();
  if (typeof wireNavigationUi === "function") wireNavigationUi();
  if (typeof wireMinimap === "function") wireMinimap();
  window.genesisEnabled = localStorage.getItem("genesisEnabled") !== "false";
  toggleGenesisMode(window.genesisEnabled);
  // Defer the (multi-MB on a big mod) scripted_effects/triggers pull to idle — it only prettifies preview
  // text for custom NAME=yes calls (built-in dicts cover the rest), so it shouldn't compete with the
  // editor's first render. Genesis re-resolves names as you edit once the defs land.
  {
    const _loadDefs = () => { loadGenesisScriptedEffects(); loadGenesisScriptedTriggers(); };
    if (typeof requestIdleCallback === "function") requestIdleCallback(_loadDefs, { timeout: 4000 });
    else setTimeout(_loadDefs, 1200);
  }
  if (typeof syncFocusEditRow === "function") syncFocusEditRow();
  if (typeof updateLocalizationTargetLabel === "function") updateLocalizationTargetLabel();
  if (typeof wireAiLogicLab === "function") wireAiLogicLab();
  if (typeof wireFocusIconPicker === "function") wireFocusIconPicker();
  if (typeof wireAiTriggers === "function") wireAiTriggers();
  loadHoi4Dictionary();
  const startLogicBtn = document.getElementById("complexStarterAddBtn");
  if (startLogicBtn) {
    startLogicBtn.onclick = () => {
      startLogicBtn.style.display = "none";
      showStarters();
    };
  }
  const apiSearch = document.getElementById("complexApiSearch");
  if (apiSearch) {
    apiSearch.oninput = (e) => {
      const term = e.target.value.toLowerCase();
      const filtered = Object.keys(hoi4Dictionary.commands).filter((key) => {
        const cmd = hoi4Dictionary.commands[key];
        return key.toLowerCase().includes(term) || cmd.label.toLowerCase().includes(term);
      });
      populateApiGrid(filtered);
    };
  }
  const cBtn = document.getElementById("sb-add-complex-effect-btn");
  const cDlg = document.getElementById("complexEffectDialog");
  const cClose = document.getElementById("complexEffectCloseBtn");
  if (cBtn && cDlg) {
    cBtn.onclick = (e) => {
      e.preventDefault();
      cDlg.showModal();
    };
  }
  if (cClose && cDlg) {
    cClose.onclick = () => cDlg.close();
  }
  const sBtn = document.getElementById("settingsToggleBtn");
  const sDlg = document.getElementById("settingsDialog");
  const sClose = document.getElementById("settingsCloseBtn");
  const sDone = document.getElementById("settingsDoneBtn");
  if (sBtn && sDlg) {
    sBtn.onclick = (e) => {
      e.preventDefault();
      if (typeof updateCanvasSizeUi === "function") updateCanvasSizeUi(); // refresh current-canvas-size readout
      sDlg.showModal();
    };
  }
  if (sClose && sDlg) {
    sClose.onclick = () => sDlg.close();
  }
  // #inline-handlers-reintroduced — this used to be an inline onchange on the checkbox, which the page's
  // own CSP blocks, so ticking the box did nothing until Done was pressed. Apply it as the markup intended.
  {
    const gTog = document.getElementById("genesisSettingsToggle");
    if (gTog) gTog.addEventListener("change", () => toggleGenesisMode(gTog.checked));
  }
  if (sDone && sDlg) {
    sDone.onclick = () => {
      const checkbox = document.getElementById("genesisSettingsToggle");
      if (checkbox) toggleGenesisMode(checkbox.checked);
      sDlg.close();
    };
  }
  const dBtn = document.getElementById("debugToggleBtn"); // legacy toolbar button (removed from the UI; guarded)
  const dDlg = document.getElementById("debuggerDialog");
  if (dBtn && dDlg) {
    dBtn.onclick = () => dDlg.showModal();
  }
  // The Debug Dock now lives under Settings (it's a dev tool, not a focus-tree control). Open it from there.
  const sDbgBtn = document.getElementById("settingsOpenDebuggerBtn");
  if (sDbgBtn && dDlg) {
    sDbgBtn.onclick = () => { if (sDlg) sDlg.close(); dDlg.showModal(); };
  }
  const mBtn = document.getElementById("minimapToggleBtn");
  if (mBtn && typeof toggleMinimap === "function") {
    mBtn.onclick = () => toggleMinimap();
  }
  const gBtn = document.getElementById("genesis-toggle-btn");
  if (gBtn) {
    gBtn.onclick = () => toggleGenesisMode();
  }
  if (typeof wireSimulatorUi === "function") wireSimulatorUi();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", startup);
} else {
  startup();
}

