function wireAiLogicLab() {
  const genBtn = document.getElementById("ai-logic-generate-btn");
  const inputEl = document.getElementById("ai-logic-input");
  const statusEl = document.getElementById("ai-logic-status");
  const previewContainer = document.getElementById("ai-logic-preview-container");
  const previewEl = document.getElementById("ai-logic-preview");
  if (!genBtn || !inputEl) return;
  genBtn.onclick = async () => {
    const prompt = inputEl.value.trim();
    if (!prompt) return;
    genBtn.disabled = true;
    if (statusEl) {
      statusEl.textContent = "AI is thinking...";
      statusEl.style.display = "block";
    }
    if (previewContainer) previewContainer.style.display = "none";
    try {
      const dictResp = await fetch("./hoi4_dictionary.json");
      const dictionary = await dictResp.json();
      const apiKey = localStorage.getItem(GEMINI_API_KEY_STORAGE_KEY) || "";
      const response = await fetch("/api/ai/logic", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, dictionary, apiKey, modPath: localStorage.getItem("activeModPath") || "" }),
      });
      const data = await response.json();
      if (data.error) throw new Error(data.error);
      if (data.script) {
        if (previewEl && previewContainer) {
          previewEl.textContent = data.script;
          previewContainer.style.display = "block";
        }
        await applyAiGeneratedEffects(data.script);
        inputEl.value = "";
        if (statusEl) statusEl.textContent = "Logic applied!";
      }
    } catch (err) {
      console.error("[AI Logic] Failed:", err);
      if (statusEl) statusEl.textContent = "Error: " + err.message;
    } finally {
      genBtn.disabled = false;
      setTimeout(() => {
        if (statusEl) statusEl.style.display = "none";
      }, 5000);
    }
  };
}

function formatEffectToHoi4(effect, indent = "") {
  const preset = EFFECT_PRESETS[effect.key];
  const cmd = (preset ? preset.command : effect.key) || effect.key;
  if (effect.children && effect.children.length > 0) {
    const childLines = effect.children.map((c) => formatEffectToHoi4(c, indent + "\t")).join("\n");
    if (cmd === "if") {
      const limit = effect.params?.condition || "check = yes";
      return `${indent}if = {\n${indent}\tlimit = { ${limit} }\n${childLines}\n${indent}}`;
    }
    return `${indent}${cmd} = {\n${childLines}\n${indent}}`;
  }
  if (effect.params) {
    const paramsArray = Object.entries(effect.params).map(([k, v]) => `${k} = ${v}`);
    if (paramsArray.length > 1 || preset?.wizardMode === "building_construction") {
      return `${indent}${cmd} = { ${paramsArray.join(" ")} }`;
    }
    const val = Object.values(effect.params)[0];
    return `${indent}${cmd} = ${val}`;
  }
  return `${indent}${cmd} = yes`;
}

function splitHoi4TopLevel(code) {
  if (!code) return [];
  const tokens = [];
  let depth = 0;
  let currentToken = "";
  for (let i = 0; i < code.length; i++) {
    const char = code[i];
    if (char === "{") depth++;
    if (char === "}") {
       depth--;
       currentToken += char;
       if (depth === 0) {
          if (currentToken.trim()) tokens.push(currentToken.trim());
          currentToken = "";
       }
       continue;
    }
    if (depth === 0 && (char === "\n" || char === "\r" || char === ";")) {
      if (currentToken.trim()) tokens.push(currentToken.trim());
      currentToken = "";
    } else {
      currentToken += char;
    }
  }
  if (currentToken.trim()) tokens.push(currentToken.trim());
  return tokens;
}

async function applyAiGeneratedEffects(scriptText) {
  const [id] = [...selectedIds];
  if (!id) {
    // Non-locking modal, not native alert() (which freezes the renderer + can lock inputs).
    showNovaInfoModal("Select a focus first", "Click a focus node on the tree, then apply the AI-generated effects to it.");
    return;
  }
  const focus = (parsed?.focuses || []).find((f) => f.id === id);
  if (!focus) return;
  const newLines = splitHoi4TopLevel(scriptText);
  const current = pendingEffectEdits.get(focus.id) || [];
  pendingEffectEdits.set(focus.id, [...current, ...newLines]);
  markDirty(true);
  renderFocuses();
  renderSidebarLists(focus);
  setStatus("AI generated complex effects for " + focus.id + ".");
}

function wireFocusIconPicker() {
  // The continuous-focus editor is re-rendered on every open, so its Browse button is delegated rather
  // than bound. It reuses the focus-icon picker: a continuous focus takes the same GFX_goal_/GFX_focus_
  // art as an ordinary one, so there is nothing to build a second browser for.
  document.addEventListener("click", (ev) => {
    const btn = ev.target && ev.target.closest && ev.target.closest("#cfEdIconBrowse");
    if (!btn) return;
    ev.preventDefault();
    cfIconPickTarget = true;
    const opener = document.getElementById("selectFocusIconBtn");
    if (opener) opener.click();
  });

  const selectFocusIconBtn = document.getElementById("selectFocusIconBtn");
  const iconPickerModal = document.getElementById("iconPickerModal");
  const iconPickerSearch = document.getElementById("iconPickerSearch");
  const iconPickerGrid = document.getElementById("iconPickerGrid");
  const closeIconPicker = document.getElementById("closeIconPicker");

  if (!selectFocusIconBtn || !iconPickerModal) return;

  let allFocusSprites = null;
  let allFocusSpritesRoot = null;  // which mod allFocusSprites was built for (#picker-cache-never-invalidated)
  let currentFilteredSprites = [];
  let renderedCount = 0;
  // Small first batch + fill-until-scrollable (below). Rendering all sprites fired ~120 DDS→PNG conversions
  // at once via /api/buildings/icon-file (native loading="lazy" is viewport-relative, so it doesn't defer).
  const BATCH_SIZE = 24;

  function renderNextBatch() {
    if (!currentFilteredSprites) return;
    const batch = currentFilteredSprites.slice(renderedCount, renderedCount + BATCH_SIZE);
    const fragment = document.createDocumentFragment();

    batch.forEach(sprite => {
      const itemDiv = document.createElement("div");
      itemDiv.className = "icon-picker-item";
      itemDiv.setAttribute("data-key", sprite.key);

      itemDiv.innerHTML = `
        <img src="/api/buildings/icon-file?path=${encodeURIComponent(sprite.texturefile || '')}" alt="Icon" loading="lazy" style="width: 48px; height: 48px; object-fit: contain; margin-bottom: 8px;" data-fallback="/api/vanilla-ui?rel=gfx/interface/ideas/idea_unknown.dds" />
        <span style="font-size: 10px; color: #8b949e; word-break: break-all; font-family: monospace;">${sprite.key.replace(/^(GFX_focus_|GFX_goal_|GFX_)/i, "")}</span>
      `;

      itemDiv.addEventListener("click", () => {
        const input = document.getElementById("sb-focus-icon");
        if (input) {
          input.value = sprite.key;
          // Apply the exact picked texture straight to the focus (node + preview) instead of the slow
          // resolve-by-key, so it shows instantly and never falls back to "?".
          applyPickedFocusIcon(sprite.key, sprite.texturefile);
        }
        iconPickerModal.style.display = "none";
      });

      fragment.appendChild(itemDiv);
    });

    iconPickerGrid.appendChild(fragment);
    renderedCount += batch.length;
    // Fill just enough to make the grid scrollable (so scroll-to-load-more takes over) — never all at once.
    if (renderedCount < currentFilteredSprites.length && renderedCount < 96 && iconPickerGrid.clientHeight > 0 && iconPickerGrid.scrollHeight <= iconPickerGrid.clientHeight + 40) requestAnimationFrame(renderNextBatch);
  }

  function handleSearch() {
    const val = iconPickerSearch.value.toLowerCase().trim();
    if (!allFocusSprites) return;

    currentFilteredSprites = allFocusSprites.filter(sprite =>
      sprite.key.toLowerCase().includes(val)
    );

    iconPickerGrid.innerHTML = "";
    renderedCount = 0;

    if (currentFilteredSprites.length === 0) {
      iconPickerGrid.innerHTML = `<div style="grid-column: 1/-1; padding: 24px; color: #8b949e; text-align: center;">No icons found.</div>`;
    } else {
      renderNextBatch();
    }
  }

  selectFocusIconBtn.addEventListener("click", async () => {
    iconPickerModal.style.display = "block";
    iconPickerSearch.value = "";

    // #picker-cache-never-invalidated — the list was fetched once per page load and reused forever. It is
    // mod-dependent (13,137 sprites under Millennium Dawn against 3,232 under vanilla), so after switching
    // mods or opening a tree from another one, the browser kept offering the first mod's art. Key on the
    // root it was built for rather than on "have we fetched yet".
    const pickerRoot = inferModRootFromFocusPath(loadedPath) || String(editorActiveRootPath || "").trim();
    if (allFocusSprites !== null && allFocusSpritesRoot === pickerRoot) {
      handleSearch();
      iconPickerGrid.scrollTop = 0;
      return;
    }

    iconPickerGrid.innerHTML = `<div style="grid-column: 1/-1; padding: 24px; color: #8b949e; text-align: center;">Scanning game files for focus icons...</div>`;

    try {
      // Name the mod. Without modPath the endpoint falls back to getActiveRoot(), so the browser could
      // list a different mod's art than the tree being edited — and the Upload button a few lines below
      // already writes to inferModRootFromFocusPath(loadedPath). One dialog, two answers to "which mod".
      const q = pickerRoot ? `?modPath=${encodeURIComponent(pickerRoot)}` : "";
      const res = await fetch(`/api/focus/sprites${q}`);
      const data = await res.json();

      if (!data.sprites || data.sprites.length === 0) {
        allFocusSprites = [];
        allFocusSpritesRoot = pickerRoot;
        // #nova-does-not-find-the-game — "no icons" with no game folder found is the base game's icons not seen, not none
        iconPickerGrid.innerHTML = `<div style="grid-column: 1/-1; padding: 24px; color: #8b949e; text-align: center;">${data.gameFound === false
          ? "No icons found: Nova could not find Hearts of Iron IV on this PC, so the base game's focus icons are missing. Set the game folder on the Home page (Game folder), then reload this page."
          : "No icons found."}</div>`;
        return;
      }

      allFocusSprites = data.sprites;
      allFocusSpritesRoot = pickerRoot;
      handleSearch();
      iconPickerGrid.scrollTop = 0;
    } catch (err) {
      iconPickerGrid.innerHTML = `<div style="grid-column: 1/-1; padding: 24px; color: #f85149; text-align: center;">Error: ${err.message}</div>`;
    }
  });

  iconPickerGrid.addEventListener("scroll", () => {
    if (iconPickerGrid.scrollTop + iconPickerGrid.clientHeight >= iconPickerGrid.scrollHeight - 60) {
      if (renderedCount < currentFilteredSprites.length) {
        renderNextBatch();
      }
    }
  });

  // Upload your own image as the focus icon (PNG/DDS → resized 96×96, written as GFX_focus_<id> in the
  // mod, registered). Mirrors the maker upload flows; reuses /api/upload-gfx (type=focus).
  const uploadFocusIconBtn = document.getElementById("uploadFocusIconBtn");
  const focusIconUploadInput = document.getElementById("focusIconUploadInput");
  const focusIconUploadStatus = document.getElementById("sb-focus-icon-upload-status");
  const setUploadStatus = (msg, color) => { if (focusIconUploadStatus) { focusIconUploadStatus.style.display = msg ? "" : "none"; focusIconUploadStatus.style.color = color || "#8b949e"; focusIconUploadStatus.textContent = msg || ""; } };
  if (uploadFocusIconBtn && focusIconUploadInput) {
    uploadFocusIconBtn.addEventListener("click", () => focusIconUploadInput.click());
    focusIconUploadInput.addEventListener("change", async (e) => {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const modRoot = inferModRootFromFocusPath(loadedPath) || String(editorActiveRootPath || "").trim();
      if (!modRoot) { setUploadStatus("Load a focus tree from your mod first, then upload an icon.", "#f85149"); focusIconUploadInput.value = ""; return; }
      const selId = [...selectedIds][0] || "";
      const baseName = selId || (sbFocusIconEl && sbFocusIconEl.value.replace(/^GFX_focus_/i, "").trim()) || "custom_focus";
      const fd = new FormData();
      fd.append("image", file);
      fd.append("name", baseName);
      fd.append("type", "focus");
      fd.append("modPath", modRoot);
      setUploadStatus("Uploading & converting to DDS…", "#e8a849");
      try {
        const resp = await fetch("/api/upload-gfx", { method: "POST", body: fd });
        const data = await resp.json();
        if (data.error) throw new Error(data.error);
        const key = data.spriteName;
        const input = document.getElementById("sb-focus-icon");
        if (input) { input.value = key; input.dispatchEvent(new Event("input", { bubbles: true })); input.dispatchEvent(new Event("change", { bubbles: true })); }
        if (typeof applyPickedFocusIcon === "function") { try { applyPickedFocusIcon(key, ""); } catch (_) {} }
        const prev = document.getElementById("sb-icon-preview");
        if (prev) { try { prev.src = URL.createObjectURL(file); prev.style.display = "block"; } catch (_) {} }
        setUploadStatus(`Uploaded ✓ — icon set to ${key}`, "#2ea043");
      } catch (err) {
        setUploadStatus("Upload failed: " + (err && err.message ? err.message : err), "#f85149");
      } finally {
        focusIconUploadInput.value = "";
      }
    });
  }

  if (closeIconPicker) {
    closeIconPicker.addEventListener("click", () => {
      iconPickerModal.style.display = "none";
    });
    closeIconPicker.addEventListener("mouseenter", () => {
      closeIconPicker.style.color = "#f85149";
    });
    closeIconPicker.addEventListener("mouseleave", () => {
      closeIconPicker.style.color = "#8b949e";
    });
  }
  
  if (iconPickerSearch) {
    iconPickerSearch.addEventListener("input", handleSearch);
  }

  window.addEventListener("click", (e) => {
    if (e.target === iconPickerModal) {
      iconPickerModal.style.display = "none";
    }
  });

  window.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && iconPickerModal.style.display === "block") {
      iconPickerModal.style.display = "none";
    }
  });
}

function wireAiTriggers() {
  const buttons = document.querySelectorAll(".ai-trigger-gen-btn");
  buttons.forEach(btn => {
    btn.onclick = async () => {
      const targetId = btn.getAttribute("data-target");
      const type = btn.getAttribute("data-type");
      const textarea = document.getElementById(targetId);
      if (!textarea) return;
      
      const isWeight = type === "ai_will_do"; // ai_will_do is a weight block, not a trigger condition
      const desc = await window.showCustomPrompt(
        isWeight ? `Describe WHEN the AI should prioritize this focus` : `Enter description for focus "${type}" conditions`,
        isWeight ? `prioritize heavily if at war; a bit more if fascist` : `Germany has at least 50% stability and is at peace`);
      if (!desc || !desc.trim()) return;
      
      const prevText = btn.textContent;
      btn.disabled = true;
      btn.textContent = "⌛ AI...";
      
      try {
        const apiKey = localStorage.getItem("gemini_api_key") || localStorage.getItem("geminiApiKey") || "";
        const systemPrompt = isWeight ? `You are a Master-Level Hearts of Iron IV (HOI4) Modding AI.
Translate the user's request into the INNER body of a focus 'ai_will_do = { }' weight block — how strongly the AI prioritizes TAKING this focus.
CRITICAL: ONLY output raw HOI4 script. No markdown, no explanations, no chatter.
CRITICAL: DO NOT wrap your output in 'ai_will_do = { }' or 'focus = { }'. Output ONLY the inner contents directly!

### ai_will_do SYNTAX (weights, NOT plain triggers):
- Begin with a base 'factor = N' (base weight; 1 = normal priority, 0 = never take it).
- 'modifier = { factor = N <triggers> }' MULTIPLIES the weight when the triggers are met (factor = 0 disables the focus while met).
- 'modifier = { add = N <triggers> }' ADDS or subtracts a flat amount when the triggers are met.
- Triggers inside a modifier use normal HOI4 syntax: has_war = yes, has_government = fascism, has_stability > 0.5, date > 1938.1.1, has_completed_focus = some_focus, tag = GER, OR = { ... }, NOT = { ... }.
EXAMPLE OUTPUT:
factor = 1
modifier = { factor = 5 has_war = yes }
modifier = { factor = 0 has_government = democratic }` : `You are a Master-Level Hearts of Iron IV (HOI4) Modding AI.
Your ONLY purpose is to translate user requests into 100% flawless, valid, machine-readable HOI4 paradox script for a focus trigger/available condition block.
CRITICAL: ONLY output the raw HOI4 script. No markdown formatting, no explanations, no chatter.
CRITICAL: DO NOT wrap your output in '${type} = { }' or 'focus = { }'. Output ONLY the inner trigger conditions directly!

### ULTIMATE HOI4 TRIGGER SYNTAX CHEAT SHEET:
1. Stability: 'has_stability > 0.50' (values range 0.0 to 1.0).
2. War support: 'has_war_support > 0.50'.
3. Political Power: 'has_political_power > 100'.
4. War Check: 'has_war = yes' or 'has_war = no'.
5. Focus Completion: 'has_completed_focus = focus_id'.
6. Ruling Party Ideology Check: 'has_government = fascism' or 'has_government = communism' or 'has_government = democratic' or 'has_government = neutrality'.
7. Country tag check: 'tag = GER'.
8. Date Check: 'date > 1938.1.1'.
9. Logical operators: 'OR = { ... }', 'AND = { ... }', 'NOT = { ... }'.`;

        const response = await fetch("/api/ai/logic", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ prompt: desc, apiKey, systemPrompt, modPath: localStorage.getItem("activeModPath") || "" }),
        });
        const data = await response.json();
        if (data.error) throw new Error(data.error);
        if (data.script) {
          // #sidebar-removes-outside-undo — THE AI REPLACES THE WHOLE BLOCK, SO SNAPSHOT BEFORE IT DOES.
          //
          // This overwrites a hand-written trigger block wholesale with generated script. It is the most
          // destructive thing on the sidebar: not a character but an entire condition, and the model's
          // answer is non-deterministic, so "just ask again" does not bring the original back.
          //
          // The synthetic input event below runs applySidebarLiveChanges, which snapshots per editing
          // burst keyed on document.activeElement — and the active element here is the ✨ button, not the
          // textarea, so that path cannot stand in for this one. Push explicitly, before the overwrite.
          pushUndoSnapshot();
          textarea.value = data.script.trim();
          textarea.dispatchEvent(new Event("change"));
          textarea.dispatchEvent(new Event("input"));
        }
      } catch (err) {
        showNovaInfoModal("AI couldn’t generate that", '<p style="margin:0;">' + String(err.message || "Unknown error").replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])) + '</p><p style="margin:10px 0 0; color:#a6acd0; font-size:12px;">Try rephrasing, or check your Gemini key on the Home page.</p>', targetId);
      } finally {
        btn.disabled = false;
        btn.textContent = prevText;
      }
    };
  });
}
